/* 平成24年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h24.committeeSessions.push(...[{"id":"h24-20120123-6","meetingId":"h24-cm01","date":"2012年1月23日","dateIso":"2012-01-23","committee":"区民委員会","time":"午後０時５９分～午後３時１４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"山元委員","kind":"質問・要望","question":"１つは、実際、具体的に４社というのはどういうところが申し込みがあったのかというのを教えていただきたいということと。品川荘をやっていらっしゃる東京ケータリングが、そこに決めた理由というか、どういう理由なのかなというのを教えてほしいと求めました。","respondent":"武内地域活動課長","answer":"もう１点は、特に私も１２月になって、区のほうから紹介という形になれば利用する方も安心して利用できるのかな。ゴルフ場の連携だとか、その辺をトータルしまして今回、東京ケータリングという会社に決定させていただきました。","id":"exchange-001"},{"speaker":"山元委員","kind":"質問・要望","question":"そういう学校で使うこともあるかと思うんですが、その辺は今後どのように区としては、対応されるのか。その辺もちょっと教えていただきたいと思うんですけど。","respondent":"武内地域活動課長","answer":"今後も品川区の学校につきましては、光林荘を利用した移動教室、林間学校をそのまま引き続き従来と変わらない方式で利用する予定です。それは責任をもって区の中で調査するということになりますので、その辺はご安心していただければと思います。","id":"exchange-002"},{"speaker":"山元委員","kind":"質問","question":"そうすると、定期的に例えばそういう移動教室が始まる前のある程度何カ月前とかという、何かそういう定期的にはかることというのは予定されているんか尋ねました。","respondent":"武内地域活動課長","answer":"その辺のことは検討しているということで聞いておりますので、その辺は教育委員会のほうで責任をもってやるということは確認しておりますので。そういうことでよろしくお願いします。","id":"exchange-003"},{"speaker":"藤原委員","kind":"質問","question":"３の新しいこの８施設なんですけれども、区として一般料金と優待料金の差を補助するというのでいいんか尋ねました。","respondent":"武内地域活動課長","answer":"こちらにあります平日の一般料金、優待料金というのは、区のほうの補助は一切しません。若干金額的なものを企業努力の中で進めていただいている額でございまして、区のほうはこの辺の補助的なものは一切考えておりません。","id":"exchange-004"},{"speaker":"藤原委員","kind":"意見","question":"そうすると、丸得というか、この東京ケータリングを頼んだ結果、こういう形でできたということで、区の予算が使われないということですよね。品川荘、光林荘なんですけれども、年間で大体延べ人数でどのぐらい来るか、予想はしていますかとの意見を述べました。","respondent":"武内地域活動課長","answer":"３月にありますけれども、４,０００円という補助金額になりますので約５,０００万円ぐらいの予算計上を提出させていただいているところです。補助金ですので、また補正等でご審議いただくようになると思いますけれども、一応今の段階ではそういう人数の想定をしています。","id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"そうすると、今までのシステムと、こういうふうに変えて、結局予算ベースで言うと、どのぐらいマイナスになっているんでしょうか。それとは別ですけれども、今までのシステムを変えたわけですから、お金的にはどのぐらいマイナスになったか説明を求めました。","respondent":"武内地域活動課長","answer":"今、実質的には８,６００万円ですかね、ですから約６６.８％マイナスになるというような金額の想定をさせていただいています。経済性、効率性を考えますと、かなり圧縮できている部分があるのかなというふうには考えております。","id":"exchange-006"},{"speaker":"本多委員","kind":"質問","question":"今までだったら、品川区の歳入に入ったかと思うんですが、これからはどういう取り扱いになるのか。それを説明を求めました。","respondent":"武内地域活動課長","answer":"それは基本的には民間事業者の運営するための利用になるということで、それが１年間収支しまして黒字に転じるということも当然ありますね。その場合については、その黒字になった金額の５割を区のほうに歳入としていただくという契約で考えております。","id":"exchange-007"},{"speaker":"本多委員","kind":"質問","question":"それと、補助金を出しているところで、料金のところですね。この方たちが例えば２人で１室借りる場合でも、やはりこの２,１００円というのは割増になってきちゃうんか尋ねました。","respondent":"武内地域活動課長","answer":"委員言われるとおり、３人で利用したときの金額でありますので、それを２人でという場合については割増は通常どおりの割増をいただくということになります。","id":"exchange-008"},{"speaker":"石田副委員長","kind":"質問・要望","question":"そういった部分を把握していただきたいと思うんですが、その点、どのように考えているのか。３点あわせてお願いします。","respondent":"武内地域活動課長","answer":"利用料金の５％引きというようなことを東京ケータリングがやる予定で、それで、従来と同じようにバスで品川区内まで迎えにくる。変更等で直近で変更だとかという部分については、あいていない場合については、それは申し込みされた方というふうに考えております。","id":"exchange-009"},{"speaker":"石田副委員長","kind":"質問・要望","question":"これは要望で終わります。再度ご答弁をお願いします。","respondent":"武内地域活動課長","answer":"従来から、要するに学校が使わないときは一般区民に開放するということをやっておりますので、それは従来と変わらないことだと認識しています。","id":"exchange-010"}]},{"id":"topic-02","title":"行政視察の報告書","agenda":"行政視察の報告書","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"教えてもらいたいんですけれども、京浜工業地帯発祥の地大崎となっていますけれども、これはどうしてかというのをお伺いしたいのと。もう１点は、お金を助成する、差し上げるわけじゃないか尋ねました。","respondent":"福島ものづくり・経営支援課長","answer":"ここには品川区の企業以外にも呼びかけますので、ほかの全都ですとか、あるいは全国に向けて発信できればというふうに思ってあります。それをもとにさらにその企業が発展し、また、品川区自体も品川区の産業が発展し続ければというふうに考えているところです。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問","question":"もうやられていると思うんですけれども、いわゆる助成している、助成の施策というのも何年かやっているじゃないですか。実際にこういうフェアで果実というか、出てきている例というのは実際問題あるんか尋ねました。","respondent":"福島ものづくり・経営支援課長","answer":"あそこがこういうのを開発しているのなら、うちも頼みたいというようなこともありましたし、それ以外にも来た人と商談が成立した。そういう事例もありますので、こちら、参加する企業については十分役立っているのではないかというふうに思ってあります。","id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"１つの産業振興というときに、私の感覚だと、工業よりも商業のほうに力を入れていたという思いが私はあったんですね。せっかくこう２つの課に分かれてやられているわけですから、工業に対する支援というのはどういうふうに考えているか、改めてお伺いしたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"２つの課になってから、両課とも事業を増やし、あるいは支援策を増やし、あるいはさまざまな形にかえ両方の支援を行ってきたところです。今後もそういった企画を強め、さらなるものづくり事業に対する支援等を行っていきたいというふうに考えてあります。","id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/118408?Template=document&Id=2626#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":18642,"voices":53}},{"id":"h24-20120123-7","meetingId":"h24-cm01","date":"2012年1月23日","dateIso":"2012-01-23","committee":"厚生委員会","time":"午後１時００分～午後３時２０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件整理しています。","topics":[{"id":"topic-01","title":"杜松小学校跡高齢者福祉施設等の運営事業者の選定","agenda":"杜松小学校跡高齢者福祉施設等の運営事業者の選定","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"それから、(7)の緊急対応室というのは、常に開けておくのか。緊急対応は、結構利用される方が多いと聞いているんですけれども、需要はどれぐらいあるのかというのを、ちょっとお聞きしたいと思います。","respondent":"原高齢者福祉課長","answer":"それから、緊急対応室ですけれども、さまざまな形で、緊急対応室というのは考えられるところです。具体的な対応をしていますけれども、今言いましたようなトータル的な中での緊急対応ということで、提案をいただいているところです。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"意見","question":"防災備蓄倉庫をつくられるということですけれども、どういう方を対象に、何日分ぐらいを備蓄されるのか。それから、(5)のリサーチを行ったということですけれども、どのように、どんなことを聞いて行ってきたのか、説明を求めました。","respondent":"原高齢者福祉課長","answer":"地域の方の１週間分ぐらい、バランス等々の関係で出てこようかと思いますけれども、そういった分を保管するということで考えているところです。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"今後、品川区としての運営事業者の選定の考え方というのを、お聞きしたいんです。区内の法人ではなくて、結構、今、外から入れてきているなと思うんですけれども、今後は、どのような考え方で進められるのか、説明を求めました。","respondent":"原高齢者福祉課長","answer":"区内の５法人というのは、今後も、そこの考え方は変わっているところはございません。そういった意味では、施設の規模、内容等々によって、そこの部分については、今、申し上げた考え方に基づきながら進めていくです。","id":"exchange-003"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"公募するにあたって区が求めた中身というのは(1)から(4)で、ショートステイや緊急対応室という提案があったということなんですけれども。ほかの２法人の提案が、それと比べてどうだったのかというあたりを、ちょっと教えてほしいと求めました。","respondent":"原高齢者福祉課長","answer":"ケアの方針等、施設を見学させていただいて、そこにまたさらに感銘を受けたというような状況です。２番とも絡むところですけれども、そういった部分の対応、大変評価をさせていただいたところです。","id":"exchange-004"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１１月７日の厚生委員会のときに、どういうふうに述べられているのか、ひとつ教えていただきたい。ここの選定理由の(2)の3)のところで、どういうところと連携をしていくのかということと、ちょっと教えてほしいと求めました。","respondent":"原高齢者福祉課長","answer":"看護師による介護福祉士との連携の中での研修体制の確立、既に実施してきておりまして、この法人は認識しております。これからの課題ということで、そういう認識の中で実現をしていこうというところで考えているということで、理解をしています。","id":"exchange-005"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"提案の中身として、そういうところまで提案をしてくださいということで書かれているんですけれども、どれぐらいを考えているのかということ。新生寿会なんかは、この若竹大寿会の研修の体制というのはどういう状況になっているのかということについても、お聞かせほしいと求めました。","respondent":"原高齢者福祉課長","answer":"それから、２点目の職員の研修等ですけれども、やはり介護は、心を持って介護しませんと、なかなか、利用者に対応できないです。職員みずからがそういった認識の中で対応するという中で、そういったことを含めてトータルでやっているということで、理解をしています。","id":"exchange-006"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"それから、離職率とかについては、この法人がどうなっているのかということも、教えてほしいと求めました。この提案の施設を改修して整備するにあたっての、提案の中でも出てきているのではないかと思うんですけれども、教えてほしいと求めました。","respondent":"原高齢者福祉課長","answer":"提案というところでいきますと、９億円ちょっとぐらい、工事費だけでいけは９億円程度の提案をいただいているところです。そのほかに設計等々は別の金額ということで、理解をしています。","id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけ、教えてください。さっきからずっと、施設を見てきた、見てきたと言うんだけど、新生寿会は、岡山県まで行ったという理解でいいのか。","respondent":"原高齢者福祉課長","answer":"見てきたというのを、ちょっと強調し過ぎて大変恐縮です。麹町の小規模特別養護老人ホーム、それから、小規模多機能型居宅介護、グループホーム、それから地域の交流の部分ということで、見てきたです。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"意見","question":"１日で見てきて、それはぜひ、配慮をしたほうがいいのではないか。岡山県まで行って、本拠地を見てくるというほうがいいような気がするということだけ、言っておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"若林委員","kind":"質問・要望","question":"やはりこの3)の、すごくポイントといいますか、注目をしております。具体的に品川区でどういうふうにされていこうとしているのか、イメージとして、ちょっと押さえていただきたいと思うんです。","respondent":"原高齢者福祉課長","answer":"医療対応看取りというものを、仕組みの実践を、この間やってきたです。こういったところと連携をしながら、区の中でも、今後のテーマの中で看取りというものをとらえて運営をしていきたいと考えておるところです。","id":"exchange-010"},{"speaker":"若林委員","kind":"意見","question":"すみません、ちょっとまだイメージがわかないので、そうすると、この法人が診療所を持っておられますけれども、こういうところと、いわゆる法人の中の介護の枠の中で、横浜市ではやっていらして、その外の、例えば医師会とか。","respondent":"原高齢者福祉課長","answer":"医師との連携をどういうタイミングになったら声をかけていくか、そこが、これからの看取りに対する取り扱いということで考えています。こういった考え方をもとに、地域の医師会と連携しながら対応していくということで、とらえているところです。","id":"exchange-011"}]},{"id":"topic-02","title":"品川区立大井林町高齢者住宅の入居者募集","agenda":"品川区立大井林町高齢者住宅の入居者募集","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"応募はどれぐらいきて、どれぐらいの方が落選されたのか、説明を求めました。","respondent":"間部高齢者いきがい課長","answer":"ご説明させていただいたように、今回、現在もう介護が必要な方を中心に入っていただくということをご説明させていただいておりました。１２月に約１０日間ほど募集をしたわけですが、６１件の応募があったということで、追加募集をさせていただいてあります。","id":"exchange-012"}]},{"id":"topic-03","title":"品川区立心身障害者福祉会館機能の再編","agenda":"品川区立心身障害者福祉会館機能の再編","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"１面の１番の表のところで、サービス等利用計画案に基づく支給決定とあるんですけれども、これは具体的にはどのようなことなのか尋ねました。","respondent":"永尾障害者福祉課長","answer":"計画をつくって、実際にサービスを行います。１年、これからガイドラインが出る予定ですので、またご報告をしたいと考えております。","id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これで、障害者の方々にとって、よくなる部分を教えていただきたい。利用者のメリットがどこにあるのか、説明を求めました。","respondent":"永尾障害者福祉課長","answer":"サービスの見直しとか、そういうことを行えるということで、非常に利用者とってはきめ細やかなサービスを受けられるということが利点になります。区が４分の１となり、この区の４の１の部分が出てくるという意味で、負担が増えるということになります。","id":"exchange-014"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"その対象というのは、知的・身体・精神すべてが含まれていくのかということを教えてほしいと求めました。そして、その対象者というのは、おおよそ何人ぐらいになるというあたりも、ちょっと教えてほしいと求めました。","respondent":"永尾障害者福祉課長","answer":"国のほうで示しているところでは、３年の経過措置の中で、徐々に拡大してくださいというようなことが出ております。政府のほうから出される予定になっておりまして、どの程度のことをやるかというものが、もうちょっと明らかになるのかなというふうに思っています。","id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ぜひ、そういう方向にしていただきたい。もうほんとうに間近に迫っている段階で、４月１日からはどの程度というところを、考えられているところをお聞かせほしいと求めました。","respondent":"永尾障害者福祉課長","answer":"今現在、考えているところでは、現在の心身障害者福祉会館の体制の中でできる範囲でやってみようかと考えています。過渡的な部分がありますので、そういう実践を増やして、職員のケアマネジメントの技術を磨いていくというほうに力を入れていきたいと考えています。","id":"exchange-016"},{"speaker":"若林委員","kind":"質問・要望","question":"もう既に、種々ご説明をされているんだろうと思うんですけれども、そこら辺の現状をお知らせいただきたい。当然、区のほうで進められると思うんですけれども、ちょっとそこは確認をさせてほしいと求めました。","respondent":"永尾障害者福祉課長","answer":"第１回目の保護者会になりますので、まず今日のご意見を十分に聞くということと、今の段階での予定では、２月中に個別面談を行います。この２月から３月の動きについても、心身障害者福祉会館とげんき品川の職員と両方で、この部分の説明等を行っていきたいと考えております。","id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"今、旗の台の心身障害者福祉会館で行っている、就労移行支援の対象の方は何人ぐらいいらっしゃるんか尋ねました。","respondent":"永尾障害者福祉課長","answer":"今現在、２２名いらっしゃいます。","id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"２２名の方は、ちょっとどうなのかということも、教えてほしいと求めました。","respondent":"永尾障害者福祉課長","answer":"今、通われている方の平均年齢から申し上げますと、２６歳です。就労では重要な部分がありますので、その訓練も含めて、げんき品川ではやるということになります。","id":"exchange-019"}]},{"id":"topic-04","title":"障害者自立支援法の「同行援護」","agenda":"障害者自立支援法の「同行援護」","exchanges":[{"speaker":"石田（ち）委員","kind":"意見","question":"これは２４時間、３２時間と決まっていたのが、この５０時間ちょっとは自由に使えるようになるのかということ。実質、５６時間だったのが５０時間ちょっとに減ったということになるのか、説明を求めました。","respondent":"永尾障害者福祉課長","answer":"ですので、今までと同じ使い方をするのであれば、大抵の方は、これまでよりも多い時間数が使えるのではないかと考えています。身体介護があるのかないのか、時間はどうするのか、その辺はサービス利用計画を立てて決めるというような内容になっております。","id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"知的障害の方は、今までどおり、地域生活支援事業のほうでいくということなんでしょうか。それから、現在、利用している方は何人ぐらいいらっしゃるのかについても、お聞かせほしいと求めました。","respondent":"永尾障害者福祉課長","answer":"そのほかにも、移動支援を実施している事業者は区内にありますので、そちらのほうに移行していくような形をとっていきたいと考えています。それから、利用者数ですけれども、現在、５７名の登録になっております。","id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"サービス利用計画を作成して、何時間というので決めていくと思うんですけれども、これはどこでつくられるのかということ。経費の１割が原則ということになっていますけれども、利用料のことについても、ちょっと説明を求めました。","respondent":"永尾障害者福祉課長","answer":"サービス利用計画ですけれども、こちらにつきましては、障害者生活支援センターおよび品川区のケースワーカー両方で連携しながらつくっていきます。住民税非課税の方につきましては、無料です。","id":"exchange-022"}]},{"id":"topic-05","title":"平成２４、２５年度東京都後期高齢者医療保険料率案","agenda":"平成２４、２５年度東京都後期高齢者医療保険料率案","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ざっと数字だけをお聞きしたいので、まとめて言います。国民健康保険の場合は、滞納理由なんかも出されているんですけれども、今回はあるのか、あればお聞かせほしいと求めました。","respondent":"榎本高齢者医療担当課長","answer":"短期証の発行数ですが、平成２３年８月で９名の発行をしております。滞納されている方の理由ですけれども、滞納相談がありまして、こちらで把握する範囲では、納付がなかなか困難と認められる方もあります。","id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"質問","question":"もう一つあったんですけれども、資料の一番最後のページの表の一番上の旧ただし書き所得が０円で、年金収入換算額が０～１５３万円という方が、東京都で言うと５５.２％いるということなんですけれども、区で見ると、どれぐらいかというのがわかれば、説明を求めました。","respondent":"榎本高齢者医療担当課長","answer":"品川区での旧ただし書き所得の割合ですが、５３.５５％で、人数としては１万８,２３１人です。","id":"exchange-024"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"品川区の後期高齢者の人数を、まず教えてほしいと求めました。それから、一番最高の６４５万円以上の方は何人ぐらいいらっしゃるのか、そのこともちょっと教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"東京都全体ということなので、委員長も言われたように、ぜひ品川区のデータも説明のときには出していただきたいと要望させてほしいと求めました。3)、4)の葬祭事業から保険料未収入補てん分までのところは、全国同じようにされているということで考えていいんか尋ねました。","respondent":"榎本高齢者医療担当課長","answer":"１１月から１２月にかけまして、東京都と何度か協議を重ねまして、広域連合のほうから強く要望を出しておりました。東京都が協議のうえ頑張っていただいたということで、協力いただいた態勢が、都道府県によって異なるです。","id":"exchange-026"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この東京都独自の1)から4)のことに加えて、どういう状況になっているのかというあたりが、わかったら教えていただきたいことが１点です。どうしてこうなってしまうのかということと、そこら辺のところについて、ちょっと教えてほしいと求めました。","respondent":"榎本高齢者医療担当課長","answer":"東京都広域連合もこの１月に出たところでございまして、全国の数値に関しましては、まだはっきりとしておりません。広域連合としても、段階的な所得の軽減の変化について、もう少しなだらかな形にできないかということで、国のほうに要望しています。","id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"さらにこれを積み増しをして、保険料の値上げを押さえていくというところに、引き続いてしていただきたいと思っているところです。軽減率が８.５割から一気に２割となってしまうというところでは、５割軽減とかいうのもありますし、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"意見","question":"多分、御家事情として、各区あるわけです。じゃあ、品川区はどういうスタンスでいるのかというところを、聞きたいとの意見を述べました。","respondent":"榎本高齢者医療担当課長","answer":"後期高齢者は特に、後期高齢者は８０万円台という医療費になっておりまして、そのぐらい医療費が非常にかかる年代になってあります。世代間の公平性等を考えまして、保険制度を実現させていくしか、現状ではないと考えています。","id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そのうちいつか、こっちの本則に戻りますよみたいな、いつになるかわからないわけじゃないですか、これは。もう一段やっぱりしっかり突っ込んで、ここは一般財源を投入しているんだということを踏まえるなら、もうちょっと説明をしていただきたいと思う。","respondent":"木下健康福祉事業部長","answer":"保険料で対応すべき、４項目挙がっておりますけれども、これはほんとうは保険給付の中で見るべきものだと思います。ご指摘がございましたけれども、本則を挙げながら、このような形に併記してお示しさせていただいたということであろうかと思います。","id":"exchange-030"}]},{"id":"topic-06","title":"「放射能に関する講演会」の開催","agenda":"「放射能に関する講演会」の開催","exchanges":[{"speaker":"石田（秀）委員","kind":"意見","question":"どういう話をしてくださるのかわからないけれども、という人がいたら、何の効果もない。そういう両極端の人に２人きてもらうとか、そういうことができるのかどうかわからないけれども、そこら辺だけお願いをしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ホームページを見ればいいと思うんですけれども、これは、普通に参加はできるんですか。それから、料金とか、定員とか、どうなっているんか尋ねました。","respondent":"工藤品川区保健所生活衛生課長","answer":"広報等で周知していますけれども、チラシができております。こちらのほうを、今日、この委員会終了後にお配りしたいと考えていますけれども、料金無料、先着４００名ということで周知しています。","id":"exchange-032"},{"speaker":"若林委員","kind":"確認","question":"教育委員会も含めた放射能のいわゆる測定というのですか、これはしっかりご理解というのですか、認識されたうえで臨まれるのかという確認。なるべくフロアの方の質問に、しかるべき担当の方が正確にお答えしていただくことは最低限必要かなと思いますので、ちょっと確認します。","respondent":"工藤品川区保健所生活衛生課長","answer":"そういった部分では、十分に講師と情報交換をして、しっかりとしたものにしていきたいと考えています。いらっしゃる方は区民ですので、そういった部分では、しっかり対応できるように態勢を整えたいと考えています。","id":"exchange-033"},{"speaker":"若林委員","kind":"質問・要望","question":"不安でいらっしゃる、毎日が心配でたまらないというお気持をしっかりとくみとって迎えていただきたいと、これだけはお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"向委員","kind":"質問","question":"数点、お伺いしたいんですが、まずこの講演会開催は、私もかなり長い間待っておりました。なぜ週末にセッティングしなかったのかとか、そこのあたりをちょっと疑問に思ったので、簡単にご説明ほしいと求めました。","respondent":"工藤品川区保健所生活衛生課長","answer":"かみ砕いて説明しているという部分で、お願いするのであれば、この先生にお願いしようということで決めておりました。夜であれば、一般に保護者のお母様方が来れないという部分があるのではないかということで、平日の２時からというふうにしたところです。","id":"exchange-035"},{"speaker":"向委員","kind":"質問・要望","question":"要望になるんですが、このあたりは、ぜひ検討をしていただけたらと思います。ぜひ伺いたいと思うんですが、ぜひ、今後ともご検討のほうを。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/594819?Template=document&Id=3314#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":38871,"voices":103}},{"id":"h24-20120123-8","meetingId":"h24-cm01","date":"2012年1月23日","dateIso":"2012-01-23","committee":"建設委員会","time":"午後１時００分～午後４時３９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を63件整理しています。","topics":[{"id":"topic-01","title":"を行います。 初めに、(1)「都市計画公園・緑地の整備方針」（改定）","agenda":"を行います。 初めに、(1)「都市計画公園・緑地の整備方針」（改定）","exchanges":[{"speaker":"中塚副委員長","kind":"質問・要望","question":"改めて位置づけについて伺いたいんですけれども、どう評価されたのか、その点を補足してほしいと求めました。それ以外のところに新たにつくるのか、どういう方法を考えているのか、そこを伺いたいと思います。","respondent":"藤田水とみどりの課長","answer":"次のページの４１ページをご覧いただきたいんですけれども、この一部が供用開始、都市計画公園区域の区域から除外していくと。結局は広い公園を使えるという形になりますので、そういったような新たな仕組みについても考えて実施をしていきたいということを示しているものです。","id":"exchange-001"},{"speaker":"中塚副委員長","kind":"質問","question":"地域を限定することなく区内全域に震災対策としての公園、緑地の確保に動き出すべきじゃないかと思うんですけども、その点はいかがお考えか伺います。ふ頭沿いの広い公園であったり、しっかり位置づけて進めていく必要があると思うんですけれども、その点はいかがか尋ねました。","respondent":"藤田水とみどりの課長","answer":"１１ページの大規模救出拠点等の考え方ですけれども、言葉のとおり救出するための予定ということで、この中でも十分認識をしています。","id":"exchange-002"},{"speaker":"中塚副委員長","kind":"質問","question":"補助金をしっかりつけなさいというのも主張していくべきではないかと思うんですけど、やっていくべきだと思うんですけど、いかがでしょうか。先ほどの大規模拠点についてしっかり位置づけるよう働きかけていくという姿勢があるのか、そこを伺いたいと思います。","respondent":"藤田水とみどりの課長","answer":"１点目と２点目、学校であったりとか、いろんな施設を連携させて防災機能のことを考えていくものだと思ってあります。これを切り口にこちらの冊子をつくってありますので、今改定作業を進めてありますので、その辺との連携を図っていくというのが基本的な考えです。","id":"exchange-003"}]},{"id":"topic-02","title":"しながわ環境大賞・みどりの顕彰および環境講演会","agenda":"しながわ環境大賞・みどりの顕彰および環境講演会","exchanges":[{"speaker":"井上委員","kind":"質問","question":"これを始めてどんなふうに変わってきたのかというこの事業の評価と、あと選考委員のメンバーというのはどういう方たちがいるのか。これは自薦他薦の両方で出されているのか、その３点をお願いします。","respondent":"野呂瀬環境課長","answer":"２点目の委員のメンバーですけれども、環境大賞実施要綱に基づきまして、選考委員を置くということになってあります。ものづくり経営支援課長、子育て支援課長、このメンバーで選考委員会を実施しています。","id":"exchange-004"},{"speaker":"井上委員","kind":"意見","question":"平成１８年からの選考のほうで同じ団体が続いているのか、区民に認知されていくようになってほしいと思うんですけど、その辺の状況と行政としてこれに取り組んでいく何か目標とか取り組みはありますかとの意見を述べました。","respondent":"野呂瀬環境課長","answer":"応募につきましては、やはりどうしても選考から漏れてしまうというところも数が決まっていますのであります。いわゆる継続して実施されているか、啓発を今後も続けていくきっかけづくりになるような、そういうような事業にしたいと考えているところです。","id":"exchange-005"},{"speaker":"井上委員","kind":"意見","question":"３４団体ということで応募があったんですけれども、新規なのか、毎年応募されて、１回大賞になったら次はないとか、そういうような要綱で何か定めとか、経験者じゃない人たちというふうにどんどん広げて取り組んでいますかとの意見を述べました。","respondent":"野呂瀬環境課長","answer":"１回受賞したら、もうないという規定ではありません。数年前に受賞した団体については継続してやっていただくということもあるんですけれども、また今年も継続してやっている方、選考していくです。","id":"exchange-006"},{"speaker":"中塚副委員長","kind":"質問","question":"同じだけど、植えた木に工夫があるのか、何かどういうところを基準に選んでいるのか、１点伺いたいなと思います。どうも何か釈然としないのは、どう考えたらいいのかなというのは、どうお考えなのか伺いたい。","respondent":"藤田水とみどりの課長、野呂瀬環境課長","answer":"みどりの関係のほうですので私のほうからお答えします。そういったものについては当然評価をしていきたいということで考えてありますので、住宅のほうを顕彰していきたいというふうに考えてあります。 ２点目のお尋ねですけども、大井坂下公園周辺の清掃活動も関連企業等を含めて実施しているだとか、いろんなところで細かい説明がございました。そういうのを総合的に見て環境大賞として決定したという経緯があります。","id":"exchange-007"}]},{"id":"topic-03","title":"地域が主導するＥＶカーシェアリング事業状況","agenda":"地域が主導するＥＶカーシェアリング事業状況","exchanges":[{"speaker":"中塚副委員長","kind":"質問・要望","question":"そもそもどういう理念としてとらえているのか、何を目標とされているのか、そこを伺いたいなと思うんですね。つまり、品川区から排出されるＣＯ２の総量削減、それをやっぱり目標と掲げているのか伺いたいと思います。","respondent":"野呂瀬環境課長","answer":"２番目の災害時の対応なんですけれども、災害時にも対応できるような形の地域コミュニティを形成していきたいという考え方のものです。この立ち上げ支援をして、今年度４月から本格的に実施していくところになると思いますけれども、今ちょっと詳細はつかんでおりません。","id":"exchange-008"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"この理念とは何かと伺ったんですけれども、地域コミュニティが中心になって地域主導でやると、それが理念なんでしょうか。そういう考え方があるのか、目指しているのか、そこを伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"武内委員","kind":"質問","question":"それともたまたま今こういうものは東京都の補助があって、やってみようかと、そういうふうになったのか。だから、今回区が計画しているわけですけども、今後どんなことを目指していこうとしているのかというのがもしわかれば説明を求めました。","respondent":"三宅都市開発課長","answer":"大崎エリアマネージメントは、あくまでも大崎エリアの、地域のまちづくりということを中心に考えております。あくまでも大崎エリアを中心にした活動としてやっておりまして、同じカーシェアリングを全区的に展開するところまでは考えておりません。","id":"exchange-010"},{"speaker":"井上委員","kind":"質問・要望","question":"区はどういうところにいて、どういうふうに育てていくために協力をしていく役割を担っていくのか、区の位置がよくわからないのでご説明いただきたい。","respondent":"野呂瀬環境課長","answer":"今年度の２,３００万円につきましては、いわゆる地域コミュニティを立ち上げる支援ということで、これについては今年度限りのことです。地域コミュニティをどういうふうな形で継続していくのか、それはまた別の検討課題で、都からの補助金は今年度限りです。","id":"exchange-011"},{"speaker":"井上委員","kind":"質問","question":"事業委託契約は、区とどういうふうな事業を、具体的に事業契約の何を、委託の締結をしたのかということと、エリアマネージメントのところで、「スマートシェア倶楽部・大崎」という事業主体が１個その中に発足したという関係でいいのでしょうかというようなことなんですが。","respondent":"野呂瀬環境課長、岩田都市環境事業部長","answer":"委託はしたんですけど、環境についての取り組み等につきましては、今後も区とは継続して取り組んでいっていただくです。 したがって、今後は区からの資金援助はないというのが前提で今話を進めているものです。これがいわゆる新たなグリーン電力証書として発行できますので、こういう意味です。","id":"exchange-012"},{"speaker":"井上委員","kind":"意見","question":"事業委託契約を締結というのが、この大崎周辺の社団法人、いろいろなことをやっている大崎エリアマネージメントというところとこれを結んだのは、補助金をそこにやりますよという契約の締結の項目というのはどういうものなのかとの意見を述べました。","respondent":"野呂瀬環境課長","answer":"大崎エリアマネージメントと契約書を締結したのは、地域主導のカーシェアリング事業支援等業務、この件名で協定書を結んだところです。","id":"exchange-013"},{"speaker":"大沢委員","kind":"質問","question":"先ほどの部長のお話の中で委託金の件、間接的な補助金というふうにおっしゃったんですが、あくまでも委託であって、間接補助金というのはちょっと表現が適当ではないと思うんですが、もう一度伺いたい。","respondent":"岩田都市環境事業部長","answer":"したがって、やむなく品川区が主体となって地元の組織である大崎エリアマネージメントに対して業務委託をするという形をとったです。わかりやすく一般的に言うと、いわゆる間接補助のような形での制度を活用したというふうに申し上げたものです。","id":"exchange-014"},{"speaker":"大沢委員","kind":"意見","question":"そうすると、やっぱり委託と補助となると、もろもろのお金、また区のかかわり方がちょっと違ってくると思うんですけれども、そこのところはどういうふうに理解をしたらいいのかとの意見を述べました。","respondent":"岩田都市環境事業部長","answer":"今申し上げましたように、現実には業務委託という契約です。したがって、品川区の業務をこの大崎エリアマネージメントが受託をして実施をしたという形になってあります。","id":"exchange-015"},{"speaker":"大沢委員","kind":"質問","question":"そうすると、責任の所在というのは、大崎エリアマネージメントであって、品川区のほうは何かあっても一切責任を負わないというような形なんか尋ねました。","respondent":"岩田都市環境事業部長","answer":"あくまで事業主体は品川区であります。発注者側に非があるのかによって、その責任所在は分かれてきますけれども、そのようなことはないというふうに考えております。","id":"exchange-016"}]},{"id":"topic-04","title":"区営住宅入居者募集","agenda":"区営住宅入居者募集","exchanges":[{"speaker":"井上委員","kind":"質問","question":"今度空き住宅のみの募集ということで、１月、７月で、その違うときにあくところは、ちょっと非効率な気がするんですね。改善も必要かという課題もあると思うので、途中であいた分については、どういうふうに対応していくということをお考えか尋ねました。","respondent":"柏原住宅担当課長","answer":"この募集を検討する際にそういったことも外部で議論にはなりました。そういったところをどういう形で解決できるかというのは、ちょっと新たな課題ということで引き続き検討していきたいというふうに考えてあります。","id":"exchange-017"},{"speaker":"井上委員","kind":"質問","question":"こういうあきと、その人たちだけが住み替えていくというのは、そうじゃない方たちにすればすごく不公平感があるというふうに思うんですね。そのときに、そういったところの対応の仕方というのは、公平にどういう案を持ってされているんか尋ねました。","respondent":"柏原住宅担当課長","answer":"高齢になられて、足腰が不自由になられて階段が上れないというような場合に、じゃあその方たちはそのままでよろしいのかというところもあります。現在もちょっと検討を進めているですので、いろいろ試行錯誤しながらですが、今後進めていきたいです。","id":"exchange-018"},{"speaker":"中塚副委員長","kind":"質問","question":"今回募集の仕方が新しくなったのであれなんですけども、どれぐらいの応募の数を見込んでいらっしゃるのか、お考えを伺いたいと思います。それが４戸で十分だと思っていらっしゃるのか、そこを伺いたいと思います。","respondent":"柏原住宅担当課長","answer":"それに５０世帯から、今回４戸ということですけれども、２００人から３００人ぐらいの応募はあるのではないかというふうには考えてあります。","id":"exchange-019"},{"speaker":"中塚副委員長","kind":"質問","question":"この間の経過を見ても、年１５戸ぐらいあくと、これで足りているという認識なのかを伺いたいんですね。しっかり増設に方針を掲げるべきだとずっと主張してきたわけですけども、改めてそこを伺います。","respondent":"柏原住宅担当課長","answer":"区営住宅、区で持っている区営住宅だけで居住、お住まいに困っている方全部に対応しようというものではないのではないかというふうに思っています。我々のほうも民間の空きストックをどんどん有効活用しようということで今検討していますので、そういった考えでいるです。","id":"exchange-020"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"大体区営住宅に申し込みされる方は一定高齢者の方が申し込むわけですけれども、古い築年数のたったアパートの退去を求められている。ちゃんと住宅に対する区の責任をしっかり果たしていくべきだと思いますが、いかがか尋ねました。","respondent":"柏原住宅担当課長","answer":"それから、区営住宅では対応できないというふうに言っているのではなくて、区営住宅だけで議論すべきものではないというふうに考えているものです。そういった方向で考えていきたいです。","id":"exchange-021"}]},{"id":"topic-05","title":"平成２４年２月都営住宅入居者募集","agenda":"平成２４年２月都営住宅入居者募集","exchanges":[{"speaker":"武内委員","kind":"確認","question":"それとも何か一定の間を縫ってスケジュールがあるのか、それについてのお知らせというのは、広報「しながわ」とかで出しているんでしょうか。そこだけ確認したい。","respondent":"柏原住宅担当課長","answer":"１０月、１月にやる予定だというのは聞いているんですが、周知をしています。ここ何年かは１件とかという形でございまして、品川区のこのスタンスとしては、一般の全体の募集の中でやっていただくということで考えてあります。","id":"exchange-022"},{"speaker":"武内委員","kind":"質問","question":"もしくは住宅担当に直接情報を聞いてもらうしかないと、広報「しながわ」ではやっていないということ、間に合わないということですね。３０倍と、知らなくてということがあるのかどうか、その辺はどうなんか尋ねました。","respondent":"柏原住宅担当課長","answer":"本当に直前ということですので、なかなか周知が難しいということでございまして、広報紙に載せるのはタイミング的には非常に難しいというものです。","id":"exchange-023"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"現在東京都はそこをどう考えているのか、あわせてご説明ほしいと求めました。事故物件の申込倍率といいますか、どれぐらいの方がそういうところでも申し込んでいらっしゃるのか、倍率についてもご説明ほしいと求めました。","respondent":"柏原住宅担当課長","answer":"これ全体で考えるということでございまして、都営住宅につきましては、都が総合的に判断して考えるべきものだと考えています。こちらのほうもお話を聞いたこともありますけれども、そういったことについては回答できかねるという返事をもらっています。","id":"exchange-024"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"改めて都営住宅の増設をしっかりと東京都に求めてほしいと求めました。一人でお亡くなりになったり、さまざまな事情もありますので、ぜひ増設を働きかけてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]},{"id":"topic-06","title":"住み替え住宅（大井林町高齢者住宅）の募集結果","agenda":"住み替え住宅（大井林町高齢者住宅）の募集結果","exchanges":[{"speaker":"武内委員","kind":"質問・要望","question":"それからそれぞれ八潮と木造密集地域で今回合計１１世帯の方々が移ってくるわけですけれども、その跡の利用というんですか、主なところで。特に木造密集地域なんかは、この後どのようになっていくのか、それを教えてほしいと求めました。","respondent":"柏原住宅担当課長、品川防災整備担当課長","answer":"もっと二、９件来たということですので、ほぼアンケートどおりの結果が出ましたので一定の評価ができるのではないかというふうに考えてあります。４件ぐらいは希望されているというところがありまして… ７月から始めて短期間の募集をした割には２件、この期間内で２件ということであれば非常に意義があったのではないかというふうに解釈しております。","id":"exchange-026"},{"speaker":"武内委員","kind":"質問・要望","question":"八潮については、そうしますと、ファミリーの方たちが４件ぐらい今予定されている。そこを教えていただきたいのと、その跡の使い方というんですかね、何々地区あたりぐらいはちょっと教えてもらいたい。","respondent":"柏原住宅担当課長、品川防災整備担当課長","answer":"まだ４件といいましても、具体的にどうだというのは決まってはいないんですけれども、例えば家賃を安くするとかということではなくて、相場の家賃で。ただ、八潮はこれだけ住む魅力がありますよというのを大きくＰＲしたいです。そういうものに適した土地であれば買い取りということも考えられるんですが、その辺を今後検討はしていきたいというふうに考えております。","id":"exchange-027"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"２０戸募集で１１戸だったというところはどういう事情があったのか、そこを伺いたいなというふうに思いますのでご説明ほしいと求めました。まずこの制度は結構複雑だなと思うこともありまして、実際の状況にどういう特徴があるのか、そこをご説明いただけますか尋ねました。","respondent":"柏原住宅担当課長","answer":"事情と申しますと、個々の事情ということですか。","id":"exchange-028"},{"speaker":"井上委員","kind":"質問","question":"そこをどういうふうに、その周知の方法がどうだったとか、そのことについてどういうふうに思っているのか。住み替え住宅は１回だけの施策なのか、そこはどういうふうにこれから整理をしていくのか、考え方を説明を求めました。","respondent":"柏原住宅担当課長、品川防災整備担当課長","answer":"２０戸ということで１１戸入る予定で今考えていますけれども、２０年という形で住まわれると、減るという話ではないと思います。先ほどの区営、こういったところの住み替えの対象になるということで… ７月から制度を始めたということで、期間が短かったということもあるんですが、この間興味を持たれた方というのは非常に多かったです。","id":"exchange-029"},{"speaker":"井上委員","kind":"質問","question":"世帯用を１２戸と多くとっているにもかかわらず、そこは意見として結果的にこうなってしまったではちょっと違うなというふうに思っています。家賃とかそういう問題とか、どんなふうにこれをいいほうにちゃんと向けていくのか、その辺の考えはどうなんか尋ねました。","respondent":"品川防災整備担当課長","answer":"この密集地の中で、大きな土地を確保するというのは非常に困難な状況であるということが背景にあると考えられます。ただ、その辺の課題を踏まえながら今後どのようにやっていったらいいかということは検討していきたいというふうに考えております。","id":"exchange-030"}]},{"id":"topic-07","title":"品川区まちづくりマスタープラン全体計画骨子（案）","agenda":"品川区まちづくりマスタープラン全体計画骨子（案）","exchanges":[{"speaker":"井上委員","kind":"質問","question":"２ページの図なんですけれども、そういう生活エリアというか、そういう人たちもいっぱいいるわけですよね。このところはどういうふうに見ていったらいいのかという、見ると感じるんですけど、そこのところはどういうふうに読めばいいんか尋ねました。","respondent":"山崎マスタープラン担当課長","answer":"それで、当然こうした白地図にいろんな図表で都市構造をあらわすものですから、その重なりがありましたり微妙に隠れてしまう部分等々があります。","id":"exchange-031"},{"speaker":"井上委員","kind":"質問","question":"これはどういうふうな形で、イメージして、こういう図になるんでしょうか。今後のまちづくりとして。","respondent":"山崎マスタープラン担当課長","answer":"品川・天王洲アイルの広域活性化拠点の考え方ということですが、それから品川駅に近接をしているエリアでもあるということが特徴かなです。","id":"exchange-032"},{"speaker":"井上委員","kind":"質問・要望","question":"まだ先が長いですから、それはだれですかというところのかみ合わない議論になるので、そういう要望に対してどのようなお考えをお持ちか尋ねました。","respondent":"山崎マスタープラン担当課長","answer":"都市計画法のほうでは、こうしたそれぞれの自治体のまちづくりの基本方針を定める際には、こういうことで法的にはかかわっています。","id":"exchange-033"},{"speaker":"井上委員","kind":"質問・要望","question":"法的にパブリックコメントというところがあると思いますが、そうではなくてというところの意味なので、これから検討いただきたいと。どんどん変えていくほうにしていただきたいというふうに思いますので期待をしています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"松澤委員","kind":"質問","question":"１点聞きたいんですけど、３ページです。都市基盤のところで、都市計画道路の整備促進、補助２９号線、補助３１号線と書いてあるんだけど、これをどのように考えているのかお伺いします。","respondent":"山崎マスタープラン担当課長","answer":"こういうようなことで補助２９号線、補助３１号線についてもそうした方向でもともと長期計画でも規定があります。区といたしましては、例えば東京都に働きかけを行う等々のことをしまして、そうした考えのもとに今回記載をさせていただいているものです。","id":"exchange-035"},{"speaker":"松澤委員","kind":"提案","question":"補助２９号線は防災的には必要だということですけれども、あの件については、品川区の議会の中では３回廃止ということを提案しているんですよね。ここに載せるということは口約束じゃなくて、しっかり行動していくというふうなことでよろしいんですねとの意見を述べました。","respondent":"片田防災まちづくり事業部長","answer":"補助２９号線につきましては、今回の３・１１を含めてきちっと安全なまちを考えていかなきゃいけないと、取り入れていきたいと。東京都のほうも、１０年の中の検討の、十分その辺の連携をとりながら区としても働きかけるところは働きかけていきたいというふうに考えております。","id":"exchange-036"},{"speaker":"武内委員","kind":"質問・要望","question":"２ページの地域生活拠点のところで、ちょっとわかりやすく、教えていただきたい。考え方を出していくというふうな話になっているはずなんですけど、その中で今補助２９号線という話が出たんですが、それは交換条件なんか尋ねました。","respondent":"片田防災まちづくり事業部長、山崎マスタープラン担当課長","answer":"実際に担当レベルの説明、明日２４日ですか、東京都からの説明を受けるといったような状況もあります。そういう考え方の大枠については説明を受けましたけれども、十分東京都の説明を具体的に確認しながら、このように考えております。来年策定をする地区別計画の中に住宅マスタープランの特徴を出すような表記のほうを少しちょっと検討させていただいているところです。","id":"exchange-037"},{"speaker":"大西委員","kind":"質問","question":"それと、高齢者等が住みやすい住まいづくりの促進というのは、バリアフリーの何か補助かなんかをするとか、そういう意味のことなのでしょうか。区がどうこうという問題じゃないんではないかという認識を持つんですが、そこはどうですか、その３点は。","respondent":"山崎マスタープラン担当課長、柏原住宅担当課長","answer":"ここについては、それから福祉施策と連携をいたします住宅施策、そうした連携の促進というようなことをイメージしているものです。ファミリー世帯の住居取得にかかわる支援ということにつきましては、今ちょっと検討しておりますが… 数字としましては、１万２,０００戸以上の賃貸住宅の空き家があるということで、空き家になっている大きな要因があるというのは数字上出ております。","id":"exchange-038"},{"speaker":"大西委員","kind":"質問","question":"今の３点目のところは大体わかったんですけど、１点目の今ある住宅の住みやすさの維持・改善と有効活用、これは耐震に対する補助をするということか尋ねました。","respondent":"柏原住宅担当課長","answer":"ただ、それ以外にも先ほどございました賃貸の住宅も１万２,０００戸ある中で、使えない住宅とかというのも統計上幾つか数字が出ているんですね。","id":"exchange-039"},{"speaker":"大西委員","kind":"質問","question":"これからもますます高齢化を迎えるということと、２番目の高齢者等が住みやすいものと空き家の有効活用、だったら、住むべき高齢者住宅がない。治安の問題もあって、そういう方向で少し品川区も考えていく視野を持ってもいいんじゃないかと思うんですが、その辺どうか尋ねました。","respondent":"柏原住宅担当課長","answer":"そういった方たちを拒まないでいかに入れるかとか、そういったところも今、それは不動産団体の方たちと今お話をしています。ハード、ソフト、両面でそういったところを大きな視点として進めていこうとしています。","id":"exchange-040"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"下の今も若干議論がありました量から質、建設からストック活用への転換、これはどう目指しているのかそこを伺いたいと思います。伺いたいのは、なぜこの路線が必要なのか。","respondent":"山崎マスタープラン担当課長","answer":"国のほうでも方針が量から質ということと、いろんな意味で方針とすればそうした方向に転換していっている事例があります。区といたしましても、良質な質を確保しつつ住宅施策の方針をこちらのほうで明確化をしていくんだというようなことです。","id":"exchange-041"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"この際その前に伺いたいことがあるんですけれども、補助３１号線の周辺だけでなく、そうした住宅や地域はあるのかどうか伺いたい。なぜかというと、この道路の問題を言うと、必ず防災上と言うんだけども、実際どういう課題があるのか疑問なのでぜひご説明ほしいと求めました。","respondent":"岩田都市環境事業部長、山口防災安全担当課長","answer":"まず道路とは何ぞや、都市における道路とはどういう役割なのかというところから少しご説明したいと思います。したがって、今回は特に３・１１等を受けて… 一つ目、そういうエリアはほかのエリアと比べて非常に早期の消火活動が難しいエリアだというふうに指定しております。","id":"exchange-042"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"てんぽについて、どう合理性を説明するのか伺いたいと思います。延焼を遮断するための役割を果たせるのか、そこをどうやって防災上考えていらっしゃるのか、改めて伺いたいと思います。","respondent":"岩田都市環境事業部長","answer":"その他の火災については、各町会で頑張っていただいて、初期消火に努めてもらう以外にない。それで、万が一延焼火災が出た場合は、速やかに広域避難所に逃げていただくというのが現在の品川区の防災計画になっております。","id":"exchange-043"},{"speaker":"中塚副委員長","kind":"質問","question":"もう１点、道路をつくっても実際に消防活動はどうなのかというお話がありました。この道路計画は、要するに自分の家も含めて近所が家事になったときに消火活動がしやすいと、そういうふうな説明をよく伺っていると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"中塚副委員長","kind":"質問","question":"消防能力の向上と住宅耐震化、そこを位置づけ直すべきだと思うんですが、いかがかということ。そういう説明というのは今の説明と違うじゃないかと、どう考えているのかを伺って、この計画はやめるべきだと思います。","respondent":"岩田都市環境事業部長","answer":"着実に進めざるを得ません。短期的には古い家がつぶれて、その補助も行っているということは、ここはひとつ誤解のないようにご理解をいただきたいと思います。","id":"exchange-045"},{"speaker":"井上委員","kind":"質問","question":"一般の人たちをどう取り込むかという部分で目的がちょっと違うのかもしれないのであれですが、そういう機会にそういうメニューもあわせてすべきだというふうに思うので、そこについては何かありますか尋ねました。","respondent":"中山防災課長","answer":"それぞれ水道局だとかガスだとかというところが、それぞれブースを持ちまして、いろんな危険物の啓発等々をやってあります。今ご提案になりました視覚障害者、それから聴覚障害者の訓練等については、別の機会に設けたいと思ってあります。","id":"exchange-046"},{"speaker":"井上委員","kind":"質問","question":"経費はどれだけかけてやろうとしているのか、その費用対効果も含めてちゃんと把握をしておきたいというふうに思いますので、その辺をちゃんとした数字で説明を求めました。","respondent":"品川防災整備担当課長","answer":"それから、経費に関しましては、こちらは日本大学のほうにマニュアル制作費として２００万円費用をかけております。それから、この講演会に関する費用に関しましては、区の庁舎でやるということ、それからほとんど職員が対応するということで経費はゼロです。","id":"exchange-047"},{"speaker":"井上委員","kind":"質問","question":"こういった講師の方というのは、どのぐらいの講師料を払ってお願いしているんか尋ねました。","respondent":"品川防災整備担当課長","answer":"こちらは日本大学に２００万円をマニュアル作成費用というふうに出しております。その中でやっていただくというふうになっております。","id":"exchange-048"},{"speaker":"武内委員","kind":"質問","question":"ちょっと私が勘違いしているとあれなんですけど、そうすると、今まで品川シェルターは２件か３件の施工がありますけども、これを施工できる業者というのは品川でどれぐらいいたんか尋ねました。","respondent":"品川防災整備担当課長","answer":"こちらは、昨年度までにトータル１件、それから今年度２件ということになっているんですが、３件とも一つの業者に日本大学と協力してつくってもらっているというような状況、現在はそういう状況です。","id":"exchange-049"},{"speaker":"武内委員","kind":"質問","question":"私はあらあらマニュアル化されて、既に幾つかの業者ができると思っていたんですけど、できなかったのでということですか。ただ、そうなると、わずか１日２時間だけで本当に習得できるのか。","respondent":"片田防災まちづくり事業部長","answer":"それを、やはりその辺のノウハウをお伝えするような場を複数回また検討していきたいということで考えております。設置した例なんかも一応紹介をしながら、ちょっとそういう技術的なところ、あと相談の受け答えができるような対応を考えていきたいと考えています。","id":"exchange-050"},{"speaker":"中塚副委員長","kind":"質問","question":"なので、進まない理由をどう考えているのか改めて伺いたいと思います。これはシェルターですから住民の命を守ろうということそのものはやっぱり大事なことだし、しっかり進めていかなきゃいけないとは思うんですよね。","respondent":"品川防災整備担当課長","answer":"進まない理由というところもありますが、今回３・１１を踏まえまして、耐震診断は大分申込件数が多くなっております。その業者からまた品川シェルターを広げていただくというような形をとっていくためにも今回講習会を考えております。","id":"exchange-051"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"デザインといいますか、生活の中でなじみやすいような使い方というか、いろんな角度でしっかり検討してやっていく必要があると思うんですよね。今、しっかり位置づけて改善策を進めていくというふうにぜひ位置づけていただきたいと思うんですけど、もう一度いかがでしょう。","respondent":"品川防災整備担当課長","answer":"委員おっしゃるとおりいろいろ品川シェルターもまだまだ課題はあると思います。いろいろそういった課題を踏まえまして、今後制度等研究はしていきたいというふうに考えております。","id":"exchange-052"}]},{"id":"topic-08","title":"武蔵小山駅周辺地域街並み誘導指針（案）","agenda":"武蔵小山駅周辺地域街並み誘導指針（案）","exchanges":[{"speaker":"井上委員","kind":"質問","question":"それに加わったんでしょうけど、ここはもう少し幅広く声をかけていただく機会を設けてほしいと思いますが、これについてはお願いしたい。お願いする問題じゃなくて、すべしという意見ですが、どうか尋ねました。","respondent":"三宅都市開発課長","answer":"２点目ですけれども、こちらは先ほどのまちづくりマスタープランの地区別の方針というところでもございましたけれども、掲載するのとあわせて。必要な内容につきましては、適宜その内容に反映していくようなことも今後考えていきたいと考えています。","id":"exchange-053"},{"speaker":"井上委員","kind":"質問・要望","question":"１点目なんですけど、誘導という行政が一方的にそういう印象を持たれるような、そういう言葉ではないものがいいのではないでしょうかという意見です。そのスカイライン、そのスカイラインをどういうふうに考えるのかという、ぜひむだだと思わないで何とか対応していただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"伺いたいのは、それが住民要望の反映だと区は考えていらっしゃるのか、この点を伺いたいと思います。そこをちょっと伺いたいんですけども、一番ねずみ色が濃いと言ったらいいんでしょうか、１４０ｍなんか尋ねました。","respondent":"三宅都市開発課長","answer":"具体的にどんな建物にして段階的に建て替えをしていったらいいかというような商店街の検討もありますし、地元のまちづくりの気運を反映した。それから１１ページの色分けですけれども、商店を含めて色濃いところも全部含めて、全部想定をもとにやっております。","id":"exchange-055"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"１４５ｍ、航空法いっぱいの高層ビルが住民要望の反映なのかと伺ったら、くみ取ったものだとご説明がありました。１４５ｍ航空法いっぱいの超高層ビルではなくて、人の生活が息づくというんですかね、こういうまちを願っているわけですよね。","respondent":"三宅都市開発課長","answer":"２点目のほうからご説明いたしますと、これはあくまでもイメージですが、白いところからいくと図面上は１４０ｍ程度です。というふうに、拠点性と表裏一体となった高さということで、こういったイメージをお示ししているものです。","id":"exchange-056"},{"speaker":"中塚副委員長","kind":"質問","question":"そういう幻想をいまだに現実的にお考えなのか伺いたい。本当にそういう中でポテンシャルが高いから人が集まると、そういうのをどういう根拠でお考えなのか。","respondent":"三宅都市開発課長","answer":"２点目の将来の見通しですけれども、商店街の、ご自身でも活性化を課題に挙げてあります。まさに協働で地域を盛り上げていくにはどうしたらいいかということを一緒になって取り組んでいきたいというふうに考えております。","id":"exchange-057"}]},{"id":"topic-09","title":"その他","agenda":"その他","exchanges":[{"speaker":"井上委員","kind":"質問","question":"前回の説明会のときの区民の方たちのご理解、どんなことを言われたのか、それについてと、１６区で説明会を開催ということは、大田区と品川区の調査結果で拡大をするということは決定をしたということなのか、それはどこで決定をされたのか、そこを説明を求めました。","respondent":"太田品川区清掃事務所長","answer":"これは１１月２９日の委員会においてご説明をしているかと思いますけれども、これについては１１月１５日の区長会総会において確認をされています。","id":"exchange-058"},{"speaker":"井上委員","kind":"意見","question":"１点、一部事務組合のホームページで公表されるというのは当然なんですけれども、それを区のほうでリンクを張って、区でもちゃんと見られるようにということはやっていただけるのかどうかとの意見を述べました。","respondent":"太田品川区清掃事務所長","answer":"現在でも私どもも１１月２４日のときからホームページで掲載しています。それから環境省のほうに必要な部分についてはリンクを張ってありますので、当然焼却の部分についてもリンクを張っていく方向で考えているところです。","id":"exchange-059"},{"speaker":"井上委員","kind":"質問","question":"当然リンク先にはあるんですけれども、特に東日本大震災に関連してとか、ああいうところにちゃんとわかるようにしていただいたほうがいいというふうに思うんですが、そういう形か尋ねました。","respondent":"太田品川区清掃事務所長","answer":"それからもう一つは、新しく試験焼却が出て、清掃一部事務組合でアップしましたら、同時に区の新着情報の真ん中に新たに張ります。そこで、資源リサイクルのところに飛ぶように、こういうリンクの張り方をしています。","id":"exchange-060"},{"speaker":"井上委員","kind":"質問・要望","question":"区が独自にやった以外に区民の方から、例えば八潮で、八潮はちょっと高かったことは事実だと思います。区民の要望で、ちゃんとご報告できたのか、その辺をちょっと確認させてください。","respondent":"野呂瀬環境課長","answer":"あくまでも区の方針は１ｍの高さではかりました。結果的にはそれも含めて基準値以下だったです。","id":"exchange-061"},{"speaker":"井上委員","kind":"意見","question":"今は落ち着いているので今の状況だと思いますけれども、まだ完全に終わったわけではないので、これでよしということではなくて、アンテナを張っていただいて対策のほうをよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"１,１４１カ所測定したというご説明ですが、そのすべてがホームページに出されているんでしょうか。ぜひ今後も測定したら速やかに公表してほしいと求めましたので、その点だけ確認します。","respondent":"野呂瀬環境課長、稲川委員長","answer":"それで、すべてのところで安全でありましたということは結論として最初に申し上げてあります。それについては区のほうとしても今後もこれでおしまいということではなくて、それから感謝の言葉もいただいているところです。以上で、本日の予定はすべて終了いたしました。","id":"exchange-063"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/142731?Template=document&Id=4028#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":69222,"voices":189}},{"id":"h24-20120123-9","meetingId":"h24-cm01","date":"2012年1月23日","dateIso":"2012-01-23","committee":"文教委員会","time":"午後１時００分～午後２時２９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を25件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"今、杉並区で移動教室の経験があると伺ったんですが、全体像がわかると、特に杉並でやっているから大丈夫というものなのか。ちょっとその辺の審査の中身、あと決定理由とかがわかったら説明を求めました。","respondent":"和氣学務課長","answer":"品川荘以外にもいくつか、例えば北区はこね荘とか伊東倶楽部とか中央区伊豆高原荘であるとか、こういうところを請け負っている会社です。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１から８までというのは、どういう、これも皆さん貸付の施設なんですか。そうでもないんか尋ねました。","respondent":"和氣学務課長","answer":"それから、移動教室に関しましては、借上げをしますので借上げの契約をします。それから、移動教室について、そういうことで仕様書で詳細に定めてまいりたいというふうに考えてあります。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"仕様書を交わしていくということです。ちょっと今の移動教室の委託の部分で、この施設管理をするところに具体的に移動教室で委託をするということは、具体的にどういうふうな感じか尋ねました。","respondent":"和氣学務課長","answer":"具体的には例えばテントの管理であるとか、キャンプファイアーの補助であるとか、こういう組み立てをするということです。","id":"exchange-003"},{"speaker":"木村委員","kind":"質問","question":"これは区から民間にあれするわけですけれども、これ、契約内容となっているのは毎月いくらかという感じでやるんでしょうか。そういうのはわかりますか。","respondent":"和氣学務課長","answer":"区民委員会でのご議論になるかと思うんですけれども、基本的には貸付ですので、契約ではないんです。貸付でその際に覚書で、例えば利益があがった場合にそのうちの何％をもらうとかという、そのような覚書を交わすようになってあります。","id":"exchange-004"},{"speaker":"木村委員","kind":"質問","question":"利益が出れば５０％をいただくという形だと思うんです。それで間違いないか尋ねました。","respondent":"和氣学務課長","answer":"パーセンテージについては今まだ交渉中だと思いますので、それも地域活動課のほうで今取り組みをしているところだと思いますけれども、基本的にはそういうことでございまして、あくまでも無料貸付になりますので、その範囲内でということになります。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問","question":"ちょっと調べたら人材派遣会社となっていたんですけれども、保育所に関する実績とか、質の担保がどういうところでされるのかを教えてください。どういう経過でここに決まったのかということと、認証に関してですけれども、説明を求めました。","respondent":"伊崎待機児童対策担当課長","answer":"質の担保につきましては、当然認証保育所ですので、東京都の実施基準に基づいて監査が入ります。来年度につきましては、ただいま認証保育所の開設を検討中のところですので、まだはっきりとここでという形ではお伝えできるものではございません。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"確認","question":"１階は埋まっているんですか。ちょっと環境を聞きたいのと、近くに子どもが遊べるような公園とかが確認されているのかどうか、その辺も説明を求めました。","respondent":"伊崎待機児童対策担当課長","answer":"基準でいいますところのほぼ５分だったか、範囲に公園がございまして、そちらで園庭がわりに使うということで聞いております。これは確認はしておりませんが、そういう環境にありますので、かなり友好的というか、好意的に対応してくださるところとは聞いております。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問","question":"開設に当たっての補助金がどんな項目があるのか教えてほしいのと、あと、今後の周知について説明を求めました。","respondent":"伊崎待機児童対策担当課長","answer":"開設の補助金ですが、こちら最終補正でご提案する予定ですので、詳細はこの場では控えしますが、内装経費のほうの補助金を計上しております。それから、周知ですが、２月１日号の広報で周知をする予定です。","id":"exchange-008"},{"speaker":"阿久津委員","kind":"質問","question":"けいひんファミリークリニック、よく使わせていただくので非常にいいところにできるなというふうに思っています。募集の時期と保育料、年齢によって変わってくると思うんですけれども、わかる範囲で教えてほしいと求めました。","respondent":"伊崎待機児童対策担当課長","answer":"募集は広報での周知の後ということにはなっておりますが、詳細いつからということは申しわけありません。数字のほうはいただいていないんですが、当然上限８万円という規定の中でやっていきますし、こちらも区の保育料補助の対象となる施設です。","id":"exchange-009"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"先ほども説明いただきましたが、子どもたちの学力のところで、品川区が平均を上回る効果が上がっている。不登校に関しても、数値的にわかれば、減ったということに関して具体的にわかれば教えていただきたいのでお願いします。","respondent":"冠木指導課長","answer":"今後、そういった取り組みを各学校全体に広めることによって、さらに英語の力をつけるように進めてまいりたいというふうに思っているところです。中学校におきますと、ここ３年の中で品川区のデータとしましては２.９％台から２.６％台に抑制をされているという状況があります。","id":"exchange-010"},{"speaker":"渡部委員","kind":"質問・要望","question":"もうちょっと詳しくお伺いしたいことについて、児童・生徒評価の導入で、しようとしているのかというのを教えていただきたいのがまず１つ。もし教えていただければお願いします。","respondent":"冠木指導課長","answer":"ご助言が、学校のマネジメントに活かされるような取り組みをこれからしてまいりたいというふうに思って、ここに書かせていただいたです。７グループ１１校ということで学校と今、連携型、それぞれにバランスよく指定をする予定です。","id":"exchange-011"},{"speaker":"渡部委員","kind":"確認","question":"ちょっと４つ独立な形に見えてしまったので、確認だったんですが、そういう考えでいいのかどうかをもう１回お願いいたします。平成２４年度から始めるに当たって、例えば今の段階では平成２４年度ではこの辺までというのは、説明を求めました。","respondent":"若月教育長","answer":"委員のご質問、それをご説明するに当たって、先ほど来のご質問に関連づけてお答えをしたいと思います。小学校が、中学校の教育というのはこういうふうになるということを認識しながら、若干あまりにも発達段階が違いますから焦点がぼやける可能性がある。","id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この間の『プラン２１』のところでどうだったのかというところをちょっとお聞かせいただきたいのと、また、自分に自信が持てる。極端に自己肯定感がないというあたりをすごく重視して見られていたので、その辺のところはどうなのかなと思って、この２点をお伺いします。","respondent":"冠木指導課長","answer":"それにはどういったカリキュラムのマネジメントをしていく必要があるかといったところで、今後進めてまいりたいというふうに考えているところです。","id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"よりよいものになるのではないかなと思ってお伺いしたんですが、皆さんが現在でもそうですよね、力を合わせて子どもたちのことを考えている。改善をしていくことが必要なんですが、やはりそういう姿勢が欠けているのではないかなと、私は端的に思うんですがいかがか尋ねました。","respondent":"若月教育長","answer":"ある１つのことをやったら全部なくなるなんて、そんなおとぎ話みたいな世界はないわけでありまして、新しい課題というのは常に出てきます。選択制、一貫教育、さまざまな声が多いとおっしゃいましたけれども、私は多いとは全く思っておりません。","id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"何かとにかく頑張っているんだから見ててほしいというのでは、それこそ外部評価制度の充実とかにはならないと思うんですよね。これは何回やりとりやっても同じだと思うので、意見として言っておきますけれども、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"須藤委員","kind":"質問・要望","question":"雨の中、ここの教育自体がそういうことを１つ１つクリアしているから、あえてそういう点を承知しながらの質問なんだけれども。第IVステージ云々といったときに、そういったことも考えてもらえたらどうかなというふうに見ているんですけれども、いかがか尋ねました。","respondent":"和氣学務課長、若月教育長","answer":"一般の方が入れなくなってしまうということですね。そこに象徴的なように、十分そこら辺も含めて検討させていただきながら、今後の対応を考えてまいりたいと思います。したがいまして、何かあったときにはすぐに対応ができるようなそういう心づもりだけはしておく必要があるなと考えています。","id":"exchange-016"},{"speaker":"須藤委員","kind":"質問・要望","question":"世界へ羽ばたく子どもになってほしいよというのは、この間、子どもというのは本当にスポンジでどんどん吸い取るようにやっていく。なおさらそういうものを聞いても、ああ、うちはもう既にそこまでいってるぞというような思いでいられるように頑張っていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"阿久津委員","kind":"質問","question":"お話を伺って、本当にそのとおりだなと。やはりそういうお話を伺うものですから、わかりやすい、このことに関してはどういうふうにお考えになっているのかをお聞かせいただけたらと思います。","respondent":"若月教育長","answer":"私たちは１４年余、この『プラン２１』に必死になって取り組んできました。これは大いに反省をするところです。","id":"exchange-018"},{"speaker":"木村委員","kind":"質問・要望","question":"今、そのようにして成績がいい方向に行っているにもかかわらず、どうして月に２度の授業が増えるのか。これをもう一度はっきりと教えてほしいと求めました。","respondent":"冠木指導課長","answer":"品川教育を進めていく中で、当時削られていた部分も当然その時代、入れて取り組んできたという状況があります。中学校の授業時数、いずれにしましても、子どもたちの学習状況をさらにもう一歩進めていきたいといった思いでの土曜日の授業です。","id":"exchange-019"},{"speaker":"渡辺副委員長","kind":"質問","question":"伺いたいのが、どのような思いというか、地域力というのがどんなふうに教育委員会としてとらえられているか。それを伺いたいと思います。","respondent":"冠木指導課長、若月教育長","answer":"まちの人の授業であるとか、そういった意味でかなりの、毎年１,０００件近いそういったご協力をいただいているところです。第IVステージにおいてもその考え方には変わりはございません。 今までの実践は、そういうことが頼みやすいような人間関係づくりの期間だったというふうに考えていただいてもいいかもしれない。まさに、ご理解をいただければと思います。","id":"exchange-020"},{"speaker":"浅野委員長","kind":"質問","question":"ほかにはご意見ありますでしょうか。３つお伺いしたいんですけれども、例えば今の質問にも関連してくるんですけれども、アピールも含めてお伺いしたいのが１点あります。","respondent":"冠木指導課長、田村教育次長","answer":"例えば８３運動であるとか、ああいった地域を一体とした取り組みによって、区のホームページなどにも出させていただいているところです。個々の課題、例えば持久力等々の課題は若干あるんですけれども… 先ほど教育長のご答弁でもあったんですが、第IVステージについては、あくまでスタート時があれなので、おおむね教育長の私見ですが、二、三年を１つの計画期間と考えております。","id":"exchange-021"}]},{"id":"topic-03","title":"行政視察の報告書","agenda":"行政視察の報告書","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"前のまとめのときに、ぜひ行程表を載せていただきたいと希望したんですが、なぜ載っていないのか。日程とどういう行程で動いたのかというのが最初のページにちょこっとでも入ったら、他委員会では入っているようなんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"全部とは言いませんが入っていました。ぜひ次に活かしてほしいと求めました。","respondent":"浅野委員長","answer":"この件については正副委員長でちょっと検討させていただきまして、また皆様にお伝えさせていただければと思います。大幅な変更、しっかりとまた正副委員長のほうで検討していきたいと考えておりますので、よろしくお願いいたします。","id":"exchange-023"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"飯沼委員","kind":"意見","question":"児童センターのことなんですけれども、１０月から大規模改修が行われている中での休館ということなんです。ちょっとその辺との意見を述べました。","respondent":"安井子育て支援課長","answer":"こちらについてはエレベーターのほうはちょっと。なかなかエレベーター等はつけられないような状況なので、こちらについてはそこまでの大規模改修は組んでございません。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問","question":"児童センターとかの改修で大規模のときとかは、基本的にはそういった面は検討されるんでしょうか。もう１回そこのところを説明を求めました。","respondent":"安井子育て支援課長","answer":"４階というところを使っているというのが非常に多いので、そういった面では前に検討したことがあるんですけれども、そういった意味での検討というのは改めてしておりません。","id":"exchange-025"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/162678?Template=document&Id=4750#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":28745,"voices":80}},{"id":"h24-20120123-5","meetingId":"h24-cm01","date":"2012年1月23日","dateIso":"2012-01-23","committee":"総務委員会","time":"午後１時００分～午後３時２３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件整理しています。","topics":[{"id":"topic-01","title":"の「地域主権改革」による権限委譲等への対応","agenda":"の「地域主権改革」による権限委譲等への対応","exchanges":[{"speaker":"塚本委員","kind":"質問","question":"３ページの第１回定例会に上程を予定しているということで法令が出ているわけですけれども、これはここで４月に成立をすれば、そういう具体的な法律にかかわる側の方々の行動が変わってくるということがいきなり起こるたぐいのものなのか尋ねました。","respondent":"榎本企画財政課長","answer":"ここの１０法令の1)番の墓地、今まで都条例で定められたものが区条例になるということで、そういうようなことはないかと思います。そういう形であれば、窓口自体は変更がないという形で、基本的にはそんなに大きな影響はないというふうに考えています。","id":"exchange-001"},{"speaker":"塚本委員","kind":"質問","question":"じゃあ、ついでに区として今まであった基準をもっとこうしようああしようとか、そういうことはあんまりないと考えればいいか尋ねました。","respondent":"榎本企画財政課長","answer":"全然ないというわけではないんですけれども、基本的には今までのものとそんなに大きな変化がなくという形で考えているところです。","id":"exchange-002"},{"speaker":"原委員","kind":"質問","question":"今、塚本委員からもお話があったように、逆の見方で、ある団体なんかからは、条例化しろというような意見が出てくる可能性もあるのかなと思うんですけれども、その辺についてお考えがあれば説明を求めました。","respondent":"榎本企画財政課長","answer":"そういう要望事項があるというのは聞いておりますけれども、その部分も十分考えた上で、実際には条例の提案をするということで準備をしています。それが現状、都が持っている条例と、その辺を検討した上で条例の審議にさせていただきたいというふうに考えています。","id":"exchange-003"},{"speaker":"原委員","kind":"質問・要望","question":"まだ具体的な話という形ではなってきていないのでしょうけれども、あまり硬直化しないように、またそれだけではなくて、権限関係のほうも強くなり過ぎないようにということも配慮していただきたいので、その辺をもう一歩何かご意見があればお願いしたいと思います。","respondent":"榎本企画財政課長","answer":"きちんと実情に合ったものを実情の中で運用していくということができるようにというのが基本だと考えていますので、権限がおりたからその権限でもって区が急に変えるとか、そのような考え方ではございません。","id":"exchange-004"},{"speaker":"阿部委員","kind":"質問","question":"ですから、やはり品川区らしさというのは今後出てくるべきであろうかとは思うんですが、区行政側としてのお考えはいかがなんでしょうか。あくまでもこれまでどおりを旨とするということなのか、やはり今後よい品川の主体性というのを出していこうという思いも少しはあるのか尋ねました。","respondent":"榎本企画財政課長","answer":"ただ、今後改正を予定していくとかという考え方ですので、その辺は十分中身を斟酌してという形になろうかと思います。平成２４年度以降につきましては、もう少し影響が大きいものが出てまいりますので、その部分を十分検討して進めていきたいというふうに考えています。","id":"exchange-005"},{"speaker":"阿部委員","kind":"質問・要望","question":"私たちも、もちろん立場上、行政に求めるだけではなくて、積極的に発言をしていきたいと考えています。今後、やはり少しずつ品川として主体性を強く出していくべき必要性があるかと思いますので、ぜひ品川区としても検討を進めていってほしいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"品川区に財政的な負担ですか、事務量増、事務の量が今度増えるわけですよね。メリットもあると思うんですが、どうなんでしょう、区へ対する負担増という問題点というのはあるんか尋ねました。","respondent":"榎本企画財政課長","answer":"平成２４年度の中でまた引き続き都と議論をして、財政措置をどういうことにしていくのかというのが、実情に応じて検討していくです。１つのＡ区ではいっぱいあっても、それは平成２４年度中に準備をして、平成２５年４月からということになろうかというふうに考えております。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問・要望","question":"それも大変なことだと思いますし、その辺、要望要請は。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"そしてまた、品川区もその立場に立ってきたから、その点についての見解をちょっと伺いたいというふうに思います。その辺について、どんなふうに、私の見方が間違っているのかも含めて見解を伺いたいと思います。","respondent":"榎本企画財政課長","answer":"今度の第１回定例会、それから平成２４年度中の条例、その部分は対応していかなければいけないというふうに考えております。都区のあり方検討というのは、その分とは直接関係ないかなというふうに認識をするところです。","id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"やっぱり必要な、そういう考え方を許さないで、そこについてはぜひ２３区の区長会のところで大いに要請もしていただきたいというふうに思います。それとあと、ちょっとこの辺をどういうふうに考えたらいいのかなというのを聞いておきたかったので、そこについて教えてほしいと求めました。","respondent":"榎本企画財政課長","answer":"やはり影響がありますので、各区対応というのは、法律的には変わることがあり得てもいいというように法律上の整理としてはされていく話です。","id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"確認のこの内容をそのまま受けとめるという場合と、意見を聞く場面をつくっていただきたいというように思っていますので、あえてそのことも触れておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問","question":"区の独自性は本当に出せるのでしょうかというのが１点。その辺で独自性はどこまで可能性があるのかなという点を先に１回説明を求めました。","respondent":"榎本企画財政課長","answer":"例えば１つ目の例に挙げた墓地、墓地が全然ない地域であれば、当然その基準の定め方というのは変わってくるのかなということで考えているところです。それらにつきましては、十分今度の第１回定例会の審議の中でご説明する予定です。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問","question":"平成２４年度は計算に入っていないのかなと、先ほどお話に出た事務処理特例交付金、これも予算決算でそこそこの数字が出ていると思うんです。これが平成２４年度予算においては一切ゼロになるということで、一切というか、この事務に関してはゼロになるということでよろしいんか尋ねました。","respondent":"榎本企画財政課長","answer":"今後もかかる予定がありますので、財調の需要額にそれを入れていくというような形の取り扱いを今のところしています。その他の権限につきましては、平成２５年の財調協議に向けて、きちんと実態を踏まえて、どういうふうにしていくかを検討するという状況です。","id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問","question":"平成２４年度の財調算定にその分は入っているというふうに考えてよろしいのか尋ねました。","respondent":"榎本企画財政課長","answer":"入っているものです。","id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ですから、２３区の総体がわからないですけれども、区としては算定が減るわけですよね。その辺のところもこれからもご努力をお願いしたいということで、その辺ちょっともう１回お願いします。","respondent":"榎本企画財政課長","answer":"例えば財調交付金の１％を超えるものであれば財調交付金の配分率自体を変える検討というのができるだろうという議論はあったんですけれども、今後どんなふうにしていけば都と協議ができるかということで検討していこうというところで、現時点では。","id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"いろいろやっぱり東京都との件で、いろいろとまっているところもありますし、区のほうでまたしっかりした対応のご努力をお願いしたいと思います。要望にします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"品川区に限らず、１つの自治体の特性というのと、どういうふうにイメージしたらいいのかなというのがちょっとわからなかったので教えていただければ。それはわからなくもないけれども、地域の特性というのはどういうイメージをして発言なさったのか、ちょっと教えていただけると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"確認","question":"大田とか港とかそこら辺のところがなかったときに品川に影響を受けてくる部分もあるのではないかと、そんな思いもあってちょっと確認しました。そうすると、２３区ある程度そろえなければいけないのかなというところの思いと、そこら辺がどう判断していくかを聞きたかったということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"南委員","kind":"質問","question":"急に済みません。そういう関係でこちらに質問なんですけれども、その辺はどんなふうに考えていこうというふうにしているのかなというのを聞きたいなと思って。","respondent":"日下部企画部長","answer":"１つの考え方は相対するような面というのはあろうかと思いますけれども、基準、全部決めるわけですね。かつての日本の地方自治の１つのやり方だというふうに言われていましたけれども、一連の大きな流れですので、このように考えております。","id":"exchange-019"},{"speaker":"金野副委員長","kind":"質問・要望","question":"確認をさせてください。これは第１回定例会に上程をされてくるものかと、それが１点確認をいただきたいのと、そこら辺をちょっと確認させてください。","respondent":"榎本企画財政課長","answer":"平成２４年度以降、それぞれどの定例会かも含めまして、準備ができたものから順次条例を上程する予定です。審議を行うものです。","id":"exchange-020"},{"speaker":"金野副委員長","kind":"意見","question":"これをもって品川区独自の、やっぱり品川区ならではのというところを目指していければと、こんなふうにも思っております。細かい具体的なことでなくても、決意というか、お願いしたいと思いますとの意見を述べました。","respondent":"日下部企画部長","answer":"独自性を発揮するだけの条件が確かに今、整いつつあります。２３区を見ましても、それはケース・バイ・ケースになりますけれども、でき得る限りのそういった努力はしていきたいというふうに考えております。","id":"exchange-021"}]},{"id":"topic-02","title":"の公共施設のコスト表示","agenda":"の公共施設のコスト表示","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"４点目、こういう対応をする区は、２３区でほかにあるのかどうか、そこを知りたいです。最後は、予想でいいんですけれども、そのあたりをちょっと教えてほしいと求めました。","respondent":"榎本企画財政課長","answer":"平成２３年度のこの施設ですが、５０施設、今、準備をしておりまして、平成２３年度の今年の３月に施設に掲示をする予定で準備を進めております。","id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"費用は６０万円という話なんですけれども、３年ごとにですから、大体年間で６０万円というふうに考えていいのかというのが確認です。そこをどういうふうに、３つに分けてやるというお話なんですけれども、その点について最後に一言伺っておきたいと思います。","respondent":"榎本企画財政課長","answer":"今までやはり財政状況等の公表というと、総論のものしかなく、これを機会にこういう形でさせていただきたいというふうに思っております。３年間の掲示ですので、３年に１回、その辺も踏まえて工夫を図っていきたいというふうに思っております。","id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"さっきも言ったように、区民の方はかなりコスト意識を持って品川区の行政あるいは働いている職員一人一人の挙動について見ていると思います。そういう点で、新たな誤解とか曲解みたいな、ぜひそういうところも踏まえて対応をしていただきたいということをあえて申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"阿部委員","kind":"質問・要望","question":"それからあと、スポーツ施設なども施設があれば表示ということでしたけれども、例えばグラウンドなんかは入らないのでしょうか。あれはあれで地価の高い品川区のことですから、考え方から言えば、やはりコストというのは非常に考えていただきたい部分ではあるんですよね。","respondent":"榎本企画財政課長","answer":"今後の予定ですけれども、平成２６年度は、図書館のデータを新しくしたものをもう１回入れ替えるということを考えております。平成２４年度に運動施設のある公園ということで予定しているんですけれども、公園の出し方が検討に上っておりまして、全部の公園を出すべきなのか。","id":"exchange-025"},{"speaker":"阿部委員","kind":"質問","question":"次にお伺いしたいのが、例えば保育園、幼稚園ということですけれども、これは認可保育園に限るんですか。それは可能であるのか、幼稚園は公立だけなのか、私立についてはどう考えるのかといったくくりというのはどうなるのか尋ねました。","respondent":"榎本企画財政課長","answer":"２０２施設、区立施設というふうに考えておりますので、幼稚園を基本として考えております。ただ、どういう形で、そういうコストがわかるような別の手段をつくれないかどうかということも検討してまいりたいというように思います。","id":"exchange-026"},{"speaker":"阿部委員","kind":"質問・要望","question":"だけれども、規模が違ったり、あるいは０歳から預かるということになると、そちらのほうが大きな数字がついています。その辺の検討はされましたか尋ねました。","respondent":"榎本企画財政課長","answer":"それをわかりやすさと個別の説明の部分をどこで調和させてこのコスト表示をするかということになりますので、今のところ。その部分でどういうふうに問い合わせに答えていくかということで、この施設の表示板を示していきたいというふうに考えているところです。","id":"exchange-027"},{"speaker":"阿部委員","kind":"確認","question":"それからもう１つ、これは玄関先の施設内に表示するということでよろしいんでしょうか。むしろそれは地域住民の方に見えなければあまり意味がないわけですから、少なくともこのパネルは施設の内側ということなのか確認をさせてください。","respondent":"榎本企画財政課長","answer":"今、その反応を見ながら、どういう形でよりわかりやすいコストを表示できるかということは検討していきたいというふうに思っております。もともとが海抜については切り離したほうの考え方で、それはより適切な場所で海抜のほうは表示をしていきたいというふうに思っております。","id":"exchange-028"},{"speaker":"阿部委員","kind":"質問・要望","question":"こういう表示をすることがマイナスに働かないように、ぜひ研修その他、改めて確認してほしいと求めました。以上、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"須貝委員","kind":"質問","question":"そういう支援をしているんだというところが、差は確かにありますけれども、そこら辺は私はやはり区としても考えてほしいなと思います。区のほうは別に法人税をおさめているわけではないですから、これ、一括で建物は償却しているはずですよね。","respondent":"榎本企画財政課長","answer":"例えば、今のところ、どこの地域のシルバーセンターも年間経費は９０５万円でしたというのを出したいというふうに考えているものです。","id":"exchange-030"},{"speaker":"須貝委員","kind":"意見","question":"その辺はちょっとおかしいと思うんですが、もう１回ご答弁願えますか。ちょっと私は納得いかないんだけれどもとの意見を述べました。","respondent":"榎本企画財政課長","answer":"それが１つと、職員に説明する説明会等、そういった部分できちんと認識をしてもらいたいということでは言っております。そういうものがきちんと納税者の負担になっているということも改めて認識をほぼ具体的にさせていきたいというふうに考えています。","id":"exchange-031"},{"speaker":"須貝委員","kind":"質問・要望","question":"終わりに、品川区はせっかくこれだけ区民に信用されて、本当に皆さんの働きによって品川区はいいよという住みやすい町だということでなっています。おまえはどうだ、こっちはどうだというようなことがないように、よろしく配慮して対応してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"原委員","kind":"質問・要望","question":"私ももう１回整理しますと、もう１回整理をしていただきたいと、これはお願いです。それは二次的な間接的な問題であって、その辺はいかがなものかというふうに思うんですけれども、ご意見があれば説明を求めました。","respondent":"榎本企画財政課長、日下部企画部長","answer":"問い合わせしてくる方は、どんな形でこういうものを出していけばいいのかということで、それぞれ検討してきたところです。平均値としてこんなものですよというものを出していきたいというところで… ちょっと補足しますと、私ども、平成２２年度、事務事業評価を実施いたしました。私どももやはりそれにしっかりこたえていくという観点で事務事業評価も実施してまいりましたけれども、今の経済状況を考えますと、今。","id":"exchange-033"},{"speaker":"原委員","kind":"意見","question":"それともう１点、再度申し上げますけれども、やはり教育と福祉というのは、いくらコストだと言っても、これはちょっと別かなというところ。特にこの２点、感じるので、この辺の項目、やることはいいと思うんですけれども、この辺をもう少しご検討いただければなと、意見としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"鈴木（真）委員","kind":"質問","question":"委託の部分の給与をどうとっていくのかというのが１点。それともそこだけの部分なのか、そこら辺を説明を求めました。","respondent":"榎本企画財政課長","answer":"委託の部分につきましては、人件費ということではなく、事業等経費の中で委託費の部分で一括で入ってくるという形です。それから、本庁との部分については、その部分は計上しておりませんので、それぞれの独立した施設ごとをグループ分けしてという形になってあります。","id":"exchange-035"},{"speaker":"鈴木（真）委員","kind":"質問","question":"シルバーセンターだと、そういう方たちがこれを聞かれたときに、どう対応できるのかなというのが非常に疑問があります。そこで今、人件費が出たときに、その人たちの人件費が乗っかっていると見られたら、また困るなということもちょっと感じたのでお伺いしました。","respondent":"榎本企画財政課長","answer":"これから説明会等やりますけれども、現場での対応というか、対応できる問い合わせ先等を準備をしていきたいというふうに考えております。その場で答えられるのが一番いいんですけれども、実際にはそこの代表者、チーフ等の部分で伝達できればというふうに思っております。","id":"exchange-036"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"何か質問を受けたときに非常に気になるなということが今の現状だと思いますので、だれもシルバー人材センターにはほとんどいないですよね。１人か２人、やり方についてもうちょっと検討していただきたいということで、もう１回お答えほしいと求めました。","respondent":"榎本企画財政課長","answer":"窓口の対応につきましては、今後どういう形でできるかというのは、所管も含めてこれから検討していきたいというふうに思っております。今いろいろとご意見をいただきましたので、その部分も含めまして、これから十分検討した上で掲出をしていきたいというふうに思っております。","id":"exchange-037"},{"speaker":"塚本委員","kind":"確認","question":"今いろいろお話をずっと伺って、最後にもう一度確認したいんですけれども、そういったところをちょっとお伺いします。","respondent":"榎本企画財政課長","answer":"その中で、今、委員からご指摘のあった両方の面での今後のあり方というものは考えていきたいと思っています。昨今の節電等の部分でどれぐらい経費削減できているのかというものも含めていろいろとご意見をいただきたいというふうに思っております。","id":"exchange-038"},{"speaker":"阿部委員","kind":"質問","question":"簡単に質問します。例えば「シルバーセンター」と書くのか、「五反田シルバーセンター」と出てくるのか、どちらなんか尋ねました。","respondent":"榎本企画財政課長","answer":"この施設名は、「シルバーセンター」で、（東品川を除く）という形で、東品川が本館で大きくなりますので、東品川だけを規模的には別扱いをして、残りの地区館を同じ扱いで「シルバーセンター」という形で載せたいと思います。","id":"exchange-039"},{"speaker":"阿部委員","kind":"提案","question":"提案が出てくるというのは、むしろ私、近年にない異例なことかなと思います。平成２４年３月と迫っていますけれども、完全に否定するわけではありませんが、その方法についてはいま一度振り返ってほしいと求めました。","respondent":"日下部企画部長","answer":"実は私ども、やはりこういうコスト表示の取り組みもしっかりとやらなければいけないのではないかということでいろいろ検討してきた経緯があります。","id":"exchange-040"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっと聞いていて１つわからなくなったので、そこについて教えてほしいと求めました。そういうところに対して、あえてここに保育園、幼稚園を入れるというところは、もう１つ伺っておきたいというふうに思います。","respondent":"榎本企画財政課長","answer":"福祉施設、やはり区立施設の中で全体で２０２施設ありますけれども、その中でどういうふうにやっていくかというところは検討の議論がありました。その部分につきましても十分検討をして、まずは中で説明をしてから示すとか、その辺も含めて今後検討していきたいと思っています。","id":"exchange-041"},{"speaker":"南委員","kind":"質問・要望","question":"やっぱり１回これぐらい個別に知っていただきたいという話で、よしんば１回掲示したりしても、やっぱりやめるべきだと私は思います。知っていただきたいということでこういう方法を考えたという、そんなような印象を受けますので、もっと精査をするべきだというふうに思います。","respondent":"榎本企画財政課長","answer":"入り口１カ所ですけれども、そういう形でそういう施設については検討していく、そのような工夫ができるのかなというふうに思います。","id":"exchange-042"},{"speaker":"金野副委員長","kind":"質問・要望","question":"も第一弾としてやっていきますというご答弁だったんですけれども、第一弾をやられるというご意志の中で、こういうことはどうなんでしょうか。さらにそこへ区民サービスの向上に努めていくというような決意文も、決意文だけではない、その思いも加えながらというところはどうなんか尋ねました。","respondent":"日下部企画部長","answer":"私の発言に対するご質問ということですのでお答えをします。この表現については、今の副委員長のご指摘の点も含めて、表現についてはまたいろいろ工夫をさせていただきたいというふうに思います。","id":"exchange-043"},{"speaker":"金野副委員長","kind":"質問","question":"イメージですから、もう少しわかりやすい表現でもしされるのであれば、工夫をされたらいいのではないかと思います。意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/579213?Template=document&Id=1904#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":49551,"voices":99}},{"id":"h24-20120124-14","meetingId":"h24-cm01","date":"2012年1月24日","dateIso":"2012-01-24","committee":"行財政改革特別委員会","time":"午後１時００分～午後４時００分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を65件整理しています。","topics":[{"id":"topic-01","title":"の１、特定事件調査を行います。 初めに、(1)の区の組織と関連団体に関すること","agenda":"の１、特定事件調査を行います。 初めに、(1)の区の組織と関連団体に関すること","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"質問は特にないので、なぜ外郭団体をわざわざつくらなければこの事業ができないのかと、それが一番の疑問です。各種法人を含めて、関連団体に対する区幹部の天下りの実態が問題だと思いますので、住民目線に立った見直しと改善こそ必要だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問","question":"品川文化振興事業団、スポーツ協会、国際友好協会、３件に共通して伺います。そういう特色を出して青少年ホームステイ事業をやっているのかどうかということの参考にしたいものですから、雑駁で構わないので伺いたいと思います。","respondent":"安藤文化スポーツ振興課長、今井協働・国際担当課長","answer":"類似事業ですけれども、例えばメイプルセンターでカルチャー講座が７００講座ぐらい実施されております。東京都のスポーツ協会、体育協会などそういうところといろいろな連盟とか、共通の事業とか連携事業等も実施しています。品川区として在住外国人を教える立場から、友好協会と連携して、民間団体ではできない部分を支えていきたいというところがあります。","id":"exchange-002"},{"speaker":"渡辺委員","kind":"質問","question":"どういうふうに集約をして事業を絞っていくのかというところで、もう１点伺うと、年月もかなりたっている。そんなことのやりとりは、どういう比率でというか、どういうことを意識されているかどうかを伺いたいと思います。","respondent":"今井協働・国際担当課長、安藤文化スポーツ振興課長","answer":"やはり日本語の充実という形で考えておりますので、国籍別というよりも、地域に親しんでいただくということを考えてやっているところです。今、実際に事業をどういうふうに工夫して進めていくかにつきましては… 参加者の方すべてを対象にしていましたけれども、高齢者の部としてソフトバレーだとか、そういうものを設けたりもしております。そんな中で高齢者に合ったスポーツというものを拡充しています。","id":"exchange-003"},{"speaker":"原委員","kind":"質問","question":"この３団体、前にも質問したことがあるかと思うんですけれども、そこだけスタートの段階でもう一回お教えください。","respondent":"安藤文化スポーツ振興課長、今井協働・国際担当課長","answer":"それで準備を進め、この５月、６月に申請をしたところです。そしてこの平成２４年４月を目標に、今、準備を進めているところです。 ８月３０日の東京都の公益認定等審議会におきまして、友好協会が公益認定に相当であるとの答申をいただいております。ですので、ほかの財団と同様に、平成２４年４月１日には財団法人への移行という予定です。","id":"exchange-004"},{"speaker":"原委員","kind":"質問","question":"そうすると、平成２４年４月１日以降は内閣府に移るという解釈でよろしいか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"４月１日以降も東京都の所管になります。","id":"exchange-005"},{"speaker":"原委員","kind":"確認","question":"そうしたら、委員間で話していく上で、今後は先のことを考えるとすれば、５０％以上の公益目的事業を持ったというところをもう一回確認します。","respondent":"安藤文化スポーツ振興課長、今井協働・国際担当課長","answer":"公益目的事業につきましては、文化振興事業団については、申請当時７２％以上の公益目的事業を、スポーツ協会につきましては９２％以上の公益目的事業です。 品川区国際友好協会につきましては、公益目的の事業比率は８６.１％ということで、評議員会のほうでも報告しております。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"今、そこだけ補足させていただきたいと思って意見を述べするんですけれども、そういう取り組みの要望がすごく強いなと思っているんですね。ただ、なぜこの組織なのかなという区とのかかわりは、しっかりと住民目線に合った見直し、改善が必要だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"渡辺委員","kind":"質問","question":"１点だけ質問を。直営で行政が本来やるべきことだけれどもという算定、比較的なことというのは、そういう算定はしているのかどうか。","respondent":"安藤文化スポーツ振興課長","answer":"ただいまのご質問なんですけれども、例えばスポーツ協会で言いますと、総合体育館、戸越体育館を指定管理として平成１８年度よりやってまいりました。ここには書いてありませんけれども、区民の方々２００人程度を募集をして、視点にはそこら辺も入っていると思います。","id":"exchange-008"},{"speaker":"渡辺委員","kind":"質問・要望","question":"細かい数字という求めではなくて、あるいはサービスの質の向上というメリット、これは直営であるケースを想定しているかどうか。こうやって団体等の区からの助成との関係もあるので、こうやることでメリットになるよという言い方の答えをいただけるとありがたいなと思いました。","respondent":"榎本企画財政課長","answer":"区職員が直営でやったほうがいろいろなものに対応できるということでやってきましたけれども、省力化してやっていくということになってきています。対前年度もしくは直近５年間ぐらいを見ながら、すぐにこれぐらいの効果が出ているというのは、持ち合わせておりません。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問・要望","question":"確認をさせていただきんですが、区からのやっていただきたいという内容、業務委託というのがありますね。そうすると、自主事業のために国際友好協会にはこれらの助成金がありますよというふうに読み取ったんですが、そういう考え方でよろしいんか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"これは以前、８月等のご説明した表をもとにつくらせていただいておりまして、ちょっと線の引き方でわかりづらいところがあるのかなと思います。ちょっと見づらくて申しわけございませんけれども、そういう形です。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問","question":"それに対して助成をされているということになるんですよね。採算性のあるものとしてやってほしいよということなのか、お金をかけて、位置づけはどういう関係なのか尋ねました。","respondent":"安藤文化スポーツ振興課長、今井協働・国際担当課長","answer":"それについても基本的には受益者負担という形で考えております。できない発表会とか、そういう質の高いコンサート等については、低廉な価格で区民の方に楽しんでいただくという考え方です。 例えば先ほどご説明申し上げました括弧に入っている英会話教室などは、これは区からの助成金がなくて、参加者の負担金だけで全部運営しているという形になっております。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"そこを区としてどういう考え方でこれだけのお金を毎年助成しているのか。こういう明確な考え方があって助成しているんだよということがあるならば、ちょっと教えてほしいと求めました。","respondent":"今井協働・国際担当課長","answer":"海外の姉妹都市の派遣事業等につきましては、本人にかかわる負担率というのは基本的には４割負担という形で考えておりまして。やはり品川区の基本方針のほうにも外国人に開かれた社会ということがありますので、補助金という形では多めに助成している形になっております。","id":"exchange-012"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"この３団体において、主にその２つがテーマだったのかなと思うんですが、改めてお聞かせほしいと求めました。","respondent":"安藤文化スポーツ振興課長、今井協働・国際担当課長","answer":"そんな中で、文化振興事業団が有効にきゅりあんの管理しているというふうに考えております。総合体育館、スポーツ協会の設置目的であります品川区民のスポーツ・レクリエーションの向上のために、まさにメリットがここにあると思います。現在も交流の相手先は、ジュネーブ・品川友好協会という任意団体が立ち上げられておりまして、団体同士の事業の細かいところでの調整をしております。","id":"exchange-013"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"例えば２年に一度だったり、３年に一度、これだけの経費がかかっている。はこれからそういった対照をやるつもりがあるのか、改めて説明を求めました。","respondent":"久保田行財政改革担当課長","answer":"毎年もやっていますし、３年目もやっています。地域の方と連携を図りながらそういったものを進めているといったところは、業務委託をする上では非常にメリットのあるところだと認識しています。","id":"exchange-014"},{"speaker":"石田（慎）委員","kind":"提案","question":"最後に１点だけ。協会からの事業の提案であって、区からは一切こういった事業をやってほしいというのがないのか、そこだけちょっと説明を求めました。","respondent":"今井協働・国際担当課長","answer":"区と市がそれぞれの方針を立てて合意をした内容に応じて、評議員会、理事会を通して検討しています。青少年ホームステイ事業につきましても、例えばどういう事業内容にするかは友好協会が詳細を決めているという形になります。","id":"exchange-015"},{"speaker":"石田（慎）委員","kind":"質問","question":"そうなると、友好協会が例えばこの事業はなかなか採算性もとれないといった部分で、やめますと言ったときに、区としてはどのような対応になるのか尋ねました。","respondent":"今井協働・国際担当課長","answer":"現状では３都市との協議の中で、公益財団法人の移行に伴って、さまざまに交流のあり方を協会とともに協議してまいりました。ですので、友好協会が一方的にこの事業をやめたいという形では、今のところ、事業の進み方はないという形になっています。","id":"exchange-016"},{"speaker":"石田（慎）委員","kind":"質問","question":"国際友好協会においては業務委託は一切ないということは、あくまで協会がその事業を推し進めていこうと思っているからこそ、自主事業で進めている。この３つの団体の中で、ほかの２つの団体とは業務の内容が違うからこそ変わってきてしまうのかなと思うんですが、その辺はどのようなことか尋ねました。","respondent":"久保田行財政改革担当課長","answer":"予算査定の中でも、区の方針としてそれが必要かどうかということもきちんと査定をいたしまして、必要があればそれに対して助成を出すということです。補助事業と委託事業の差というのは、そういったところです。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"そのとおりいったかどうかというのは別にしても、そういうところがあるわけで、そういうのが違うなと思いました。意見を言ってばかりではあれなので、この国際友好協会と品川区スポーツ協会、それぞれご意見を伺いたいと思います。","respondent":"日下部企画部長","answer":"限られた財源の中で、やはり受益者負担の考え方ということをもっと区民の皆さん方にご理解いただくべきでありますし、それ相応のご負担をいただく。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"その視点をぜひ踏まえていくべきじゃないかという意味で言ったんですけれども、ご理解いただけないでしょうか。お伺いします。","respondent":"日下部企画部長","answer":"受益者負担、丸々１００％負担しろということではなくて、利用される方がどの程度ご負担いただくのか。もちろん税負担も含めて、どこでどうバランスをとっていくか、これが非常に重要な課題であると認識をしております。","id":"exchange-019"},{"speaker":"西本委員","kind":"提案","question":"じゃあ、それをやってくださいね、やっていろいろな意見を言ってよ、提案してくださいよと、今の協働事業は提案型なんですかね。今、それについて何か明確なコメントができるのであれば、それを教えてほしいと思いますとの意見を述べました。","respondent":"久保田行財政改革担当課長","answer":"別の問題なのかなということでございまして、友好協会の助成金のお金をそちらからという考えは今のところはないです。そこは明確に分けているです。","id":"exchange-020"},{"speaker":"西本委員","kind":"質問・要望","question":"ここで答えを求めるつもりはないんですけれども、それを今回、皆さんと討論したいと思います。今回は意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"渡辺委員","kind":"質問・要望","question":"今、明確に何人ですかという答えを求めているんじゃないんですが、文化振興事業団のやっている事業というのはすごく見えるんですね。それぞれ例えば品川区がどうしても助成金を出してこだわりというか、特色というか、政策的に意味をまず再確認したいのが一つ。","respondent":"今井協働・国際担当課長","answer":"日本語教室のほうは１５０人程度の参加者という形で、英会話教室のほうは人数が多めですので２５０人という形になっております。お国自慢料理教室のほうは全体で１００人程度という形になっております。","id":"exchange-022"},{"speaker":"渡辺委員","kind":"確認","question":"その中で、品川区国際友好協会がやることが大事だという視点を確認で伺えればと思っています。その辺、今、国際友好協会の取り組み、区が助成金を出す意味合いを再度強調していただけたらいいなと思って、質問としてお聞きします。","respondent":"今井協働・国際担当課長","answer":"品川区との交流を通して、品川区が世界でも認識される都市であるということ、それから国際親善というのが一番大きな目的です。ただ日本語教室や英会話教室、そこを友好協会が品川区の民間交流の起点となって事業を進めていくというところが大きな政策目的、区としての方針です。","id":"exchange-023"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"でもやっぱり縮小してきているなと思っていらっしゃるのか、それをぜひ課長の感覚でお聞きしたいのが１番と２番。アプローチの仕方が悪いのであれば、だからここでそういう話が出てきちゃっているのかなといつも思っていて、まずそこら辺の感覚を教えてもらいたい。","respondent":"今井協働・国際担当課長","answer":"これまでですと、親善訪問団の例えば大井権現太鼓ですとか、スポーツなどの大きな区民の方々の団体の協力を得て実施していたというのが実際です。","id":"exchange-024"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"どうも区長をはじめ縮小だろうというふうに見えるから、何をやっているの国際友好協会、それはぜひお願いしたいということだけ言っておきます。答弁は求めないけれども、私はそう思っているということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"原委員","kind":"質問・要望","question":"ちょっと確認をさせていただきたいのは、ある程度さきの２団体に関しても当然ありますし、行財政改革特別委員会ですからはっきり言ってしまえば。ですから、公益団体なんかはすごい数あるわけですから、ほかの委員の方はその辺はお思いにならないですかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"西本委員","kind":"意見","question":"いいねというのは、それは大きなメリットだと思っているので、それはちゃんと整理して上げるべきなのかなという感じがします。最近やっている事業というのは、それなりに国際化という形を踏まえてやっていますのでとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"原委員","kind":"確認","question":"確認なんですけれども、区が助成をしているということは税金が入っているということですから、区の関係者には費用が出ていない。会合とかに行っても、逆に団体は持っていないというのは当たり前の話ですよね。","respondent":"久保田行財政改革担当課長","answer":"区の関係者には出ておりません。","id":"exchange-028"},{"speaker":"原委員","kind":"質問","question":"そうしましたら、さっき副委員長もお話ししていたように、公益性をどんどん目指していくのであれば、今後においてはこういう団体はどんどん独立性を持って、ドネーションを集めるとか、そういう展開をされていったほうがいいような気がするんですけれども、いかがでしょうか、というのが私の考えです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"山元委員","kind":"質問・要望","question":"この３団体というか、もうちょっと拡大というか、そういうのはどうなのかなと。その辺は見直しをしていただきたいし、努力していただきたいなと、自分自身はそんな実感をしています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"鈴木（博）委員","kind":"意見","question":"１番とか２番というと、ちょうど僕がまだ若い、何かそれをまだ随分引きずっているみたいな感じだなという気がするんですね。そういうことをすると、非常にみんないいんじゃないかなということをちょっと今、お話ししましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"必ず私はそういう意味で、結果は後になってわかるだろうけれども、拡大していくべきだなと。今、鈴木（博）委員のトロントの話を聞いて余計そういうふうに思ったとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"沢田委員","kind":"意見","question":"３番の啓発普及事業は、そういうのはどこまで区でやるべきかとか、友好協会でやるというのはどこまでやるのかなというのはあるかなと思いました。その辺はどうなっているのかな、どうされていくのかなと、それは意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"沢田委員","kind":"意見","question":"無料というのがちょっとどうなのかと思うんですね。ある程度の負担を、減額していくという部分はいいと思うんですけれども、ある程度の負担はしていかなくてはいけないんじゃないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"阿久津委員","kind":"確認","question":"担当課長が帰られてしまったので、もしおわかりになれば確認をしたいと思います。オークランド市は１５周年派遣をやっておりますけれども、増えているんですか、減っているんか尋ねました。","respondent":"桑村総務部長","answer":"５年ごとにやっていますので、それが５年なのか１０年なのかはまた別として、どういう対応するかということが決められるのだと思います。もう少し実際上は、この間の大震災等で人数が減っているかもしれませんけれども、通常の場合はもっと行っているかなという感じです。","id":"exchange-035"},{"speaker":"阿久津委員","kind":"質問","question":"ですから、私としては淡々と今の形を続けていけばいいのかなという印象を、今日のご説明を受けてそのように感じました。もし拡大路線となった場合には、区からの助成金というのは当然増やしていくというお考えでいらっしゃるのどうかというのをお聞きしたいと思います。","respondent":"榎本企画財政課長","answer":"寄附金は例年いろいろな目的でいただいておりますので、国際友好のために使ってほしいということであれば、その目的に応じた寄附を受け入れて、その事業のほうに充てていくという形ができております。","id":"exchange-036"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"たまたまそれはきっかけがあったから。私はそういう民間交流の仕掛けが増えていったときには、もしその助成金が増えるのであれば、拡大で増やしていくべきだと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"阿久津委員","kind":"意見","question":"政策判断が行革の場でどうかというのはちょっとわからないんですけれども、なかなかこの場で増やす、増やさないというのは難しいのかなというのが印象ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"石田（慎）委員","kind":"意見","question":"課長が一生懸命頑張っているというのは、どうしても矛盾に感じてしまい、だったら区独自でその事業は進めていけるんじゃないか。そういった全体像を変えていかないと、事業の拡大とか縮減とかという議論にはなっていかないのかなと思うので、これは意見ですけれどもとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"ちょっと話を変えて、ずっと国際友好協会ばかりじゃ悪いから、文化振興事業団を大きくとらえて、ハコモノの話をしていいですか。おれはつくっているんだろうと思っているけどどうなんか尋ねました。","respondent":"日下部企画部長","answer":"ではそれを建て替えましょうという施設が、これから多く出てきますから、それに短期間で対応するというのは非常に厳しいわけです。そういう視点でいろいろ検討はしますけれども、１０年先のスパンで、具体的に何か展望を持っているというわけではございません。","id":"exchange-040"},{"speaker":"石田（秀）副委員長","kind":"質問","question":"だから、６億円なら６億円ずっとかけていくんですかと。それも、１つの行革の財政的な部分も含めれば、そこに目を向けるべきじゃないのかなと私は思っているということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"}]},{"id":"topic-02","title":"の「財政に関すること」","agenda":"の「財政に関すること」","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"伺いたいのは、この旧第一日野小学校の跡地の問題です。何か連絡的なものはなかったのか、そこだけ、ちょっと伺いたいと思います。","respondent":"久保田行財政改革担当課長","answer":"第一日野小学校の貸付に関してですけれども、私どもはＴＯＣと協議、連絡はとって、きちんと話し合いはしています。ただ、今の段階でそういう具体的なものをお示しする時期ではないですので、この場では具体的なお話は控えさせていただきたいと思います。","id":"exchange-042"},{"speaker":"中塚委員","kind":"質問・要望","question":"暫定貸付期間が切れます今年の９月ですか、防災活用も含めた活用を進めるべきだし、１日も早い具体化を求めたいと思います。この大崎や五反田のまちなかは、この地域は認可保育園がとても少ないですから、設置に向けた検討を進めるべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"中塚委員","kind":"提案","question":"今の段階では住民要望や行政需要を踏まえながら、引き続きの活用方法も検討を進めていくべきじゃないかなという程度にとどめたいと思います。こういう機能としての期待もできますし、そうさせなければならないと思いますので、こういう方向で検討することを提案したいと思いますとの意見を述べました。","respondent":"武内委員長","answer":"抽象的なお話ぐらいしかできない状況になっております。そういった面で、今回は今出た２つの跡地と、東品川清掃作業所と、この３つに絞って跡地についてはちょっと議論をしたいと思います。","id":"exchange-044"},{"speaker":"渡辺委員","kind":"提案","question":"やはり金額的なもの、本当にそれが意味をなすかどうかというところで、２つの考え方をあわせ持ったほうがいいと思っています。そんな考え方で、次回ぐらいまでには個別の具体例として何か議会として、個人としてもそうですし、提案ができたらなという思いでおりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"阿久津委員","kind":"質問","question":"それをＣＭ効果換算ですか、１つそういう考え方もあるのかなということで、こういったことはちょっと具体的な案を出せればなと考えています。別にテキスト、文字だけですから、データ量もそんなに多くない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"渡辺委員","kind":"質問","question":"検討会の必要性を説いていらっしゃいましたが、私は真逆で、まず１つ、どうお考えになるのかということ。やはりその意向を聞いて、区民の声を聞く場をなんて言うこと自体がとてもナンセンスではないかと考えていますので、見解をお知らせください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"中塚委員","kind":"質問・要望","question":"近隣の方々の要望と、全体の行政需要と、ここをしっかりとらえて、跡地活用を考えるべきだということはこの間言ってきたつもりなんですね。もう１つ、濱野区長になってからは、タウンミーティングか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"私は、それこそ、そういうつらいことも議員が言っていくべきだろうと。そこら辺のところのお考えがあれば、ぜひお聞かせいただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはりそういう住民要望に沿って検討した結果こういう結果でしたというところまで、まだ詰めていない、議論が始まったばかりだと私は思っています。今の段階でしっかり住民要望を取り上げて、その実現のためにその検討を求めていくというのは、私は正しいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"石田（秀）副委員長","kind":"提案","question":"本当は提案権は行政側にあって、下の土地を買う部分、あれはなかなか手を入れるのは難しいと言っていることをまるっきり信じてない。そこは今、３点言ったのだけれども、そういうふうに思って行政の発言を聞いてらっしゃるかどうかだけ教えてほしいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"中塚委員","kind":"意見","question":"建物の耐震化のときに、この建物は耐震化をするにはちょっとなかなか難しいという話はありまして、既存の建物をそのまま使うのは難しいだろうと。今、暫定活用として若干使っておりますけれども、その時点をとらえただけでありますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"だから、もう１回よく聞いてくださいよ。そんなことは聞く耳持たないのか、それは区民要望を吸収していないから、そこはどうとらえているんですかと聞いているの。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"中塚委員","kind":"質問・要望","question":"あくまで議会ですから、やっぱり、そうは言ってもこの強い住民要望で何とかならないかと。もちろん、今、副委員長が言ったように擁壁の問題で、簡単には何ともならないという説明があるわけだけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"中塚委員","kind":"意見","question":"近くで何とかならないかと、いろいろな議論の広がりもあるとは思うけれども、今の時点では必要かどうかもあまり発言がない。知恵はないのかという意味ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"},{"speaker":"石田（秀）副委員長","kind":"提案","question":"行政側もきちんと調べて提案が出てきたときに、「おまえ、何とかならないのか」ってただ文句を言うだけ。ただ区民要望を聞いたから行政側に「何とかならないか」と、そういう感覚で中塚委員が思っているということがわかっただけでよかったですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"中塚委員","kind":"質問","question":"特に特養ホームについては、これはあくまでも公益的な施設であって、地域ごとに考えるものではないというのが従来の区の考えですから。でも、私は、お年寄りの方々にもお話を伺ったり、家族の方からもお話を伺ったり、いわゆる生活圏というものがあるだろうと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"中塚委員","kind":"質問・要望","question":"必要性についても、必要性はあると。では、どうしようかという話に次は臨むわけで、ぜひそこはわかっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"区民要望がここにあるから、この場所につくれ、それは何とかならないのかと。本末転倒だよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"西本委員","kind":"質問","question":"個人のために品川区の財産をどうのこうのと言ってくる方がたくさんいらっしゃると思うので、売却処分という形も１つの方法ではないかと思っています。助け合うというような、そういう啓発は、していくことが必要だなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"ある、ないは別としても、まずはやっぱりその意識をしっかりと持っていただきたいなと思います。品川区で同じことをやって、しかし、品川区においてもそういった部分に関してトライをしてみるといった姿勢も必要なのかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"沢田委員","kind":"意見","question":"どうにかして利用してということはなかなか難しいのかなとも思っていて、それで、そうやって売却していくという方向がいいのかなと思いました。そういう使い勝手が悪い部分に関しては、別に、民間の方に有効に使ってもらえばいいのではないかなと思いましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"石田（秀）副委員長","kind":"意見","question":"だけれども、それも１つの区民サービスだというのは大きな勘違いだと私は思います。そこは行政目的があったとしても、その跡地を活用して、そこの選択肢を選んでくるということだけは考えてほしいなというのはお願いだけしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"渡辺委員","kind":"質問","question":"３団体、１つの絞った形で伺っていたんですが、やはり同じ流れだと思うんですね。可能かどうか、正副委員長で検討いただければと考えています。","respondent":"武内委員長","answer":"では、正副でちょっと検討します。その辺もわかればお願いしておきたいと思います。","id":"exchange-064"},{"speaker":"西本委員","kind":"質問","question":"区民の方々が、駐車場を利用したときに、何か意見がきているのであれば、それもあわせて出していただけないですか。お願いします。","respondent":"武内委員長","answer":"では、また、次回以降そういうのを含めて、ちょっと税外収入等も、検討していきたいと思います。これで「特定事件調査」を終了いたします。","id":"exchange-065"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/931720?Template=document&Id=5916#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":54428,"voices":142}},{"id":"h24-20120125-17","meetingId":"h24-cm01","date":"2012年1月25日","dateIso":"2012-01-25","committee":"震災対策特別委員会","time":"午後１時０１分～午後３時４２分","status":"正式会議録","sourceType":"formal","overview":"震災対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を58件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"要援護者の命を守るために行政がどう役割を果たしていくのかということについて、どう考えられるのか、お聞かせほしいと求めました。品川区の要援護者に対しての全体計画というのは、どういうものを指すのかということについても、お聞かせほしいと求めました。","respondent":"高山防災計画担当課長","answer":"安否確認や救出など、警察、消防と一体となって進めていくといった役割はあります。２点目の総務省の調査、先ほど、ご紹介いたしました要綱の制定をもちまして全体計画としたというような考えでおります。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"地域の実情に応じた対策マニュアル等を整備して、適切な対策をとられるよう努めていただきたい、ということで求めているわけです。市町村がこういうことを責任を持って進めてほしいということが書かれていると思うんですが、その点に関しては、いかがか尋ねました。","respondent":"高山防災計画担当課長","answer":"全体計画と合わせまして、個別支援ということで、現在、プランの策定を、町会・自治会と進めているところです。取り組みで、災害時要援護者の問題につきましては、対処してまいりたいと考えております。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"こういう活動をしてほしいということを求めているんですけれども、その災害時要援護者支援班というのは、平常時は活動すると。品川区の災害時要援護者支援班というのは、現状ではどうなっているのかについて、ちょっとお聞かせほしいと求めました。","respondent":"高山防災計画担当課長","answer":"こういった対象者の範疇でありますとか、また、情報の提供のあり方なども含めまして、福祉部門と、障害部門等との会議につきましては、この間、繰り返してまいったところですので、そうした意味での連携というのは、庁内においてとっているという認識でおります。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"安否確認、区としても、とられているということでいいんでしょうか。そしてもし、こういう体制がとられているんであれば、そういうことはどこに書かれているのかについても、お聞かせほしいと求めました。","respondent":"高山防災計画担当課長","answer":"そういった形で、要援護者にも、平時からかかわっていただくような仕組みがあります。「障害のしおり」などに載せたりといった形で、情報の共有と、情報の発信に努めているところです。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"東京都のほうでも示されているわけですから、こういうふうな形で支援していきますというものをつくっていただきたいと思うんですけれども、いかがか尋ねました。","respondent":"高山防災計画担当課長","answer":"震災を受けまして、先ほど、答弁申し上げたとおり、福祉部門と防災部門の定期的な打ち合わせなども、この間、進めてきておりますので、こういったものを明文化できるものについては、方針なり、マニュアルなりの中にうたっていきたいと、そういった考えはあります。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"具体的なところでお聞きしたいんですけれども、３,１００人ということで、教えていただきたいのが１点です。区が考える対象者というのは、現在は何人ぐらいを想定しているのかということについても、説明を求めました。","respondent":"高山防災計画担当課長","answer":"こちらにつきましては、数にしまして３００名弱ということで、おおむね９％制度といった構成となっております。正確な数字ではございませんが、その中から応答していただいた３割程度の方が登録した結果、この３,１００人といった数字になってあります。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それからもう一つは、これも一般質問でお願いしたのですけれども、私は、対象の拡大が必要なのではないかと思います。どういう状況になっているのか、ぜひ拡大していただきたいと思うんですけれども、いかがか尋ねました。","respondent":"中山防災課長、高山防災計画担当課長","answer":"対象の拡大につきましては、福祉部門とも、今、十分に協議を詰めているところです。慎重に検討を進めて、どの部分だというようなことで、慎重に協議を進めてまいりたいと考えています。行政からの登録に関する意向調査に関して、登録しないというものも含めて何かしらの反応を受けた結果が、この３,１００名という数字です。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"これはぜひもと入れていただかないと困るということもお聞きしていますので、ぜひ、拡大という方向でご検討をよろしくお願いしたいと思います。要援護者の支援計画の具体化をどう進めていくのかというところでは、どのような考え方をされているかということについて、説明を求めました。","respondent":"原高齢者福祉課長","answer":"あるいは翌日の対応のみならず、どういう対応をすればいいか、検討中でもある状況ではありますけれども。そういう経験と、その後の検証を十分に踏まえた形で、今後の対応についても生かしていきたいと考えているところです。","id":"exchange-008"},{"speaker":"伊藤委員","kind":"質問","question":"私は端的にお伺いするんですが、要援護者の現状把握について、東京都が平成１８年に推定した区の避難者は１５万７,０００人となっているわけですよ。実際にこの名簿登録対象者の想定数は１万人とおっしゃいましたけれども、認識としてはこの１万人でよろしいのか尋ねました。","respondent":"原高齢者福祉課長、永尾障害者福祉課長","answer":"３年に１回、またそういう中で、こういった名簿の登録等についてもご案内をするというような形です。１万人を超えていらっしゃいますし、どういった形での対応がいいかということを、対応していくということが大変重要だと認識していま… は情報取得が、ほかの方に比べて非常に困難性のある方ということで、最低限に絞った形での対象者になっております。１級から３級までを、全部合わせますと、大体６,５００人ぐらいにはなるのではないかと考えています。","id":"exchange-009"},{"speaker":"伊藤委員","kind":"確認","question":"確認したいのが、１万６,５００名の対象ということも踏まえたうえで、おそらく品川区が期待する力は発揮できにくくなってくると思う。でもそれが現実なわけですから、品川区の考え方はどうでしょうかということをお聞かせください、お願いいたします。","respondent":"高山防災計画担当課長","answer":"防災課の考える以上の地域の見守りということで、自主的に取り組まれている事例もありますので、大変あると考えております。防災を一つの切り口としまして、防災区民組織の活性化などが図られればと、そのような思いで計画の改定などを進めてまいりたいと考えております。","id":"exchange-010"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ここを避難所として指定していいんですか、これから国や東京都が、その考え方を変更していく可能性はあるわけでしょ。そのことを含めての見直しは、どう考えていますかということの確認を、お願いいたします。","respondent":"高山防災計画担当課長","answer":"津波の想定につきましては、現在、東京都のほうが鋭意進めているところで、順調にいけば、年度内ではないかというような話も聞いております。区の取り組みとして進めてまいりました区内の標高といったもので、今後、引き続き検討してまいりたいと考えております。","id":"exchange-011"},{"speaker":"伊藤委員","kind":"質問・要望","question":"まとめますけれども、ずっと私たちが言ってきました自助・共助・公助、これはぜひ、円滑に進めていっていただきたいんですよ。ぜひ、そのことはしっかり対処していただきますことをお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"本多委員","kind":"確認","question":"３月１１日に、自覚があればいいんですが、漏れてしまうようなことがないようにお願いいたします。その辺の確認とか、そういったものの確認について、説明を求めました。","respondent":"原高齢者福祉課長","answer":"それから発災時にどういう動きをすればいいか、これは日常の訓練を生かした形で対応をとっていくです。いざ今回の３.１１を受けて、今回、すぐにそういう対応をとったです。","id":"exchange-013"},{"speaker":"本多委員","kind":"質問","question":"シルバーセンターにいたときにどうするかというのは、２０秒後に地震が来ますと鳴るではないですか、伺いました。今回、高齢者ということで、その辺を簡潔にお聞かせほしいと求めました。","respondent":"原高齢者福祉課長、高山防災計画担当課長","answer":"シルバーセンターの関係ですけれども、こちらのほうは、先ほどの施設と同様に、何かあった場合ということで、訓練をしているです。現在の２０秒後に地震が来るといったところについても、もう１回徹底をする形で… 緊急地震速報の関係につきましては、防災課のほうで予算化しておりまして、そういった意味で、もしも、委員ご指摘のような、案内として不十分な点がありましたら、確認をして対処したいと考えております。","id":"exchange-014"},{"speaker":"塚本委員","kind":"確認","question":"ちょっと念のために確認しますが、最初に、それをまず確認させてください。","respondent":"高山防災計画担当課長","answer":"本日の資料にはございませんが、要援護者向けの通知につきましては、平仮名表記でありますとか、それぞれの障害の方に判読できるような工夫をしていますので、そういった部分の対応はとれております。","id":"exchange-015"},{"speaker":"塚本委員","kind":"質問・要望","question":"今の答弁を信じてというか、そのようにしていただいて、登録の漏れがないように働きかけてほしいと求めました。１点確認をいたしたいのは、こういったものはどのように定められているのか、説明を求めました。","respondent":"高山防災計画担当課長","answer":"それぞれの災害時の医療につきましては、医療救護班を統括する部分として、保健救護部という部を災害対策本部内に設置いたします。そういったものと連携をとりながら、病院等への搬送について、計画を進めるといった対応をとる予定でおります。","id":"exchange-016"},{"speaker":"塚本委員","kind":"質問・要望","question":"そこにどういう医療機関の方が来るということで、準備というか、そういったことは非常に大事になってくるかと思います。そういった点も、しっかりとしてほしいと求めましたので、この点を要望させていただいて、終わりにしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"山内委員","kind":"質問","question":"医療のところについて、伺いたいと思います。この４師会の先生方と、その組織といったものを整備をしているのかといったところを、説明を求めました。","respondent":"中山防災課長","answer":"もうこれは決まっているんですけれども、今後、医師会との話し合いを進めようということで予定をしています。そういったときには、どなたにきていただくかとか、そういった問題をきちっと協議しようという話になってあります。","id":"exchange-018"},{"speaker":"山内委員","kind":"意見","question":"なぜ医師会だけなのか。その辺は、これから懇談を持とうという中で、なぜその４師会と話し合いができないのかとの意見を述べました。","respondent":"中山防災課長","answer":"４師会と会合を持ちたいと考えています。当然のことながら、４師会と調整を図ってまいりたいと考えています。","id":"exchange-019"},{"speaker":"山内委員","kind":"質問・要望","question":"４師会と、それはちゃんと、そういった懇談がされたというときには報告をいただきたいと考えています。この二つの事業部をまたいで、どういった話をされてきたのかということを、もう１回、説明ほしいと求めました。","respondent":"高山防災計画担当課長","answer":"現段階でお示しできませんというところで、そういった意味で、継続的な打ち合わせというものを持っていきたいと考えております。やはりそれぞれ慎重にお話を進めていく中で、そういったものを一つ一つ解決しながら、実効性ある計画にしていきたいと考えております。","id":"exchange-020"},{"speaker":"山内委員","kind":"質問・要望","question":"そういったところもありますので、その辺はほんとうに早急にやってほしいと求めましたので、これは要望いたします。そういったことがあるのであれば、こういった記載をされたのは納得できるんですけれども、そういったことができるのかということを伺いたい。","respondent":"中山防災課長","answer":"これは、毎年、２５万円ずつ払って入れかえを行っております。今、何日間かは、私どもが十分にストックしている医薬品で事足りるのではないかと考えています。","id":"exchange-021"},{"speaker":"山内委員","kind":"質問・要望","question":"今回は医療系と行政との連携といったものを、そこでしっかりと構築してもらいたいということを、最後にそれを申し上げたいと考えています。そのあたりはしっかりと、品川区のほうで把握をし、そしてしっかりと提供できるような基盤整備といったものを整えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"渡部委員","kind":"質問・要望","question":"今日、こういう議論ができる場でしたので、一番最初の取っかかりのときの内容を教えてほしいです。それから、町会に対しても、どのような形でお願いをしているのか、説明を求めました。","respondent":"高山防災計画担当課長","answer":"３点目のお尋ねですが、どのような形で説明をしているのかといった点ですが、丁寧にお伝えしてきているところです。そういったことではないといった旨のご説明と、そういった旨の丁寧な周知文を添えてお送りするように、そんなような形で事務を進めております。","id":"exchange-023"},{"speaker":"渡部委員","kind":"意見","question":"そうしましたら、一番気にしているところなんですけれども、名簿に載せますか、載せませんかというときに、必ずしも、命の安全、だれかが助けてくれることを保障されているものではないということが明記されているか、されていないかだけ、もう１回、お願いしますとの意見を述べました。","respondent":"高山防災計画担当課長","answer":"非常に直接的な表現にはなるかと思うんですが、趣旨としましては、命の保障をするものではないというような趣旨の文言が添えてあります。","id":"exchange-024"},{"speaker":"渡部委員","kind":"質問・要望","question":"町会どうですかということまでも戻していただいて、２０５町会ある中で、またいろいろな町会に逆に発信をしていっていただきたい。どうやって使っていいかもわかりませんという部分も多いですので、それは要望としてお願いをいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"向委員","kind":"質問・要望","question":"教えていただきたいんですけれども、これは１回研修を２日間受けて、定期的な再研修があるのかどうか。荏原地区で、それぞれ延べ人数が出ていると思うんですが、これは大体町会に１人ぐらいはいてほしいというお考えで実施されているのかということ。","respondent":"中山防災課長","answer":"今後は、毎年、防災アドバイザー研修を受けた方が５００人以上いらっしゃいますので、何年間か続けてやってまいりたいと考えています。それから年齢と男女比ですけれども、ちょっと今、恐縮ですが、データがございません。","id":"exchange-026"},{"speaker":"向委員","kind":"質問","question":"若い方もいたらいいなと、ちょっと思ったので、お尋ねしました。わかれば教えてください、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"吉田委員","kind":"質問","question":"先ほど、総合防災訓練のほうにも導入の話もあるということでしたが、それをいつごろやるのか。まず３,１００人ということですが、その辺をちょっとお聞きしたいんですが、お願いします。","respondent":"高山防災計画担当課長","answer":"個別支援プラン、区がどのような支援ができるかといったものを整理いたしまして、全域に広げていきたいといった考えです。なかなか個別支援プランが進まないところもある一方で、支援者探しをしたりとかいった、拡大に努めたいと考えております。","id":"exchange-028"},{"speaker":"吉田委員","kind":"質問・要望","question":"できれば、そういう内容等も、我々は知りたいと思うんですよ。経過報告等もしていただきたい、そういう要望です、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"吉田委員","kind":"質問","question":"ごめんなさい、それはやっぱり質問にさせていただいて、できれば、それをしていただけるのかどうかということをお聞きしたいと思います。","respondent":"中山防災課長","answer":"災害時要援護者につきましては、今度の２月の町会長会議、全地区を回りまして、再度、説明をすることになりました。３月には固まると思います。","id":"exchange-030"},{"speaker":"金野委員","kind":"確認","question":"歯科医師が２名とか態勢がありますけれども、１３地区それぞれで救護班があって、まず確認をさせてください。どういうふうに考えていらっしゃるのか、まず２点、お願いします。","respondent":"高山防災計画担当課長","answer":"今後の話し合いの中で、１３地区の班編成でありますとか、交代要員も含めた医療の体制につきましては、順次、詰めてまいりたいと考えております。２点目の助産師のお話につきましては、現在のところは、まだ検討の項目には挙がってございません。","id":"exchange-031"},{"speaker":"金野委員","kind":"質問","question":"それが１点。災害時には、こういった方々への支援の手も必要かなと考えますけれども、いかがか尋ねました。","respondent":"高山防災計画担当課長","answer":"１点目の、働きかけがどのような方法が考えられるかということについては、研究してまいりたいと思います。２点目の助産師の協力体制につきましては、こういった計画の中では考えられておりますが、これも一つ研究の課題の一つとして取り上げします。","id":"exchange-032"},{"speaker":"金野委員","kind":"質問","question":"次が、難病の患者への支援体制は、どうなっていますでしょうか。たしかなかったと思うんですが、そこら辺の体制は、どのように考えられていらっしゃいますか尋ねました。","respondent":"福島荏原保健センター所長","answer":"現に３月１１日には、呼吸器のついている患者が、現在６名いると、それは東京都と東京電力との連携体制ができているということです。個々にその地区に応じた支援体制を、今、チームをつくってやっているというところです。","id":"exchange-033"},{"speaker":"金野委員","kind":"質問","question":"お考えになっていらっしゃるかと思いますが、もっと強固にされることをお願いしたいと思いますが、いかがか尋ねました。","respondent":"片田防災まちづくり事業部長","answer":"事業継続計画の状況も、今、整備分析しているような状況もあります。具体的にどのような支援ができるのかといったところも、きちっと対応できるような体制を、検討して。","id":"exchange-034"},{"speaker":"高橋委員","kind":"意見","question":"町会などに入っていないマンションに住まれている方の中に、３,０００人の中のどなたかがいらっしゃると、しかし、町会長とは日ごろかかわりがない。この辺の名簿の扱いというのは、どうすればいいかわからないので、お尋ねしたいんですとの意見を述べました。","respondent":"高山防災計画担当課長、片田防災まちづくり事業部長","answer":"名簿の登録にあたりましては、特に町会加入の有無というところで何か隔たりがある、差があるわけではございません。防災のもう一つの切り口として、地域の活動に興味、関心を持っていただければとは考えております。 自治会がまだできていないところが課題だと考えていますので、私どものほうも、そのような対応が共有できるような情報ができればと考えています。ちょっと研究をさせていただければと考えています。","id":"exchange-035","title":"町会・自治会支援"},{"speaker":"高橋委員","kind":"質問","question":"ということは、管理組合があって、理事長とかがいらっしゃって、今、修繕計画等をやっているところには伝えられるということですか。お尋ねすれば、という話か尋ねました。","respondent":"片田防災まちづくり事業部長","answer":"ご本人のご了解が得られるのであれば、そういうことはできると考えています。","id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"５,０００人もいるわけですから、どうかということで、そのことを一つお聞かせいただきたい。そのつくられ方というのは、どういう形でつくられているのかについても、説明を求めました。","respondent":"高山防災計画担当課長","answer":"どこまでできるかというところもありますので、その点については、できる得る限りの範囲内で対応していただくということが重要かと考えております。","id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"具体的にはなかなか、個別の支援プランは実際につくられていないという状況だということでしょうか。その方をどう支援していくかというところでは、一人ひとりに対してどうかかわっていくのかというあたりを検討して、いかがか尋ねました。","respondent":"中山防災課長","answer":"支援プランの関係について、一応、名前を書いていただきたいというようなことで。ただ、その名前を書くことが、果たして、自分は行けないかもしれないけれども大変だというようなことになろうかと思います。","id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうではないですか。そこら辺のところを、ちょっともう１回、説明を求めました。","respondent":"中山防災課長","answer":"そういう意味で、私は申し上げたのではございません。福祉部局で見守る人間以外の方々を対象にした、私たちの名簿ですので、その方を対象にして個別支援プランを作成するところまで実施していこうです。","id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"福祉分野で見守る方以外のところが、防災課でやるということなんですか。防災のほうで名簿をつくっていくというのは、それ以外のところというのはどうことなんだか、ちょっとよくわからないんですけれども。","respondent":"高山防災計画担当課長","answer":"ご説明申し上げております防災区民組織、町会・自治会を中心とした個別支援プランの作成といった部分については、そういったものを基本とする支援の仕組みです。","id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それからもう一つお聞かせいただきたいのが、避難所の中で、壊れかかった自宅に戻るということもたくさんあったということです。品川区としては、どういう方向になっているのかを、ちょっと説明を求めました。","respondent":"高山防災計画担当課長","answer":"同じようなことを、品川区を含めて、２３区で実施しようとすると、これはなかなか難しいというところがあります。全部の避難所でそういった支援班をつくれるかということにつきましては、マンパワーの関係もございまして、なかなか難しい問題だとは考えております。","id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ほとんど把握されなかったというところが、今回、問題だということで出されているわけですよね。安心して居場所をつくれるというところでの相談窓口をつくって対応をとるべきなのではないかと思うですけれども、いかがか尋ねました。","respondent":"中山防災課長","answer":"さくら会、春光福祉会という区内の５法人を福祉避難所と呼んでいますけれども、そこへ迎え入れるという形になっております。それで、福祉避難所のほうも、簡易ベッド等を用意しています。","id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それからもう一つは、障害者の団体の方々からも、はじめから福祉避難所に避難できるようにしてほしいという要望をお聞きしているんです。はじめからそこの福祉避難所に避難できるという体制をとっていただきたいと思うんですが、そのことについては、いかがか尋ねました。","respondent":"中山防災課長","answer":"相談窓口で福祉避難所へ入りたい、移動したいというようなことを……そうではないんですか。そうでないとすれば、相談窓口は相談窓口としてつくって、福祉避難所は別な話ということでいいわけですね。","id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、一般避難所に行く、または福祉避難所に行くというのを選択できるようにしていただきたいということなんです。だから、そのためにも、相談窓口をつくっていただきたいということで、質問をさせていただきました。","respondent":"原高齢者福祉課長","answer":"この災害初動対応マニュアルの中でも、直ちに避難所の開設班として、私ども動くマニュアルになっております。そういう特性に合わせた形で、状況に合わせた形で相談に応じるということで対応していくことになっておりますし、そういうふうに認識をしています。","id":"exchange-044"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ、よろしくお願いしたいと思います。品川区としては、どういう職員を考えているのか、お聞かせほしいと求めました。","respondent":"原高齢者福祉課長","answer":"今回の３.１１の状況を見ましても、いろいろな機能がその避難所では必要となってきますので、そこに応じたスタッフ体制をとる。なるべく早い段階で体制をつくっていくといったところが、当然必要ということで認識をしています。","id":"exchange-045"},{"speaker":"伊藤委員","kind":"質問・要望","question":"女性の方も受診されるわけですから、それは体制の中で対処できると思いますので、要望しておきます。そんなことは言っていられないということもあるわけですから、やはりその辺は、いかがか尋ねました。","respondent":"片田防災まちづくり事業部長","answer":"やはり人命に係わるですので、名簿等の取り扱いについて配慮しつつも、一定の判断をしなければいけない。あるいは、防災とかそういう関係機関との協力の中で、どのような対応ができるかということを、まず研究させていただければと考えています。","id":"exchange-046"},{"speaker":"伊藤委員","kind":"質問","question":"３月１１日の震災があって、震災対策をやるということになって、この委員会も開かれているわけではないですか。あの３.１１を踏まえたうえでやっていくのであれば、そういうふうな答えはいただけないのでしょうかということで、答弁をお願いいたします。","respondent":"片田防災まちづくり事業部長","answer":"確かに、人の生命とか、身体、あるいは財産の保護のために、必要なことはそういう判断ができると認識していますので、そのような場合については、そのような対応をとらせていただきたいと考えて、整理をしていきたいと考えています。","id":"exchange-047"},{"speaker":"伊藤委員","kind":"質問・要望","question":"もし、そういう位置であるならば、福祉部門だけではなくて、いろいろな部門が関係してくるわけではないですか。そのことについて、品川区の改めての考え方と、方向性を説明を求めました。","respondent":"片田防災まちづくり事業部長","answer":"今、いろいろの角度の中から、課題を含めて、防災計画の見直しを、担当課長が進めているところです。この計画がきちっと連携がとれるように、きちっとしたものを作り上げていきたい、情報の共有化を含めて対応してまいりたいと考えています。","id":"exchange-048"},{"speaker":"伊藤委員","kind":"意見","question":"当然、品川区も、同じようなことにあった場合に、例えばＡさんに聞けば、品川区の防災関係全般については、大概のことはわかる。危機管理課とは言わないけれども、そういう対処をしていく必要があると思うんですが、もう一つ踏み込んでの答弁をお願いいたしますとの意見を述べました。","respondent":"片田防災まちづくり事業部長、岩田都市環境事業部長","answer":"地域防災計画の中でも、本部長として、指令情報部という形で防災まちづくり事業部が速やかに対応していく状況になっております。情報を集約していくといったような体制をとってまいりますので、今後も… ２３区の中でも、区によっては、地震水害すべての災害を危機管理室に集約した体制をとり始めた区もあります。体制が違うということで、これからもこの体制でいきたいというのが、区の考えになります。","id":"exchange-049"},{"speaker":"井上副委員長","kind":"意見","question":"やっぱり所管がすごく無理があるなと、今、感じていました。どういう方たちが要援護者だと、明確な答弁を、どなたかにお願いしたいと思いますとの意見を述べました。","respondent":"岩田都市環境事業部長","answer":"２日という系列になってきますので、学校避難所の一般の人との生活が非常に不自由になってまいりますので、二次避難所のほうに誘導する。要援護者へ、実は区が手を差し伸べられる度合いというのが、当然のことながら変わってまいろうかと考えています。","id":"exchange-050"},{"speaker":"井上副委員長","kind":"質問","question":"何かあったときにしか使ってはいませんよ名簿のようなものではなくて、そういうものを、まずは地域が把握をする仕組みをつくるべきだと思うんです。一段階前につくるべきだと思うんですけれども、その点については、いかがか尋ねました。","respondent":"岩田都市環境事業部長","answer":"どう考えてもできない方、地域の皆さんといろいろ考えながら、こういう仕組みをつくってきたわけです。区も堂々とＰＲをして、町会への加入率を高める努力も、今後もしていきたいと考えています。","id":"exchange-051"},{"speaker":"井上副委員長","kind":"提案","question":"何をニーズとして求めているのかというワークショップにはなっていないので、社会福祉協議会とか、そういう団体ごとでないと難しいと思うんです。具体的に要望があったからしていくのか、２点、伺いますとの意見を述べました。","respondent":"中山防災課長、片田防災まちづくり事業部長","answer":"対象を広げるには、慎重に協議をしていくです。それから、助けてくださいという形ですけれども、こちらがそう申さなくても、町会の方々は、十分にそれを承知されていると思ってあります。ほんとうに震災時に、その場の中で対応をしなきゃいけないという中では、地域の人とのきずなを含めた共助の体制づくりが必要だと考えています。","id":"exchange-052"},{"speaker":"井上副委員長","kind":"提案","question":"３.１１で、安否確認を、その報告というか。その状況をどこかに連絡をしたり、だれかが集約をしてちゃんと把握をしているということが、計画の中にちゃんと反映されているのか尋ねました。","respondent":"高山防災計画担当課長","answer":"要援護者と町会・自治会との間のすき間といいますか、間隔も狭まっていくのではないかと、こんなような形で認識しております。３.１１を経て、こういった災害時要援護者に係わる所管というのが救助２部という位置づけになっておりますので、このように考えております。","id":"exchange-053"},{"speaker":"井上副委員長","kind":"確認","question":"安否確認ができたのかどうかというのが、そこら辺は、どんな感じになっているんですか。一人に３人行くところがあったり、これからどうしようかというその結果と、これからの検討事項はあるのか尋ねました。","respondent":"片田防災まちづくり事業部長","answer":"町会の中で、そういう取り組みをやって大変効果があったと期待していますので、やはりそれを引き続き継続して進めていくことが大事だと考えています。もうちょっと深めた形での対応ができるように、今後、工夫をしてまいりたいと考えております。","id":"exchange-054"},{"speaker":"井上副委員長","kind":"質問・要望","question":"いろいろとお伺いする中で、支援を求めていますとか、それを使うという安心感があるという要望があります。ちょっとどういうふうにすればできるのか、その辺についての考え方は、いかがか尋ねました。","respondent":"永尾障害者福祉課長、高山防災計画担当課長","answer":"現在、手話通訳の登録者数は、品川区内で１４人、要約筆記の登録者が８人ということなんです。この間の６月補正のときに幾つか用意してありますので、そういうものを配付して、まずは筆記で対応していきたいと考えております。腕章につきましては、各避難所に備えてありますので、用途別に色を使い分けるような、そういった形での備蓄ということで考えてあります。","id":"exchange-055"},{"speaker":"井上副委員長","kind":"質問・要望","question":"どういう形がいいのかというのは、当事者の意見を反映して、それぞれ意見があると思いますけれども、その中でお願いしたいということ。５色で各１０枚とか、もう少しわかったほうがいいのではないかというふうに思うけれども、課題はないのか尋ねました。","respondent":"片田防災まちづくり事業部長","answer":"協力していただける方に、その中でいろいろどういう出し方がいいのかというところも含めて、検討させていただければと考えています。","id":"exchange-056"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"１回でどかんと来るのではなくて、その辺の情報収集ができれば、次回以降何か。別に見解というと難しいと思いますので、情報収集だけできないかなと思うんですが、もしできれば、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"伊藤委員","kind":"提案","question":"これは委員長に聞けばいいんでしょうか、防災計画にちゃんと反映されるタイミングが合うかどうか、これは非常に気になります。私どもがただ提案だけして、これは委員長に聞くのが正しいのでしょうか、まずその確認をお願いいたしますとの意見を述べました。","respondent":"飯沼委員長、中山防災課長","answer":"計画とタイアップすると、非常に難しくなると思うので、とにかくこの議論が有効に生かされる方向でまとめていきたいと考えております。計画的な、反映の余地のタイムスケジュール的なところを、ちょっとご答弁いただけますか。 ご提言をいただくために、この委員会をやっているわけですので、当然のことながら、皆様方のご提言を新しい地域防災計画に反映させていくということで、日程的にも、十分に可能です。","id":"exchange-058"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/167861?Template=document&Id=6402#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=17&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":47226,"voices":137}},{"id":"h24-20120224-3","meetingId":"h24-c-budget","date":"2012年2月24日","dateIso":"2012-02-24","committee":"予算特別委員会","time":"午後３時４７分～午後３時５４分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/918450?Template=document&Id=962#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":2000,"voices":17}},{"id":"h24-20120227-6","meetingId":"h24-cm02","date":"2012年2月27日","dateIso":"2012-02-27","committee":"区民委員会","time":"午前１０時００分～午後０時２５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を48件整理しています。","topics":[{"id":"topic-01","title":"第１７号議案、品川区印鑑条例の一部を改正する条例","agenda":"第１７号議案、品川区印鑑条例の一部を改正する条例","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"実態的なことをお伺いしたいんですけれども、具体的にどういうところが利便性ということになるのかということが１点と、こういうふうになった背景というのを教えていただけますか。","respondent":"梶戸籍住民課長","answer":"だれだれと載りますので、１枚の住民票の中でその家族構成がすべてわかるという形が、これが一番の利便性ではないかなと考えています。多言語対応のために、印刷等を行いますので、その関係で私どものほうでは５９０万円ほど予算を立てさせていただいてあります。","id":"exchange-001"},{"speaker":"本多委員","kind":"質問・要望","question":"そういった部分というのは全くないのかということを確認したいのと、２番目の記載事項のところで、これについてもう少し詳細に説明をいただきたいんですけれども。","respondent":"梶戸籍住民課長","answer":"ただいまの質問２点ということでございまして、その目的が今度は住民基本台帳法に移りますのでその必要がなくなったということだと思うんです。そして、もう１つ……。","id":"exchange-002"},{"speaker":"本多委員","kind":"確認","question":"もう１つ聞きたいのは、例えば２３区から転居が何年間のうちにあったりとか、自治体ごとにはっきりデータというのが残るものなのでしょうか。日本人同様で扱いが同じということでいいのかどうか、その確認。","respondent":"梶戸籍住民課長","answer":"住民票の除票という形で日本人の方と同じようになります。それは一緒です。","id":"exchange-003"},{"speaker":"石田（慎）副委員長","kind":"意見","question":"全部整備をされて、そのまま日本人と同様の手続をして住民票を取るのか、対象になる方の何か特別な手続が必要なのかどうかが１点。以上３つ説明を求めました。","respondent":"梶戸籍住民課長","answer":"その予定です。そのために仮住民票の発送から法律改正まで２カ月ほどの期間を設けてありますので、できるだけのことはやっていきたいと思っているところです。","id":"exchange-004"},{"speaker":"石田（慎）副委員長","kind":"意見","question":"これを逆に悪用されないように、しっかりと把握をしていただければなと思います。これからそういったケースが出てくるのかなと、そういうときの人員配置の部分で窓口対応がどのようになるのかをお知らせくださいとの意見を述べました。","respondent":"梶戸籍住民課長","answer":"８の地域センターも行ってまいりますので、電話で対応できるようなところ、こちらのコールセンターの先に通訳の方がいらっしゃる。そういった実用的なものの研修を組んでいるところでございまして、今後も随時やるということですので、それで対応してまいりたいと思ってあります。","id":"exchange-005"},{"speaker":"石田（慎）副委員長","kind":"質問","question":"仮住民票を郵送する際というのは、それはその対象の方の対象の言語で手紙を送るんですか。それとも英語のみとか、言語のあれはどのような形で郵送されるのか、そこだけちょっと説明を求めました。","respondent":"梶戸籍住民課長","answer":"ただいま考えておりましたものは、原則日本語を書いてございまして、そのほかに英語あるいは韓国語、中国語等のつけたものを送る予定です。英語、あるいはタガログ語等のリーフレットもありますので、そちらもあわせてご覧いただければという形で対応してまいります。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"ちょっと初歩的なことかもしれないんですけれども、特別永住者というのはどういう方がなられるのかということと、あと、ちゃんとした手続をせずに不法に滞在されてくる方もいると思うんですけれども、今までそういう方も登録はできていたんでしょうかということをお聞きします。","respondent":"梶戸籍住民課長","answer":"もう１点、在留資格のない不法な方ということなんですが、そういった方は、やはり外国人登録制度の中でも登録にはなってございません。そういうこともありますので、そういったご相談が来ましたら、私どもは入国管理局のほうにご相談をつなげるというような状況になってあります。","id":"exchange-007"},{"speaker":"山元委員","kind":"意見","question":"すみません、本当に私も初歩的で。何か自分たちの印鑑登録のイメージと外国の方の印鑑登録はどういうことなのかということと、具体的にお話ししていただくといいんですけれどもとの意見を述べました。","respondent":"梶戸籍住民課長","answer":"もちろんお一人１つだけなんですけれども、例えばビジネス等で会社を立ち上げるとかいろいろなときに印鑑を登録しないといけない。","id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"意見","question":"あまり人権とかプライバシーの侵害という声も今のうちからちょっと出始めているのかなと思うので、でも、この印鑑登録については賛成です。大もとのところがちょっと気になりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"}]},{"id":"topic-02","title":"第１１号議案、品川区地域センターの設置に関する条例の一部を改正する条例および(2)第１２号議案、品川区立区民集会所条例の一部を改正する条例の２議案","agenda":"第１１号議案、品川区地域センターの設置に関する条例の一部を改正する条例および(2)第１２号議案、品川区立区民集会所条例の一部を改正する条例の２議案","exchanges":[{"speaker":"沢田委員","kind":"意見","question":"荏原第三地域センターと荏原第五地域センター、それぞれ、先ほどは倉庫を地域のものを置くのに使うというお話だったんですけれども、防災用の物資とかというのは、この中だったらどこに置かれているのかとの意見を述べました。","respondent":"武内地域活動課長","answer":"地域住民の方と相談しながら、建物の空きスペース等に倉庫等ができればというふうに考えておりますけれども、現在の予定では防災の倉庫はありません。","id":"exchange-010"},{"speaker":"沢田委員","kind":"意見","question":"これから相談して決められるということですけれども、ぜひやっぱり各地域センターには防災用の備蓄物資というのは必ず置くべきだと思うんですけれども、その辺はとの意見を述べました。","respondent":"武内地域活動課長","answer":"必要に応じて、それは臨機応変に必要なものは配置していくということでやっていきたいと思いますので、よろしくお願いします。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問","question":"数字的にどういう、どのぐらいのマグニチュードとか、そういうのが来ても耐えられますという構造になっているか教えていただけますか。","respondent":"武内地域活動課長","answer":"特別工業地区ということになっておりますので、私のほうで具体的にどこをどういうふうにしたのかという説明はできませんけれども、特別的なさらに地震に耐えられるような施設建設をしていくというふうに認識しているところです。","id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"昔、私が議員になったころは、地域センターという呼び名ではなくて、出張所と呼んでいたじゃないですか。今回出てきた２つはとったわけですし、緊急課題で考えておいたほうがいいと思うんですけれども、その辺についてはいかがか尋ねました。","respondent":"武内地域活動課長、中川原地域振興事業部長","answer":"それにつきましては、建築基準法という法律の中できちっと決められた中でやっていただいているです。今後、計画段階から３月１１日以降… ただ、すごくいろいろなことが３・１１で明らかになりましたので、どう生かしていくかは今後検討していきたいというふうに今思っているところです。","id":"exchange-013"},{"speaker":"藤原委員","kind":"意見","question":"備蓄は各お宅でというご発言があったんですけれども、私もそう思っています。基本的な備蓄は各家庭でやるべきだと思っているんですけれども、その辺の３月にというところにおいては、心の中に入れておいていただければ幸いですとの意見を述べました。","respondent":"中川原地域振興事業部長","answer":"３月にまとまるということではなくて、今、区役所としても大車輪で改定の作業を進めているということです。ご意見出ましたとおり、とにかく３日間は耐えられるような体制をつくってもらうとか、そういった宮古に学ぶことはたくさんありました。","id":"exchange-014"},{"speaker":"山元委員","kind":"質問・要望","question":"その辺、子どもの出入りをするにあたって、この駐車場がそばにあるというのはどうなのかなというのが１つ心配です。それからもう１つは、それはいろいろな事情があって移るのでそれなりに理由はあると思いますが、意見が出ていれば教えてほしいと求めました。","respondent":"武内地域活動課長","answer":"駅前ですし、その辺はちょっとハード面的にここの場所に車を置くスペースがないとということでご理解いただきたいなというふうに考えております。ここの場所は従来からある施設ですので、地域の方がこの場所にするということについては何ら問題ないというふうに認識しております。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問","question":"今、駐輪場の質問がありましたけれども、それぞれ何台ぐらい置けるようになっているのかというのと、あと、荏原第五地域センターのこっちに移る前は、新耐震基準だったのか、ちょっとそこをお聞きしたいです。","respondent":"武内地域活動課長","answer":"従来は、あそこも駐輪場としては１０台ぐらいなんですけれども、今の建物につきましては、臨機応変に自転車が置かれているというようなことだと。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"意見","question":"荏原第五地域センターは、豊葉の杜との合築ということで、私たちはそもそも合築、共同施設というところに今までも反対をしてまいりました。やっぱり合築、複合施設にするからだということですので、荏原第五地域センターのところについては共産党は反対ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"}]},{"id":"topic-03","title":"第１５号議案、品川区中小企業事業資金融資あっ旋条例の一部を改正する条例","agenda":"第１５号議案、品川区中小企業事業資金融資あっ旋条例の一部を改正する条例","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"融資は一般質問でもさせていただきましたのでもう１回しますが、改めて予算特別委員会でもみっちり伺います。１０年以内という形でやった背景を教えていただきたいのと、どういうところから来たのか、この数値を教えてほしいと求めました。","respondent":"福島ものづくり・経営支援課長","answer":"品川区では５年しかないので、それを借りるという声がありましたので、それでは区でもということでつくったものです。１.２％をどういう負担割合にするかですけれども、３年間０％の緊急融資あっ旋、一番いい割合にしたです。","id":"exchange-018"},{"speaker":"藤原委員","kind":"確認","question":"予算はどのぐらいを考えているのかということをお伺いしたいのと、この融資も１０年であるというロングというか、そこの確認をしたいと思います。","respondent":"福島ものづくり・経営支援課長","answer":"予算ですけれども、一応、予算上で想定いたしましたのは、平均２,５００万円の融資あっ旋で８８０件ということで予算措置をしているものです。委員がおっしゃいましたとおり、保証協会に行って保証認定を受けていく、流れとしては同じものです。","id":"exchange-019"},{"speaker":"藤原委員","kind":"質問・要望","question":"１０年という形にしても、改めてお伺いしたいんですけれども、区としては立てるのでしょうか。この１０年ぐらいで、どのぐらいの金額のこげつきが、ずっとたまりにたまってどのぐらいあるのかというのがわかれば教えてほしいと求めました。","respondent":"福島ものづくり・経営支援課長","answer":"といいますのは、区としてもそれはまず立てることは難しいだろうというふうに思ってあります。代位弁済をして信用保証協会が回収を新たにやって、実際にこげついたのは幾らなんだ、そこまでは数値は把握してございません。","id":"exchange-020"},{"speaker":"藤原委員","kind":"質問","question":"よくわかりましたけれども、信用保証協会が代位弁済しているお金も、いわゆる個々ではないけれども、区民であり、都民であり、国民のお金ですよね。ちょっと複雑じゃないですか、そこを徹底的に勉強してまた質問します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"本多委員","kind":"質問・要望","question":"８８０件を事業を執行した後に、何かその辺のさらに目標みたいなものとか、もしあれば教えていただきたい。もし効果とか、経済に刺激を与えるとか、その辺のねらいがもしあれば教えていただけますか。","respondent":"福島ものづくり・経営支援課長","answer":"目標と効果ですけれども、従来の融資あっ旋の限度額が、運転資金で１,５００万円限度でございました。実はこの３,０００万円まで限度額を引き上げたということで、あるいは新たな展開、そういうものができればいいかというふうには思ってあります。","id":"exchange-022"},{"speaker":"石田（慎）副委員長","kind":"確認","question":"借り換えというか、５年物を今回のこれに切り替えるというのは、できるということでよろしいんですか。そこだけちょっと再確認。","respondent":"福島ものづくり・経営支援課長","answer":"それをねらっております。しばらく続くかもしれないこの不況を乗り切っていただきたいというふうに願ってあります。","id":"exchange-023"}]},{"id":"topic-04","title":"第１６号議案、品川区立工場アパート条例の一部を改正する条例","agenda":"第１６号議案、品川区立工場アパート条例の一部を改正する条例","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"区民の税金が入っているわけですから、２０年、すごく長いですよね。やっぱり私は、やっぱり２０年の区切りは２０年の区切りなんじゃないかなという思いがあるもので、その辺の説明をしていただけますか。","respondent":"福島ものづくり・経営支援課長","answer":"平成４年につくられたときですけれども、当初は上を住居にしましたので、そういう形でやりました。震災につきましては１,０００年に一度とも言われている、今回このような提案をさせていただいたものです。","id":"exchange-024"},{"speaker":"藤原委員","kind":"質問","question":"そしてもう１つなんですけれども、２０年で終わりますよというお話をしたときに、ほかの新規での募集というのは、ちゃんとかけたんでしょうか。ちょっとどうかな、この２社のためだけにちょっとという思いがどうしてもぬぐえないので、その辺について。","respondent":"福島ものづくり・経営支援課長","answer":"この経済状況を考えて、この５年間もさらに公募を１回かけて、今回こういう提案をさせていただいているものです。ですからこそ、今の経済状況を考えて最適化すると、平等性とほかの人たちとの妥協性と見ると最適化ではないかということで提案したものです。","id":"exchange-025"},{"speaker":"藤原委員","kind":"質問","question":"２つに分かれて商業、このままこの期間を延ばすことが、いわゆる品川の産業発展のためにもつながるという強い思いがあってこういうふうに出してきたと理解してよろしいのか尋ねました。","respondent":"福島ものづくり・経営支援課長","answer":"このまま何もしないで２０年を迎えて出ていってくださいというのは、やはり当初の目的であります工業振興には逆にならないのではないかというふうに判断いたしましたので、今回このようなご提案をさせていただいている次第です。","id":"exchange-026"},{"speaker":"沢田委員","kind":"質問","question":"１個しかない話ですから、今後どうなっていくのかなというのと、その辺のことをお願いします。","respondent":"福島ものづくり・経営支援課長","answer":"２０年前ですと、地方にどんどん移転しているというところで、それも止めなければならない。なかなか正確に工場の金額は相対化することはできませんで、ほかに借りてやると厳しくなるので、今のところにいさせてほしい。","id":"exchange-027"},{"speaker":"沢田委員","kind":"質問","question":"工場等が厳しいわけですから、その２社だけではなくては、入れる環境をそこにあわせて改善していくほうがいいのではないかなと思います。","respondent":"福島ものづくり・経営支援課長","answer":"この２社だけではなくて、ここに入居している８社、やはり慎重に考えなければいけないと思います。今後、物価がもっともっと下がっていくのか、そうなったときにはそうしたことも検討しなければならないのではないかというふうには思ってあります。","id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問","question":"は３年間延ばすということなんですけれども、いろいろ現状を見たり、声を聞いたりした中でということなんですが、なんで３年なのかというのを説明を求めました。","respondent":"福島ものづくり・経営支援課長","answer":"１年とか２年ということも想定したんですけれども、３年あれば、それまでに退去の方策をとってくれということでやりました。１０年、１０年来て、３年です。","id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問","question":"私もこの工場アパートへ行ってお話を伺ってきたんですけれども、作業環境、それはなかなかないんじゃないかということでした。やはりものづくりの町ということでうたっているわけですから、計５年たちました、私はすごく苦悩するんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"石田（慎）副委員長","kind":"質問・要望","question":"いろいろ課長の答弁の中で出てきたんですけれども、改めて現状が実際今どうなっているのかというのを改めて教えていただきたいなと思います。今、入っている業者の方たちだったり、あと、実予算はどのくらいでやっているのかを含めて、改めて現状をお知らせください。","respondent":"福島ものづくり・経営支援課長","answer":"２,５００万円ほどとっていますけれども、それが２,０００万円ほどのあれですから、５００万円弱ぐらいが毎年使っているというものです。逆に、歳入につきましても、大体両方合わせまして２,３００万円ほど入ってくるというような仕組みです。","id":"exchange-031"}]},{"id":"topic-05","title":"第１３号議案、財団法人品川文化振興事業団に対する助成に関する条例の一部を改正する条例および(4)第１４号議案…","agenda":"第１３号議案、財団法人品川文化振興事業団に対する助成に関する条例の一部を改正する条例および(4)第１４号議案…","exchanges":[{"speaker":"石田（ち）委員","kind":"意見","question":"財団法人、公益法人になるところで、今までがどうで、どこがどう変わるのかとの意見を述べました。","respondent":"安藤文化スポーツ振興課長","answer":"そして、どう変わったということなんですけれども、従来より、今ご説明したとおり、両財団とも公益の一助を展開してまいりました。文化振興事業団については７９.１％が公益にもう既になっているということで、区民スポーツの振興に寄与することを目的とするものです。","id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"質問","question":"より公的性を高めていくということなんですけれども、高まったというチェック、税金の使い方のチェックというのは、議会でも報告が変わったりとかはするんか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"しかし、今後、法律に評議委員会の監査機能といいますか、評議委員会が最高決定機関となるように法律が明記されました。ですから、従来と違って評議委員会は、しっかり財団内部の事業ならびに予算、決算を見ていくという形になります。","id":"exchange-033"},{"speaker":"石田（ち）委員","kind":"質問","question":"今まで評議委員は、理事の方が選べたということなんですけれども、それはこの間、文化スポーツ振興課長が言われた、もらったときのものを読んだんですけれども、理事が選任できなくて、主務官庁が選ぶということになるのか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"理事会は選ぶことができなくて、評議委員選定委員会という別組織をつくりまして、そこで選定をして評議委員を選ぶという形になっております。これは法律に明記されたところです。","id":"exchange-034"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、今まで文化振興事業団、スポーツ協会も、議員が評議委員で入っていたと思うんですけれども、それは変わらず入れるということなんか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"今言いましたように、理事会、評議委員会があります。体育指導員の方だとか、それぞれ事業団が選定しているものです。","id":"exchange-035"},{"speaker":"石田（ち）委員","kind":"意見","question":"プールなんかも独占されているような声も聞くので、そういったことも改善されていくのかどうかとの意見を述べました。","respondent":"安藤文化スポーツ振興課長","answer":"公益認定を受けて今後の事業展開にかかわることだと思いますけれども、先ほど言いましたように、従来も公益事業をかなりやっておりました。","id":"exchange-036"},{"speaker":"石田（慎）副委員長","kind":"確認","question":"１点だけ確認なんですが、公益財団法人、国際友好協会も公益化をされると思うんですが、これ、文化振興事業団とスポーツ協会、今回、２議案ですけれども、国際友好協会に関してはどのようになっているのか、そこだけ確認させてください。","respondent":"今井協働・国際担当課長","answer":"国際友好協会に関してのご質問ですけれども、品川区国際友好協会につきましては、品川区の補助金交付規則に基づいて、今は財団法人品川区国際友好協会補助金交付要綱で補助金を支出しておりますので、条例ではございません。","id":"exchange-037"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やっぱりより区民が参加しやすくなるということが公益性が高くなるということだと思いますので、それとやっぱりチェックもしっかりできる環境をつくれるようにしていただきたいなと思うので、意見として言って賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"}]},{"id":"topic-06","title":"平成２４年陳情第１号、品川区の地域の歴史に親しめるまちづくりを一層推進することに関する陳情","agenda":"平成２４年陳情第１号、品川区の地域の歴史に親しめるまちづくりを一層推進することに関する陳情","exchanges":[{"speaker":"本多委員","kind":"質問・要望","question":"品川の歴史を重んじれば、江戸開府以降の４００有余年だけではなくて、もっと長いスパンで取り組んでいただいているものだと思うんです。その辺のところを思いを聞かせてほしいと求めました。","respondent":"安藤文化スポーツ振興課長","answer":"ご案内のとおり、品川というのは、江戸がメインで前面に出されますけれども、品川は歴史のどこを切っても品川が出てくるというように考えています。特別展においても、徳川家光、いろいろな時代をもとに特別展を展開している、皆さんにご報告させていただいているところです。","id":"exchange-039"},{"speaker":"本多委員","kind":"質問","question":"質問ではないんですけれども、やはり歴史というものはものすごく大切なものでありますので、その趣旨をもって、今、区政が取り組んでいるということは十分認識しておりますので、この陳情については、私としては、理解がもう少し具体的なことが挙げていただければよかったなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"沢田委員","kind":"質問","question":"事実、それをただ本にまとめたりというのは、これは区がやることなのかどうなのかなというのはすごく感じます。「誰もが」というのは、だれでも興味を持つかはわからないですけれども、この辺の事実のことに関してはどういう認識をお持ちか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"龍馬とか伊藤博文の部分のくだりはありませんが、史実として小学生の３年生と５年生の皆さんには、歴史のことについては教育をしているです。","id":"exchange-041"},{"speaker":"大倉委員","kind":"質問・要望","question":"私も２８年間この品川区に住んでいて、あとは、やっぱりこれからもいろいろな方に知っていただきたいなという思いがあります。もっとやっていただきたい部分もありますが、計１５８カ所の看板設置とか、趣旨としては私たちとしては認めてもいいのかなというところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"山元委員","kind":"意見","question":"」という部分があったりして、そう思うと、ちょっと賛同できないかなという感じがします。逆に、その思いは、いろいろな思いがこの方にあるのであれば、課長、ぜひその話は個人的に聞いてあげてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"藤原委員","kind":"確認","question":"確認をしたいんですけれども、両課長からのさっきの説明の中を伺っていると、陳情の中でこの方のものが、１、２、３というふうには書いていないです。","respondent":"中川原地域振興事業部長","answer":"この方が言っているのは、区の立場とか、区がどう考えてやっているというのをお伝えできないもどかしさがやはりどうしてもあります。両方で説明していますが、やっぱりそれは限界といいますか、ある役割を持ってやらなければいけない。","id":"exchange-044"},{"speaker":"藤原委員","kind":"質問","question":"ただ、区としてこの陳情をという形になると、行政としては難しいものもあるということでとらえてよろしいか尋ねました。","respondent":"中川原地域振興事業部長","answer":"先ほど来、文化スポーツ振興課長が繰り返していますけれども、歴史館というのが歴史をまとめる所管とすれば、確認できないことを、この方が言っていらっしゃいますような、今の段階で江戸とか、ロマンの部分については、歴史館としてまとめるのは非常に難しいということです。","id":"exchange-045"},{"speaker":"本多委員","kind":"質問・要望","question":"本日、結論を出してほしいと求めました。態度については、陳情願意に沿えないということで、不採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"山元委員","kind":"質問・要望","question":"今日、結論を出してほしいと求めました。結論的には、不採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"石田（ち）委員","kind":"意見","question":"若い世代から高齢の方まで、歴史の好きな方はたくさんいますけれども、やっぱりそれは意見がさまざまなんですね。ちょっと私たちもどうしようもないなと思うんですけれども、明らかにしていくということはいいことなのではないかなと思うので、共産党は採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/118408?Template=document&Id=2628#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":43562,"voices":169}},{"id":"h24-20120227-7","meetingId":"h24-cm02","date":"2012年2月27日","dateIso":"2012-02-27","committee":"厚生委員会","time":"午前１０時００分～午後６時１６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を116件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これによって、例えば、介護保険料に跳ね返る金額というのはどのぐらいで、規模として見込んでいるのかということを教えていただきたい。第２０号議案を見ていて、こうなっているのかどうかわからないので、それだけ説明を求めました。","respondent":"原高齢者福祉課長","answer":"この４月から実施するのは定期巡回・随時訪問対応型訪問介護看護のほうでございまして、この新サービスの中で、区として実施していくものです。一人が１カ月、おおよそ２０万円ぐらいの形でございまして、現在のところはないと認識しています。","id":"exchange-001"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"項目としては入っているんですが、これは、品川区は今回はやらないということでいいんですよね。それでも、条例の中には規定するということなのか、そこのところだけ確認させてください。","respondent":"原高齢者福祉課長","answer":"法改正によって項目がずれてまいりますので、今までの特別養護老人ホームの項目が２項ずれましたので、そういった意味で直したといったものです。","id":"exchange-002"},{"speaker":"若林委員","kind":"質問・要望","question":"第１９号議案のほうですが、全体として、貸付の対象となる施設は、今までと変わらないという、もし違いがあれば、教えていただきたい。ここら辺、どういうふうに理解したらいいのか、大きく２点。","respondent":"原高齢者福祉課長","answer":"６カ月以内に就職し、３年経ったら免除すると、この法を持ってきて根拠としているというものです。障害者自立支援法のほうに移行した関係で、障害者自立支援法で、障害者自立支援法の第５条第６項から第１６項のうち七つの項が。","id":"exchange-003"}]},{"id":"topic-02","title":"第２２号議案、品川区介護保険制度に関する条例の一部を改正する条例","agenda":"第２２号議案、品川区介護保険制度に関する条例の一部を改正する条例","exchanges":[{"speaker":"鶴委員","kind":"質問・要望","question":"１ページの改正理由のところの1)で、５０人から７０人というところについて、それを教えていただきたい。なぜこのところを二つに細分化されたのか、人数の分布の問題だったのかなと、ちょっとその辺を教えてほしいと求めました。","respondent":"原高齢者福祉課長","answer":"平成２４年度１月現在で１万１,０００件ですけれども、平成２２年度の山が２年後ということで、平成２４年度予定をしております。審査件数が１万５,０００件ということで予定しておりまして、なかなか難しいということで、合議体を増やして審査会を実施するです。","id":"exchange-004"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今、新規、更新までは数字を教えていただいたんですけれども、区分変更がどのぐらいあるかも教えてほしいと求めました。前回の１１月のときも、部分的にはお聞きしたんですけれども、すべての１から１３段階までのそれぞれの人数を教えてほしいと求めました。","respondent":"原高齢者福祉課長","answer":"区分変更の件数ですけれども、今年の１月現在で、平成２３年度が１,５００件です。１１段階が２,０００人、１２段階が１,６００人、１３段階が６００人です。","id":"exchange-005"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"９億円取り崩して、第四期の最後には１４億円残るという計画だったと思うんですけれども、どうだったのかということ。それで、何億円から何億円を取り崩して、現在、基金として何億円あるのかということを教えてほしいと求めました。","respondent":"原高齢者福祉課長","answer":"一応、５月の出納閉鎖を見てみないと、なかなか推測は難しいところではあります。１０億７,０００万円、介護給付費準備基金のほうは取り崩す予定で保険料を計算しています。","id":"exchange-006"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"８億円取り崩して１９億円余っているということですと、第四期のはじめのときは２７億円基金が残っていたという考え方でいいんでしょうか。全都で２４０億円で、市町村の分が８０億円という説明だったんですけれども、そこのところを教えてほしいと求めました。","respondent":"原高齢者福祉課長","answer":"それから、幾らぐらい残すのかですけれども、今、８億円程度のところで予定をしているわけです。今、４０億円ぐらいの保険料を見込んでおりますけれども、２カ月ちょっとの分ぐらいを残していきたいととらえているところです。","id":"exchange-007"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それが４,７００円ということで、今回、高いほうの保険料設定になったわけですけれども、その理由というのも、教えてほしいと求めました。そういう方針が、どういうことに使われていくのかというあたりも、わかったら説明を求めました。","respondent":"原高齢者福祉課長","answer":"そこについては検討しているということで、東京都の部分については、まだ明らかな状況になってきているところではございません。若干、給付が伸びているということも合わせて、４,６００円から４,７００円のところの保険料を４,７００円でお願いをするところです。","id":"exchange-008"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"現場で働く人たちへの影響がどうなるのかというあたりも、検討されているところがあったら、ちょっと教えてほしいと求めました。７８円ぐらいの分が市町村特別給付という形で使われていくのか、このことについても、お聞かせほしいと求めました。","respondent":"原高齢者福祉課長","answer":"平成２３年度が約２,７００万円というところで想定をしておりまして、それが第五期になりますと、３,０００万円です。そういった意味では、多くの金額が増えるというところでは、想定をしていないところです。","id":"exchange-009"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"介護報酬に上乗せといっても、わずか１.２％ですし、これはまたぜひ、現場のほうからも声を挙げていただきたいと要望させてほしいと求めました。ほかの区のように、一般財源で行うという方向に変えていただきたいと思うんですけれども、いかがか尋ねました。","respondent":"原高齢者福祉課長","answer":"というところが基本となっておりますので、そういった中で、品川区としては対応しています。ご理解のほど、よろしくお願いいたします。","id":"exchange-010"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ちょっと考え方をお聞きしたいんですけれども、それから、どういう基準でここのところを決めているのかということをお聞かせほしいと求めました。そして、その一つ一つの料率をどういうふうにして決めていくのかという考え方について、お聞かせほしいと求めました。","respondent":"原高齢者福祉課長","answer":"６５歳以上は介護保険料の２１％という免責がありますので、どのように負担をしてもらうかということで、この段階を設定させていただいたです。","id":"exchange-011"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それから、国の基準でも、８００万円から２,０００万円と一足飛びにこういうふうな形に、その施行令でもなっているんでしょうか。３,０００万円以上になると、３,０００万円以上が何人ぐらいいるのか、わかったら教えてほしいと求めました。","respondent":"原高齢者福祉課長","answer":"２,０００万円という金額が、国の考え方は、この８段階以外の方ということで言っております。３,０００万円以上の方ですけれども、申しわけございません、手元にそういった数字はございません。","id":"exchange-012"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"１６８万円までの人は６,０００円で済んでいるわけですけれども、８０万円といえば非課税ですから、年額４,０００円で済んでいるわけです。そこら辺のところの考え方については、いかがか尋ねました。","respondent":"原高齢者福祉課長","answer":"第１、第２段階は４分の２ということで、０.５の料率とされているところです。０.４ということでございまして、０.４ということでの料率を設定させていただき、ご理解をいただきたいと考えています。","id":"exchange-013"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１億８,０００万円あればできるんですけれども、お金のあるところに応分の負担を求めるということで、あらためて思ったんです。１３段階ということで、能力に応じた負担になるという改善をしてほしいと求めましたけれども、いかがか尋ねました。","respondent":"原高齢者福祉課長","answer":"先ほどから、介護保険の施行令というのが基本となりつつ、ということでお話ししています。１０.何倍というような形というのは、国の施行令から考えても、いかがなものかというところで理解をしています。","id":"exchange-014"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"介護保険料というのは、今でも、これだけ限界という状況だと思うんです。これをさらに応能負担というところを提案をしていっていただきたいと要望をさせていただいて、とりあえず、終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だけれども、何で旧の第４段階と第６段階が下がっちゃうわけですか。大体全区出てきたんでしょうから、２３区の中でどれぐらいにいるかというのは言いたいんでしょうから、それはぜひ伺っておきます。","respondent":"木下健康福祉事業部長","answer":"２点目なんですけれども、保険料が安いところをベストだというふうに考えますと、片手で入るぐらいの範囲に落ち着いております。逆に足りないことはないという適切なマネージメントの結果でありますので、そのことを、今後とも引き続き努めていきたいと考えています。","id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問","question":"何だよ、ふざけるなとなる人たちなんですよ、負担を多くしているんですから。そういう人たちには、やっぱりしっかり、もうちょっとこういうときには丁寧に説明をするべきだと、これだけはお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"若林委員","kind":"質問・要望","question":"どういうふうに影響しているのかというのは、私たちはちゃんと理解しなきゃいけないと思いますので、教えていただきたいと思うのが一つ。ここを、全体的に、ちょっとお話をほしいと求めました。","respondent":"原高齢者福祉課長","answer":"区のほうで、向う３カ年の保険料の負担を考えまして、４,７００円ということで設定をさせていただいたところです。細かいところの数字は、ちょっと手元にはございませんけれども、そういった意味では、少し第７段階から第１３段階までの負担の部分が増えているです。","id":"exchange-018"},{"speaker":"若林委員","kind":"質問・要望","question":"２３区の中でも、品川区の区独自のご努力というのも、これは私たちはちゃんと理解をさせてほしいと求めました。基金の積立てというのですか、大変重大な局面というのですか、ご答弁ほしいと求めました。","respondent":"原高齢者福祉課長","answer":"そういった考え方の中で、１０億７,０００万円を、これによって約４００円の保険料の引き下げになっているです。基金というのは、非常に保険料に寄与する部分がありますので、きちっとした考え方の中で基金の管理をしていきたいと思っているところです。","id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"４００円引き下げになるということでしたけれども、それは財政安定化基金の２億２,０００万円も入れて、４００円という考え方になるのでしょうか。だから、今回の基金の繰入れは、トータルで１３億円弱になるんか尋ねました。","respondent":"原高齢者福祉課長","answer":"財政安定化基金は別でございまして、そちらのほうは約８０円の保険料への給付ということで考えているところです。","id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ということは、では、介護給付費準備基金で４００円で、財政安定化基金で８０円で、合わせて４８０円の引き下げということになっていくんでしょうか。これそのものも、もうちょっと上がっているということなんでしょうか、そこのところを説明を求めました。","respondent":"原高齢者福祉課長","answer":"４,６００円から４,７００円というご質問の中で、推定の保険料を５,０５３円から５,１８１円ということで、保険料を４,７００円ということで設定をしています。","id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"意見","question":"先ほど、若林委員からも第六期の話が出たので、ぜひここで、一つだけ言っておいてほしいのは、今、４,７００円と。一言ぐらい言っておかないと、３年後に大きな議論になってしまうから、今一言だけ言っておいたほうがいいと思いますとの意見を述べました。","respondent":"原高齢者福祉課長","answer":"基金が約８億円の残というところで計算していきますと、当然考えておかなくてはいけないということで、保険料というものも上がる要素はあるです。","id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今でもぎりぎりで生活している中に、これだけの負担増になるということは、区民生活を大変圧迫するということで反対です。１３段階ということにしていますけれども、ぜひそういうところでも、区のほうにも要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"}]},{"id":"topic-03","title":"第２３号議案、品川区立心身障害者福祉会館条例の一部を改正する条例","agenda":"第２３号議案、品川区立心身障害者福祉会館条例の一部を改正する条例","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"心身障害者会館が、これでどういうふうになるのかというのを、ついでに説明してくれると非常に助かります。多分皆さん大分イメージは持っているので、それがどういうふうになるのかということを、ちょっと説明を求めました。","respondent":"永尾障害者福祉課長","answer":"ちょっと説明が不足しておりまして、申しわけありませんでした。障害者生活支援センターですけれども、基本の相談プラスアルファで、継続して相談支援をするような位置づけにすることが変わるところです。","id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"この件は、私も一般質問させていただいたので、今おっしゃったとおり、サービスも増えていく、スペースをつくろう、ほんとうにこれは手狭だと思うので、大変だと思いますが、よくいろいろ総合的に検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私もいろいろと勉強してみたんですけれども、それでもなかなか理解するのは大変だなと思いながら、ちょっと質問させていただきたいんです。３年以内と言われているということなんですが、そこら辺のところを、ちょっとお聞かせいただけたらと思います。","respondent":"永尾障害者福祉課長","answer":"やはりこれからは相談支援の充実ということですので、専門の医師等が入る審査会に基づいて、実際の支給決定を行うというような方向になると思います。なおかつ、多様性があるということから、もうちょっときめ細かくやっていく形になるかなと考えています。","id":"exchange-026"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"それとも、今の時点で、３年を見越して、こういうふうな方向で進めていきたいというような方向があるのか、そこら辺のところ。そこら辺のところの課題というところを、ちょっと区としてはどんなふうに考えてられているのかも、お聞かせいただけたらと思いますとの意見を述べました。","respondent":"永尾障害者福祉課長","answer":"３年後になるかどうかはわからないんですけれども、将来的には、やはり１カ所では足りないのかなというふうに考えております。は初任者研修を５日程度、継続して研修をまた何年かに１回受けるというような位置づけに、今のところなっております。","id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"自立支援協議会を法的に位置づけるということで書かれていまして、このことが、品川区でどうなっているのか。既に位置づけられているのであれば、どんなメンバーがいて、どんな活動をしているのかということについてお聞かせほしいと求めました。","respondent":"永尾障害者福祉課長","answer":"チームを持って対応していかないと、なかなか対応しきれない部分もありますので、部会を四つつくりました。お互いに連携を取り合うような体制も、少しずつできているかと思いますので、その辺をさらに充実させていきたいというふうに考えております。","id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"お聞きしたいのが、第６条の２の使用料のところなんですが、今まではどうなっていたのか。イのところに書かれているんですけれども、この中身についても、教えてほしいと求めました。","respondent":"永尾障害者福祉課長","answer":"今までもやってはいるんですけれども、内容につきましては、さらにいろいろな障害に対応できるような内容を、今、検討しております。実費部分については、ご自身で負担していただくということで、そのほかの利用については無料と考えております。","id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ということは、基本的には、今までと変わらないということでとらえていいんでしょうか、材料費の実費という点では。","respondent":"永尾障害者福祉課長","answer":"ちょっと説明が漏れてしまいましたけれども、今までと同様です。障害者地域活動支援センターになるということで、今、組み直しをしています。","id":"exchange-030"},{"speaker":"若林委員","kind":"質問・要望","question":"これもちょっと明らかにしてほしいと求めました。ここら辺の展望というのか、組立てを、ちょっとお聞きしたいと思います。","respondent":"永尾障害者福祉課長","answer":"平成２２年度から、そういうシートはどういうふうにつくるべきか、というような検討は続けてきております。そういう検討を受けて、自立支援協議会での専門部会の検討なども含めて充実させて、少しでもスキルアップをしていきたいと考えております。","id":"exchange-031"},{"speaker":"若林委員","kind":"質問","question":"わかりました。マニュアルというのでしょうか、そういうものをしっかりと提示をして、また委員会にもご報告いただくということで理解してよろしいか尋ねました。","respondent":"永尾障害者福祉課長","answer":"このあたりにつきましては、実は国のほうも、またきちんとした政令が出し切れていない部分がありまして、今も少しずつ動いている状態です。その中で、そちらも参考にしながら、区としての考え方を決めていきたいと考えています。","id":"exchange-032"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そこら辺の中身について、ちょっとお聞かせいただきたい。それから、障害者地域活動支援センターの生産活動というのは、どういう中身なのかも、ちょっと教えてほしいと求めました。","respondent":"永尾障害者福祉課長","answer":"就労移行支援につきまして、４月からげんき品川のほうに移るということで、今、保護者にもご説明が終わりました。別の就労継続Ｂ型の事業だとか、今度新しくやる障害者地域活動支援センターのほうで過ごすとか、やっているところです。","id":"exchange-033"}]},{"id":"topic-04","title":"第２６号議案、品川区立児童学園条例の一部を改正する条例","agenda":"第２６号議案、品川区立児童学園条例の一部を改正する条例","exchanges":[{"speaker":"若林委員","kind":"質問・要望","question":"しっかりと確認させていただいたうえで、地域の中核的な療育支援施設という位置づけで、おおむね１０万人に１カ所のイメージというふうにありました。解釈といいますか、理解はどのようにされているのか、ちょっとお聞かせほしいと求めました。","respondent":"永尾障害者福祉課長","answer":"その間に整備をして実施と、平成２４年度すぐに中身を変えるということは、今のところはありません。そのあたりの連携なども必要になってきますので、検討を進め、３年後に備えていきたいと考えております。","id":"exchange-034"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ということが書かれていたんですけれども、こういうのがどうなっていくのかということについて、お聞かせほしいと求めました。それから、センターの体制がどうなっていくのかということについてもお聞かせほしいと求めました。","respondent":"永尾障害者福祉課長","answer":"この３年間の検討ということと、それから政令がどう出てくるのかとか、その辺を含めながら考えていきたいと思っています。それを受けまして、現在、平成２４年度の予算案の中で、それぞれ１人ずつ人員配置を予定しているところです。","id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"このセンターを使うにあたっては、利用料というのは発生することがあるのか、どうか。ちょっとそのところだけ説明を求めました。","respondent":"永尾障害者福祉課長","answer":"法的な整備の中で変更になっていまして、今までは障害者自立支援法の中で規定されていたのが、障害者自立支援法のその条項が廃止されて。９,３００円、それ以外は３万７,２００円、１カ月この上限までということになっているものです。","id":"exchange-036"},{"speaker":"石田（秀）委員","kind":"質問","question":"それでみんな困っている。もし今、お考えがあるなら、説明を求めました。","respondent":"永尾障害者福祉課長","answer":"ただ、区として、所管をどこの部にするかというところは、やはり非常に難しいところはあります。教育委員会も同じような状態ですので、このあたりがやっぱり、３年間の間に調整すべきところかなと考えているところです。","id":"exchange-037"}]},{"id":"topic-05","title":"第２７号議案、品川区国民健康保険条例の一部を改正する条例","agenda":"第２７号議案、品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"４,５４４円ということで、２３区平均よりも、４.５倍の値上げ幅になってしまうということなんでしょうか。なぜこういう形で、２３区平均よりもかなり高い一人当たりの値上げの幅になってしまうのかということについて、もうちょっと説明を求めました。","respondent":"本城国保医療年金課長","answer":"先ほどちょっと説明をはしょってしまったところがあるんですが、９ページに、それは所得の全体的な水準が若干高めだです。旧ただし書所得が１.３％下がる見込みだということで、２３区平均だと、これよりも相対的に下げ幅が少なく見込んでいるところですとか。","id":"exchange-038"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"滞納世帯がこれまでに増えたということに対しての区の認識を、ちょっとお伺いしたいと思います。それから、あらためて短期証、資格証、差し押さえ件数、その数字も説明を求めました。","respondent":"本城国保医療年金課長","answer":"ご説明いただいたような、２５％ということになっておりますが、いろいろな要因で収納率が増減しているんだなと感じているところです。同じく１２月現在で、差し押さえ件数についてが１４９件となっています。","id":"exchange-039"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"払える能力があるにもかかわらず払わないという確認を取れたところでされているのか、そのことについてお聞かせほしいと求めました。差し押さえなんですが、１４９件はかなり増えているという感じがするんですけれども、この中身についても、教えてほしいと求めました。","respondent":"本城国保医療年金課長","answer":"最終的な形として、どうしても一切連絡が取れない方について、場合によっては資格証対応にしたりするということです。それから、滞納の場合の差し押さえですが、ほとんどが預貯金の差し押さえとなっているところです。","id":"exchange-040"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"保険料が変わったわけですから、どういうふうに保険料が経年的に変わるのかというのが見えるので、区としても工夫してほしいと求めました。値上げされるというのが区民の実態ですので、ぜひ、そういうふうにお願いしたいと思うんですけれども、その資料の点ではいかがか尋ねました。","respondent":"本城国保医療年金課長","answer":"厚生委員会でも何度もご説明させていただいたところですが、賦課方式の変更、あらためてご理解いただけたらと思います。逆に、経過措置で２万９,０００円下がっているんだという、全体としてバランスの取れた判断ではないかと思うところです。","id":"exchange-041"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"控除されているものをすっぽりなくしてしまうというのが旧ただし書き方式ですから、今回の値上げが直撃するということになっているわけですから。年収ですから、３年間で値上げというのは、いかがか尋ねました。","respondent":"本城国保医療年金課長","answer":"もちろん、窓口対応では、各窓口の係の職員は、一人ひとりの状況に応じて丁寧に説明させていただいているところです。これも繰り返しご説明していますが、最大限経過を円滑にするという意味で、そういう視点からもご理解いただければありがたいと思っているところです。","id":"exchange-042"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そこのところを見ても、大変な人のところにより重い負担になるというのが、今回の制度改正の中身だと思います。経過措置を継続して、これ以上の値上げにはしないという方向をご検討いただきたいということで要望させていただいて、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それから、さっきから統一、統一というのはわかるんですけれども、区の考えを教えていただきたい。もうこのぐらいにしようということはできるわけですから、どう考えていらっしゃるのかというのは、お聞きしたい。","respondent":"本城国保医療年金課長","answer":"その方向性として考えていると、そのような延長で、現時点まできたということは確かだと思います。平成２３年度からそのように移行していますが、本来のところにいくにあたっての２年間の臨時的な、一応考えているところではあります。","id":"exchange-044"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だけど、ここに書き込むわけじゃないですか、こうやって。それは、ぜひ、強い意識を持っていただきたいという要望にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"だから、２割に上げるなんていうのは、しかも２倍ですから、高齢者の実態を考えたら、そんなことはとんでもないと思います。ぜひとも、区としては１割のまま続けるようにということで頑張っていただきたいと、私は要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"負担が、ほんとうに異常な値上げだと、私は思います。１.８倍とか、そんな異常な保険料の値上げになっていますので、今の区民の実態を考えたら、とても賛成するわけにはいかないと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"若林委員","kind":"質問","question":"では第２９号議案を中心にお聞きしたいと思います。この辺をお聞きしたいと思います。","respondent":"工藤品川区保健所生活衛生課長","answer":"理容所等への立ち入りですけれども、私どものいわゆる専門職であります環境衛生指導員がおります。おおむね２年に一度、最初に開設の届けを出したときと構造上の変更がないかとか、消毒等の器具が整えられているか。","id":"exchange-048"},{"speaker":"若林委員","kind":"質問・要望","question":"２年１回、すべての事業所を回って、既に確認がされているというふうに理解をいたしました。お話を伺いたいと思うんですが、というご要望がありますけれども、ここについての区の見解をお聞きしたいと思います。","respondent":"工藤品川区保健所生活衛生課長","answer":"上下水道の設置という部分を、十分な水量が期待されるというのは、私どものほうも思っているところです。こういったものに漬けて１０分間浸すということで、現状のところ、衛生面での確保という部分が十分に保たれていると考えているという理由からです。","id":"exchange-049"},{"speaker":"若林委員","kind":"確認","question":"それを防ぐには、やはり手の洗浄、手洗いの励行ということが大変重要だというふうに思います。しっかりと保健所のほうで確認をする、ここに入れるということについて、品川区の見解を伺いたいと思います。","respondent":"工藤品川区保健所生活衛生課長","answer":"上下水道の設置という部分で、設置をすれば、そこの部分は実施をしていただいているというのが現状です。上下水道の設置のない理容所、条例化するにはなじまないと、区としては考えております。","id":"exchange-050"},{"speaker":"若林委員","kind":"質問","question":"タンク式ということが出ましたが、タンク式でそれにかえているところが何件か。どちらもないところが何件か、ここら辺の実態を、ちょっと説明を求めました。","respondent":"工藤品川区保健所生活衛生課長","answer":"品川区内の理容所の実態ですけれども、昨年３月末で、２３０カ所あります。ただ、数年前、タンク式の営業所があったということをとらえておりますけれども、そちらのほうは、今現在、廃業されているという実態があります。","id":"exchange-051"},{"speaker":"若林委員","kind":"質問","question":"現在、上下水道がすべて完備しているということですので、条例の中に盛り込むということは、もう当たり前のことではないかと、今のご答弁を聞いて、私は感じましたけれども、もう１回、いかがか尋ねました。","respondent":"工藤品川区保健所生活衛生課長","answer":"そういった中で、営業のある部分の自由も奪ってしまうという考えもあります。新しい方法等がある中で、一律に条例をもって上下水道の設備を義務づけるということは、現段階ではなじまないと思っているところです。","id":"exchange-052"},{"speaker":"若林委員","kind":"質問","question":"このＡ３版の資料の中で、その他があります。その他、それを踏まえて、それに対してはこういう衛生基準というふうに縦分けて条例化するということは可能じゃないか尋ねました。","respondent":"木下健康福祉事業部長","answer":"これまで東京都がやってきた基本的な対応の部分と、区の対応の部分が、東京都が扱っているやり方を基本的に受け継ぐべきだと考えているところです。対応がされているという状況があるわけでありますから、規定はなくても、今後とも十分対応できるということ。","id":"exchange-053"},{"speaker":"若林委員","kind":"質問","question":"実態もこうですというご報告があったわけですから、来月の４月１日をもって、今のような質問をさせていただきました。４月１日を境にしたって、そういう規則なり、運用なりという文言化はできないものか尋ねました。","respondent":"工藤品川区保健所生活衛生課長","answer":"東京都の条例があり、東京都の規則、運用があるわけです。考え方の基本ですけれども、考えていきたいというのが、区の考えです。","id":"exchange-054"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"この請願の代表の方にいろいろとお話をお伺いしまして、水道がないというのは、ちょっと考えられないという思いがしたんです。こういう形で条例が提案をされていますので、それから理容組合とかの団体からの要望を受けとめて、確認をさせていただけますか尋ねました。","respondent":"工藤品川区保健所生活衛生課長","answer":"規則、運用等につきましては、条例の考え方を踏まえるですので、まず、そちらのほうには、現在のところ、盛り込むつもりはございません。","id":"exchange-055"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうところがないようにということで、ぜひ指導もしていただきたいですし、そうせざるを得ないような文言というのはいろいろあるかと思うんです。ぜひ貫いていただきたいと思うんですけれども、改めて、そこのところだけ確認をお願いします。","respondent":"工藤品川区保健所生活衛生課長","answer":"規則等に盛り込むという考えはございませんが、平成２１年１０月に、この通知の趣旨を酌み取った中で指導をしてまいります。","id":"exchange-056"},{"speaker":"石田（秀）委員","kind":"意見","question":"そういうこともあるから、私は、条例はこの形でいくべきだと思っています。そういうことも含めてやっていくべきであって、今、この時点で何かをやるべきではないと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"},{"speaker":"若林委員","kind":"質問・要望","question":"実は、質疑の内容によって、委員会の中で附帯決議を、ぜひつけさせていただきたいということで、文面を用意をしてまいりました。あしたになるのかということを、まずお知らせをして、条例については賛成をいたします。","respondent":"山内委員長","answer":"条例についての採決をしなければならないので。は条例に関する採決を先に行います。","id":"exchange-058"},{"speaker":"若林委員","kind":"意見","question":"附帯決議を、まだ皆さんにご提示していませんので、これを、後ほどしっかり提示をさせていただいて、検討をしていただくと。そのうえで、条例についての賛成、反対は、また申し述べるということになりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"石田（秀）委員","kind":"質問","question":"今、三つをやっているわけですから、その中で、これについては附帯決議をつけてほしい。附帯決議はここの中で皆さんで議論するわけですから、つくのだったら賛成しますと、そういう諮り方なんですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"石田（秀）委員","kind":"意見","question":"運用等があるわけで、そこに踏み込むようなものを条例に附帯決議つけていくということは、私はするべきではないと考えています。規則、運用を縛っていくようなものを、特にこの附帯決議でつけていくということには反対ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-061"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これからも、１００％すべて上下水道がつながっているという現状を、品川区の中で保ってほしいと求めました。そういう意味からも、そういう形で設置を縛っていくというか、そういう形での附帯決議ということで、ぜひ賛成をしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"石田（秀）委員","kind":"質問","question":"例えば我々は会派政治もしているわけですから、何にしても、そういう形の中でしっかり附帯決議をつけていくべきであろう。内容がどうのこうのというのは、それで全会一致にするべきだと思っていますので、附帯決議をつけるべきではない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"若林委員","kind":"意見","question":"地域主権の中で、議会として、全会一致の原則という中で示させていただいたつもりです。私も含めて３会派、あと２会派の方もいらっしゃいますので、それはもう一任しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-064"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけ教えてください。みんな一つ一つにお伺いを立てて、相談に乗ってくれるという、一つで流れるような制度はできないんですかね。","respondent":"工藤品川区保健所生活衛生課長","answer":"私どもも許認可をするときには、すべての部分で了解が取れているかどうかということを確認しているというのが、現段階での現状です。国のほうでも、縦割りではないんですけれども、法律の管轄の部分が異なっているということで、現状は、このような形になっているところです。","id":"exchange-065"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"まさに建築確認なんかそうで、だからどんどん民間に流れていくわけで、そういうことも含めて、ぜひお考えいただきたい。今、法律では保健所でやらなくちゃならないんだけれども、そこら辺のところも含めて、ぜひお考えいただきたいと、これは要望だけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"鶴委員","kind":"質問・要望","question":"第３１号議案の件ですけれども、その辺の件数の把握がもしあれば、ちょっとまず教えてほしいと求めました。","respondent":"工藤品川区保健所生活衛生課長","answer":"乾燥機器を設置している、給食施設のほうに入ってクリーニングをして受渡しをしているという、この三つの分類があります。品川区内、先ほど言いました一般の機器等を設置しているクリーニング所が１６４カ所、リネンサプライが８カ所というのが内訳になっております。","id":"exchange-067"},{"speaker":"向委員","kind":"意見","question":"１０歳以上の男女は混浴させないというのがあって、１０歳って、どうかなと。１０歳のときに、そのあたりのお考えだけ、お願いしますとの意見を述べました。","respondent":"工藤品川区保健所生活衛生課長","answer":"どういった基準を用いて１０歳になっているのかという部分が、いろいろと調べたんですけれども、資料が出てきてないというのが現状です。そういった部分に関しましても、今後それぞれの社会情勢等を踏まえながら、そういった部分も含めまして検討していきたいと考えています。","id":"exchange-068"},{"speaker":"若林委員","kind":"質問","question":"第２８号議案から第３３号議案が区の条例になって、２年に１回立ち入り検査ということでしたが、立ち入り調査をしているものなんですか。逆に、２年に１回でいいんですかという思いも含めながら。","respondent":"工藤品川区保健所生活衛生課長","answer":"年に２度、私どものほうで必ず立ち入り、監視をしています。７名おりまして、この７名が年間の最初の許認可、通常時の年間にわたっての監視活動をやっているというのが現状です。","id":"exchange-069"}]},{"id":"topic-06","title":"第３４号議案、品川区墓地等の構造設備および管理の基準等に関する条例","agenda":"第３４号議案、品川区墓地等の構造設備および管理の基準等に関する条例","exchanges":[{"speaker":"向委員","kind":"質問","question":"火葬炉のことなんですけれども、５基以上設けることとなっていて、今、区内で１日当たり、火葬は何件ぐらいあるのか。それから、１カ所当たり、１日平均、例えば１０件とか、１５件とか、わかれば教えていただけませんか。","respondent":"工藤品川区保健所生活衛生課長","answer":"区内の火葬場は、桐ヶ谷斎場が１カ所あります。炉が１２基設置されておりまして、大体１日の処理の最大が８４体という形の能力を有しております。","id":"exchange-070"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そういうところが、今、こういう時代だから、納骨堂という話をしたときは、許可が出ないという理解ですか。そこら辺で、駐車場ってつけたのはいいんだけれども、そこら辺の考え方はどう理解しておけばいいんか尋ねました。","respondent":"工藤品川区保健所生活衛生課長","answer":"駐車場の設置というのが、いわゆる墳墓の２％というのが一応、それでお願いしているという現状です。考え方としましては、建物だけでなく駐車場の設置を求めると、今の現状の区の考え方です。","id":"exchange-071"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１台は１台になってしまうじゃないですか、１台でよければ、わからないけれども。何となく、納骨堂については、これから増えそうな気がしてならないので、ちょっと教えていただきたい。","respondent":"工藤品川区保健所生活衛生課長","answer":"納骨堂、墓地等を設置する場合には、いわゆる近隣住民との協議が必ず条件になっております。説明会を開催しまして、区としてもしっかりと、保健所として指導していくというのが現状の考えです。","id":"exchange-072"},{"speaker":"石田（秀）委員","kind":"確認","question":"最初はもめたけれども、結局、建築確認が下りて、建ってしまうわけでしょう。建築確認というのはあるわけだから、今、近隣の方と話したって、訴訟になったって、建築確認自体は下りちゃうわけではないか尋ねました。","respondent":"工藤品川区保健所生活衛生課長","answer":"区内の中で継続して宗教活動が行われて、かつ、基本的にはいわゆる今の宗教活動をしている寺院の範囲の中で建つものだと考えております。","id":"exchange-073"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"墓地とか納骨堂の建設というのが、品川区でどの程度あったのか、まず実態をちょっと教えてほしいと求めました。","respondent":"工藤品川区保健所生活衛生課長","answer":"ここ数年で言いますと、一番新しいものが、委員ご指摘の二葉四丁目にある丸山寺、これが平成２２年度に１件あります。平成２０年に、平成１２年７月に、平成１０年以降は３件という形になっております。","id":"exchange-074"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"本当に住宅地、自分が住んでいる隣に突然墓地ができるとなったら、やはり抵抗感があると思うんですね。その中で、どういうふうに(1)と(6)というのは中身が違うのかということと、どの程度考えられているのかということについて説明を求めました。","respondent":"工藤品川区保健所生活衛生課長","answer":"１号は区域と隣接する土地との境界にはということですので、いわゆる壁面にコンクリート、もしくは隣接した境界には設けるということになっています。","id":"exchange-075"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"葬斎場と隣との間に、２ｍから４ｍという基準をつくったということでご説明を受けたんですけれども、１ｍというのは本当にわずかだと思うんですね。説明会の開催というところで、この規則で定める住民を広げた範囲というのは、どの程度までを考えられているのかも聞かせてほしいと求めました。","respondent":"工藤品川区保健所生活衛生課長","answer":"その中から１ｍということでセットバック、そういった意味では、今の現状ではしっかりとした対策がとれると私のほうは思っております。周辺３０ｍ以上の方に関しまして説明会を義務づけ、協議があればそれに応じまして、誠実に対応するという部分を入れているところです。","id":"exchange-076"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"住民が３０ｍということで拡大していただいたのはいいと思うんですけれども、これは要望で、それはぜひ広げていただけるようにご検討いただきたいと要望させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"鶴委員","kind":"質問","question":"第３条の１、２、３号、それぞれ経営主体が明示されておりまして、地方公共団体、宗教法人、公益社団法人及び公益財団法人とあります。そこまではどうかわかりませんけれども、お墓の基数ないし区画数でもいいんですけれども、そういうのがわかれば教えてほしいと求めました。","respondent":"工藤品川区保健所生活衛生課長","answer":"現在、墓地経営にあたっている主体というものは、１１７の法人が区内で墓地をやっているです。納骨堂が１３カ所あるわけなんですけれども、こちらの合計が１万９,２００というのが、納骨の区画で私どもが把握しています。","id":"exchange-078"},{"speaker":"鶴委員","kind":"質問","question":"今、１１７法人とお答えいただきましたけれども、これはおそらく全部まとめてという感じだと思うんですが、宗教法人と、それから３号で言うところの公益社団法人、公益財団法人、もし別がわかればそれぞれ説明を求めました。","respondent":"工藤品川区保健所生活衛生課長","answer":"いずれの法人もこちらの２号に該当している宗教法人法に定められる宗教法人ということで、３号該当というのは区内にはございません。","id":"exchange-079"}]},{"id":"topic-07","title":"平成２４年請願第１号、「こころの健康を守り推進する基本法（仮称）」の法制化を求める意見書の提出に関する請願","agenda":"平成２４年請願第１号、「こころの健康を守り推進する基本法（仮称）」の法制化を求める意見書の提出に関する請願","exchanges":[{"speaker":"石田（秀）委員","kind":"意見","question":"だから、意見書を上げることも含めて、我々は採択でいきたいと。もう結論みたいな形ですけれども、６会派みんな署名しているので、我々も協力をしていけるところはしっかり協力をしていきたいと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-080"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"充実させることが早急に求められていると思いますので、すでに都内で意見書を出されているところがどれくらいあるのか、把握されていたらお聞かせほしいと求めました。","respondent":"福島品川区保健所荏原保健センター所長","answer":"平成２３年１２月末で１４の地方議会で採択されたと報告されています。東京都内では、杉並区、葛飾区、調布市、三鷹市、立川市、町田市、日の出町の７つの地方議会で意見書が採択されたとのことです。","id":"exchange-081"},{"speaker":"若林委員","kind":"意見","question":"昨年の１２月１日にも国会のほうで、今、力強くスクラムを組んでやっているところです。品川区議会においても、ぜひ皆様のお役に立てるような意見書をしっかりと出していくべきだろうと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-082"},{"speaker":"石田（秀）委員","kind":"意見","question":"結論を今日出してほしいと思います。しっかり意見書をつけて、我々も行っていくということでお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-083"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"今日、結論を出すということで、採択で、そしてぜひ意見書を出すということでお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-084"}]},{"id":"topic-08","title":"平成２４年請願第２号、理容所及び美容所の衛生水準向上のための条例策定についての請願","agenda":"平成２４年請願第２号、理容所及び美容所の衛生水準向上のための条例策定についての請願","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"１つだけ先にお聞きしたいので教えてください。そこら辺の連携は今、どういうふうにしていらっしゃるのか、そこだけ説明を求めました。","respondent":"工藤品川区保健所生活衛生課長","answer":"理容所の方に関する管理的な部分をどうされているかですけれども、自主管理、自主点検の勧めということで、組合を通じまして、いわゆる自主管理点検表というものを平成１５年度からお願いしています。","id":"exchange-085"},{"speaker":"石田（秀）委員","kind":"質問","question":"それはわかっているんですが、区として２年に１回行かれると言っていましたよね。そこら辺のお互いにやってきたものの精査とか連携というのは、どういうふうにされているんか尋ねました。","respondent":"工藤品川区保健所生活衛生課長","answer":"私どもも点検立ち入りの場面で、自主管理点検表という部分に沿って、十分な衛生措置等がされているかという部分を、この点検表に基づいて、私どものほうも点検項目として一つずつ確認させていただいているというのが現状です。","id":"exchange-086"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"指導の権限がどこまでできるのかというのは、ぜひ研究をしていただきたいし、研究をして実現をしていただきたいなと思っています。もう長年やっているわけですから、いい方向に向かってほしいなと思っていますので、それは私の意見として述べておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"},{"speaker":"若林委員","kind":"質問","question":"自主点検されていましたね。これは大体２３０件ぐらい理容所があるということですが、このうち自主点検されている事業者はどのぐらいあるんか尋ねました。","respondent":"工藤品川区保健所生活衛生課長","answer":"私ども平成１５年度に東京都のこの自主点検表という様式をいただきまして、組合のほうにお願いしています。実態としまして、地区によってこの取り組みというのが温度差があると聞いておりまして、ちょっと私どもつかんでいないというのが現状です。","id":"exchange-088"},{"speaker":"若林委員","kind":"確認","question":"２３０のうち組合に入っている方と、そこは自主点検をされていないということで確認というんですか、そこだけちょっと確認を。","respondent":"工藤品川区保健所生活衛生課長","answer":"この自主点検に関しましては、組合を通じて以前、お願いしてあったものですので、組合に未加入の方に関しましては、特に投げかけというのはやっていないというのが現状です。","id":"exchange-089"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"２３０店舗あるうちで、組合に入られているお店というのはどれぐらいあるのか、つかんでいたら教えてほしいと求めました。","respondent":"工藤品川区保健所生活衛生課長","answer":"申しわけございません。今、手元に資料がございませんので、後ほど調べまして回答します。","id":"exchange-090"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"後で質問したら、どれぐらいあってどういうふうにしてくれているという連携も本当にとれていないから起こっているんだと思うんだね。それはもう乗らないわけだけれども、趣旨は非常によくわかるので、自民党は趣旨採択でお願いしたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"若林委員","kind":"提案","question":"先ほどの条例の質疑の中でほぼ言わせていただきました。附帯決議の提案をさせていただきましたけれども、しっかりとこの請願の思いを受けて、趣旨採択といたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-092"},{"speaker":"向委員","kind":"質問・要望","question":"先ほど、条例が４月１日から施行されるということで、それと同じ考えなんですが、衛生面については、我が会派でも、きちんと担保していただきたい。ということで、趣旨採択で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-093"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"共産党としても趣旨採択ということでお願いしたいと思います。品川区に対しては、しっかりとこの面でも、具体的なところでしっかりと上下水道のついた理容所というところで、ぜひよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-094"}]},{"id":"topic-09","title":"平成２４年請願第５号、介護保険料の値上げ中止と国に対し国庫負担引き上げを求める請願","agenda":"平成２４年請願第５号、介護保険料の値上げ中止と国に対し国庫負担引き上げを求める請願","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"基準額から最低でも０.４というところなんですけれども、２万円から５万円もの負担というのは本当に過酷だと思うんですけれども、この住民税非課税者に対しての保険料のとらえ方というのをあらためてお聞かせほしいと求めました。","respondent":"原高齢者福祉課長","answer":"そういった意味では、非課税の方だけを取り出してというところはなかなか難しい状況であろうかと認識しております。こういったところで対応しているというところでございまして、応分の負担をしていただくという考え方のもとにいるところです。","id":"exchange-095"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私はあらためてそういうところを、区のほうもそういう区民の実態を踏まえて検討していただきたいということで、要望させてほしいと求めました。そういう点では、そういうバランスという点についてはどう考えられているかということと、あわせてお聞かせほしいと求めました。","respondent":"原高齢者福祉課長","answer":"そういう中で、どうしても特別養護老人ホームに入らなくてはいけないといった方も実際増えているというところは、認識しています。地域密着型という考え方、品川区の中でどのくらいということで考えていくということで、どこの地域でということは考えてはございません。","id":"exchange-096"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"新しく３カ所できるということになって、さらに平塚橋会館の後につくるというところでの一定の条件というのは、どういうことで考えられているのか。待機者は今までは大体６００名ぐらいだったと思うんですけれども、まだ２月末になっていないですけれども、その数字も教えてほしいと求めました。","respondent":"原高齢者福祉課長","answer":"それから特別養護老人ホームですけれども、昨年９月の入所調整で５９１名というところで数字が出てございまして、現在、２月末です。数値としてはとらえてございませんけれども、例年並みの感触だというところで、今日の段階では把握しています。","id":"exchange-097"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"財政、保険料という点では、特別養護老人ホームよりも特定施設のほうが介護財政をより多く使うという状況になっているわけなんですね。ぜひともつくっていただきたいというのが区民の願いですし、私もそういうふうに思うわけですけれども、そういうところではいかがか尋ねました。","respondent":"原高齢者福祉課長","answer":"それから土地の取得、建設費、こういったところもトータルで判断をしていくということが大変重要かと考えています。高齢者の増加、特別養護老人ホームの入所等々を踏まえつつ、検討してまいるというところで考えているところです。","id":"exchange-098"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今回の平塚橋会館に続く特別養護老人ホームの増設というところで、ぜひ計画を立てて増設をしていただきたいということを強く要望したいと思います。老人保健施設は南大井１カ所だけでいいとは思っていないと、そこら辺のところでは、今後の展望というところも含めてお聞かせほしいと求めました。","respondent":"原高齢者福祉課長","answer":"区のほうでも１カ所をぜひということで、具体化に向けてこれからも進めてまいりたいと考えているところです。","id":"exchange-099"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ずっとそういう答弁のままなんですけれども、具体的に１カ所というのは、まだ全く見通しはないんでしょうか。それともこういう見通しという方向もありつつ進められているという、そこら辺のところをもう一歩踏み込んだご答弁をいただけたらと思うんですが。","respondent":"原高齢者福祉課長","answer":"現在のところで具体化というところで、こういったところがあるんじゃないかというところまでは至ってはございません。方向として、老人保健施設については、必要性というところは区は判断しておりますので、今後もそこに向けて進めていきたいと思っているところです。","id":"exchange-100"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"１カ所必要ということで、この答弁は前からお聞きしているところですけれども、それがなかなか前に進まない。どこをどうして進めていこうと考えているのか。","respondent":"原高齢者福祉課長","answer":"１つは土地というところが現実的な問題として出てまいります。あるいはさまざまな条件の中で、どういったところをとらえていくかといった中で、今のところでは具体的なところは出ていないです。","id":"exchange-101"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"本会議の提案もありましたけれども、なるべく近いうちに具体化をして、ぜひ増設に向けて取り組んでほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-102"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"別に計画をしていくと、本当に土地が買えなかったりするとうそをつくことになってしまうので、やっぱりそれはしっかりと判断をしていただきたい。１番と２番は、相反するものが出ているかなと思いますが、基本的には我々は不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"若林委員","kind":"意見","question":"たしか昨年の９月、同様の請願が出されて、趣旨で採択をさせていただいているということが事実としています。請願の第５号も絡みますけれども、しっかり議論を進めなければいけないという思いですので、この件については不採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-104"},{"speaker":"向委員","kind":"意見","question":"特別養護老人ホームについても、しかるべきときにしかるべきタイミングで増設もきちんと前向きに考えてくださっているという立場もきちんと理解しておりますので、今回は不採択ということで表明しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-105"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"平塚橋会館までつくるという方向を出されたことは評価するものですけれども、さらなる増設に向けて取り組みを進めていただきたい。それから老人保健施設もさらに早急な具体化を望みたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-106"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"先ほども言いましたように、ずっと区も市長会でも言っているということなんですけれども、私は区のほうからも強力にこれは求めていただきたい。そして、この欠陥の介護保険料の設定そのものを変えていくことが必要だと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-107"}]},{"id":"topic-10","title":"平成２４年陳情第２号 品川区国民健康保険被保険者証の裏面に臓器提供の意思表示欄の掲載を外すことを求める陳情","agenda":"平成２４年陳情第２号 品川区国民健康保険被保険者証の裏面に臓器提供の意思表示欄の掲載を外すことを求める陳情","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"参議院の審議もわずか８時間で、国民が本当にそういうものに対しての認識を高めていくという作業がすごく大事な問題じゃないかなと思うんですね。品川区として臓器移植の問題で、啓発や知識の普及というところを、どんな形でされているのかもお聞かせほしいと求めました。","respondent":"本城国保医療年金課長","answer":"これから４月以降についても、いずれにしても保険証の発行との関係で、趣旨をなるべくわかりやすいようにということで努めているところです。","id":"exchange-108"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういう点では、家族の死、一人一人がそういう場面を考えるという機会をつくっていくということが大事だなという思いがしています。そういう自治体というのは、つかんでいたら教えてほしいと求めました。","respondent":"本城国保医療年金課長","answer":"別な形で対応している自治体もあるとは伺っていますが、どれぐらいの割合であるとか、そのあたりまでは把握してはおりません。与えられた役割について、国の方針に示されているところに則して対応するのが、国の基準どおりの対応を現在ではさせていただいているところです。","id":"exchange-109"},{"speaker":"石田（秀）委員","kind":"質問","question":"ちょっと教えてください。実際にはドナーが移植の際に痛がる生体反応を示す場合も多いと書いてあるんだけれども、こういうことってどういう意味なのか、わかれば教えてほしい。","respondent":"本城国保医療年金課長","answer":"それに関連して若干趣旨説明があったようで、その趣旨説明の中では、提案説明の中ではありますが。","id":"exchange-110"},{"speaker":"石田（秀）委員","kind":"意見","question":"聞かれたときには、そういうことではないということで、そういうことですね。そういうふうに思っておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-111"},{"speaker":"石田（秀）委員","kind":"質問","question":"別に私はそれを、今、免許証もそういうふうに変わったけれども、強制をしているわけではないと思っています。やっぱり我々はそれの中の意思表示もしていってもいいのではないかと私は思っておりますので、この件については不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-112"},{"speaker":"若林委員","kind":"意見","question":"逆に、この陳情者がおっしゃっているような、まだまだ国民の理解等々が確かに進んでいない実態もあるんだと思います。別な形でというのは、今の段階では私は違うと思いますので、不採択ということで結構かと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-113"},{"speaker":"向委員","kind":"質問・要望","question":"結論を先に申し上げると不採択です。できるだけ啓発活動をきちんとしていただきたいということで、引き続き品川区の国民健康保険証ということでもあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-114"},{"speaker":"鈴木（博）委員","kind":"意見","question":"例えば今、それはすばらしいことで、むしろほかのところでもどんどんそういう目につく機会を広げていっていただければいいと思います。ということで、不採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-115"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"私は採択でお願いしたいと思います。そしてそのときにしっかりと家族とも話し合い、そして決めていくという形が望ましいのではないかと思いますので、採択でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-116"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/594819?Template=document&Id=3316#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":109223,"voices":404}},{"id":"h24-20120227-8","meetingId":"h24-cm02","date":"2012年2月27日","dateIso":"2012-02-27","committee":"建設委員会","time":"午前１０時００分～午後２時２２分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を71件整理しています。","topics":[{"id":"topic-01","title":"上、審査の順序を変更いたしまして、(2)から(5)までを先に行い、議案審査の最後に本件を行いますので、よろしくお願いいたします。 それでは…","agenda":"上、審査の順序を変更いたしまして、(2)から(5)までを先に行い、議案審査の最後に本件を行いますので、よろしくお願いいたします。 それでは…","exchanges":[{"speaker":"井上委員","kind":"質問","question":"そんなに東京都とかけ離れたものではないとしても、品川区独自で設定をするということが可能になるのか、どのくらいまでそういった範囲が広がるのかということはどうなんか尋ねました。","respondent":"藤田水とみどりの課長","answer":"同意は必要はないというものの、その範囲をやはり大きく変えてしまうような形のものはなかなか難しいのかなと思ってあります。あくまでも同意の必要はありませんけれども、その範囲の中で、各自独自の施策を可能な限り協議をしていくということになろうかと思います。","id":"exchange-001"},{"speaker":"井上委員","kind":"質問","question":"もう少し力強く品川区のものが出せるというふうに思っているのか、それとも協議という名前があるけれども、そんなに大した変化は望めないという判断なんか尋ねました。","respondent":"藤田水とみどりの課長、岩田都市環境事業部長","answer":"品川区の独自の形で進められるというような形に現状ではなっておりますので、品川区としては重点地区をこれからもさらに追加していくなど、さまざまな施策を打ちたいと考えております。現在の中では、こういったものについては一定の権限を付与していこうという考えだったわけですけれども、法が想定していないんですね。","id":"exchange-002"},{"speaker":"井上委員","kind":"質問","question":"２つ目の工作物の「新築」と「新設」なんですけれども、何か課題が見えてきたから変えるんだろうと思うんですけれども、そこのところはどういうふうか尋ねました。","respondent":"藤田水とみどりの課長","answer":"それに単純に合わせたほうが、今後の運用の中でやりやすいということで、合わせる形に変更したものです。","id":"exchange-003"},{"speaker":"井上委員","kind":"質問","question":"では、この言葉はただ言葉のことだけで、どこかに変わった意味合いを持つということではないということでいいんか尋ねました。","respondent":"藤田水とみどりの課長","answer":"委員のお話のとおりです。","id":"exchange-004"},{"speaker":"武内委員","kind":"質問","question":"お話を伺って、その辺のところで実務上少しスピーディーにできる、もしくはあまり時間をかけずできるという点はあるのかどうか。","respondent":"藤田水とみどりの課長","answer":"ちょっと説明の仕方が悪くて申しわけございません。品川区の場合は既に景観行政団体になっておりますので、この手続きはこれから区が行うものではないので、特にその部分については変更はございません。","id":"exchange-005"},{"speaker":"武内委員","kind":"質問","question":"ほかの自治体で、今回のこの法律の地域主権一括法の改定で、これを機につくっていないところはつくりなさいと。そのときは、協議はするけれども同意は得なくていいということになったということか尋ねました。","respondent":"藤田水とみどりの課長","answer":"委員お話のとおりで、これをきっかけに景観行政がさらに進んでいくものと考えています。","id":"exchange-006"},{"speaker":"中塚副委員長","kind":"質問","question":"これを機会に区としてはどういうことを考えているのか、そこの今後の見通しをどんなふうに考えていらっしゃるのか、そこを伺いたいと思います。そういう中身の改正をも含んでいるのか、いないのか、そこを改めて伺いたいと思います。","respondent":"岩田都市環境事業部長","answer":"その役目をこれから担っていくのが、いわゆる都道府県、こういう考えになっております。こういったものについては従来の法律も条例も同じ手続きがそのまま残っておりますので、計画の内容については変わりがないです。","id":"exchange-007"},{"speaker":"中塚副委員長","kind":"質問","question":"そこについてもう少し伺いたいのは、内容については変わりはないと。この点をどうとらえていらっしゃるのか、伺いたいと思います。","respondent":"藤田水とみどりの課長、岩田都市環境事業部長","answer":"実際に東京都の中で景観行政団体に私どもがなったわけですけれども、この同意をいただくのに２年近くやはりかかっております。区がしっかり物を考えて、区市町村がしっかり考えることを前提にすれば… そういう手続きでもって国に救済を求めるというのが、地方自治法の法体系になっているわけです。","id":"exchange-008"},{"speaker":"中塚副委員長","kind":"意見","question":"やはり品川区自身の主体性であったり独自性であったりが、今後より厳しく問われていくのだなと思うんです。ちょっと別の話にはなりますけれども、今後景観についてもどういうスタンスをつくっていくのか、ここはやはり厳しく見ていきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"中塚副委員長","kind":"意見","question":"賛成ですけれども、この法律の流れには危険性もあります。品川区の景観に対する考え方も住民の暮らしや目線に立った景観に切り替えるべきだと思いますので、その点は厳しく見ていきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"}]},{"id":"topic-02","title":"第３６号議案 品川区立区民住宅条例の一部を改正する条例","agenda":"第３６号議案 品川区立区民住宅条例の一部を改正する条例","exchanges":[{"speaker":"武内委員","kind":"質問","question":"３番に書いてあるようなことで、していないというよりも、変えることは可能となったのかどうかというのはどうか尋ねました。","respondent":"柏原住宅担当課長","answer":"例えば廃止であるだとか用途を変更するであるとか、供給計画の変更というときに、供給計画の変更について。ただ、品川区で判断ということがありますので、その部分についてはある程度自由度が出てきたのではないかと考えております。","id":"exchange-011"},{"speaker":"武内委員","kind":"質問","question":"そうすると、今までいろいろなところで出ていた借り上げ型の中でも、いろいろなかなか入居しないようなところとかの更新、するかしないかという話も、今までは一応東京都にお伺いを立てて承認をもらわなくてはいけなかったと、それが品川区の判断でできるようになったという理解でいいんか尋ねました。","respondent":"柏原住宅担当課長","answer":"委員がおっしゃるとおりでございまして、今まで東京都に必ずこの供給計画に係る部分については認定、変更等々お願いをしていたんですが、その部分が全くなくなりますので、区の判断でそちらのほうはできるです。","id":"exchange-012"},{"speaker":"中塚副委員長","kind":"質問","question":"それが今回区に来るということでどういう変更となるのか、その理念というのか、そこの意味合いをもう一度お伺いしたいと思います。つまり区で定められる供給計画というのはどういう内容なのか、どういうことが区に来るのか、そこをもう一度ご説明ください。","respondent":"柏原住宅担当課長","answer":"用途廃止とか一部用途変更、２戸を廃止しようとか、個別の廃止もできるんですね。区の認定でその供給計画を変更できるというところもありますので、法律の範囲内ではありますけれども、自由度が増えたのではないかと考えています。","id":"exchange-013"},{"speaker":"中塚副委員長","kind":"質問","question":"品川区としては今時点で何かイメージしているものがあるのか、どういうことを考えていらっしゃるのか、それを伺いたいと思うんです。何かこの変更に伴って、今、考えていることがあるのかどうか伺いたいと思います。","respondent":"柏原住宅担当課長","answer":"区民住宅等々の問題につきましては、以前にもこの場でいろいろ議論をしていただいているところです。その区民住宅の今までの課題といったところを、どういった部分が解決できるかどうかについては、今後研究していきたいと考えています。","id":"exchange-014"}]},{"id":"topic-03","title":"第３７号議案 品川区建築審査会条例の一部を改正する条例","agenda":"第３７号議案 品川区建築審査会条例の一部を改正する条例","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"いたずらにこれは何か変更だけを求めたに過ぎないと思うんですけれども、そこのところ、どのようなスタンスでやっていかれるのか。まちづくり事業部においては、この建設委員会にかかわる所管においては、そこのところをどのように考えていらっしゃるのか伺いたい。","respondent":"山崎マスタープラン担当課長","answer":"文書、それから第７条につきましては審査会に専門調査員というのがありまして、そちらのほうが「置くことができる」というできる規定です。今回、この際に整理をさせていただいたということですので、ご理解のほどよろしくお願いいたします。","id":"exchange-015"},{"speaker":"中塚副委員長","kind":"質問","question":"これまで防災まちづくり事業部に品川区建築審査会があったわけで、それを今回、組織改正によって都市環境事業部になるわけですけれども、そこの趣旨と理由をご説明いただけますか尋ねました。","respondent":"松代都市計画課長","answer":"この都市計画課は、今回の４月１日からの組織改正に当たりましては、都市環境事業部という部名に変更することになりました。そういったことで、業務自体は都市計画課で引き続き行うものということで、部名が変わるということで、今日、お示しするものです。","id":"exchange-016"}]},{"id":"topic-04","title":"第３８号議案 品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","agenda":"第３８号議案 品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","exchanges":[{"speaker":"中塚副委員長","kind":"質問・要望","question":"確かに都市計画決定を受けたからというわけだけれども、そもそもなぜこの変更なのかというところが冒頭なかったので、そこを伺いたいと思うんです。現状の建物の高さがどうで、それをなぜ５０ｍに制限をしたのか、あわせてご説明ほしいと求めました。","respondent":"中村建築課長、三宅都市開発課長","answer":"今の１点目、まずこちらの改正の理由のところをもう少し詳しく申し上げます。今、品川区の市街地整備基本方針の中で、そして都市の活性化を図るという都市計画としての目的のために改正したものあります。なぜ５０ｍの高さ制限を決めているかというところですが、用途地域を変更して容積率を１００％アップしておりますけれども、５０ｍです。","id":"exchange-017"},{"speaker":"中塚副委員長","kind":"質問","question":"１つ伺いたいのは、なぜこの１企業の要請だけに品川区がこたえるのか、一方で逆に５０ｍに制限をしているわけですよね。その兼ね合いの理由はどこにあるのか、そこを伺いたいと思います。","respondent":"三宅都市開発課長","answer":"ちょっと説明が不足しておりまして、地区の整備方針を決めているその全体の１７haの中の、設定しております。","id":"exchange-018"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"その１７haの中の方々から、またさらにその周辺からどういうご意見・ご要望が出されて、そこの内容を伺いたいと思います。にもかかわらず、そこを制限をかけているわけですから、この理由をしっかりとご説明ほしいと求めました。","respondent":"三宅都市開発課長","answer":"研究棟ですので、例えばものすごく高いものが効率がいいかというと、決してそういうことではございませんで、やはり地上になるべく近いところで研究施設があったほうが、要するに基準階が広いほうがいいという考えですので、それに合った形の高さで設定しております。","id":"exchange-019"},{"speaker":"武内委員","kind":"質問","question":"Ａ地区・Ｂ地区以外の南側のところも一応地区内に入っているんですか。ここは何かこういう制限とか緩和とか、何かあるのか、それともないのか。","respondent":"三宅都市開発課長","answer":"こちら、その他の地区として出ているんですが、ここは条例の範囲外でございまして、規制はございません。地区計画のほうで全体の大まかな方向だけ決めているです。","id":"exchange-020"},{"speaker":"中塚副委員長","kind":"質問","question":"周辺の再開発の基準を見ますと、その中でこの５０ｍの制限というのは非常に低いですから、そういう意味では理解したいなと思います。だったら、ほかの開発についてもしっかり高さを制限すべきだと意見を添えたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]},{"id":"topic-05","title":"議案第１８号 品川区手数料条例の一部を改正する条例","agenda":"議案第１８号 品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"井上委員","kind":"質問","question":"東京都だと２３区横並びでということがあったと思うんですが、それとも全然そういうことではないということなのか、どっちか尋ねました。","respondent":"柏原住宅担当課長","answer":"他区の状況を見ますといろいろ考えているところもありますので、それから効率化等々を考えて、場合によっては手数料の変更というのも今後は出てくる可能性もあると考えております。","id":"exchange-022"},{"speaker":"武内委員","kind":"質問","question":"最初の外国人登録関係のほうで、今度は通常の住民基本台帳のほうに外国人の方たちも一緒に組み入れられるということになるんですか。ずっとこの流れが続いて困ってしまうなんていう部分の中で、今回はそれほどではないのか、どのあたりなのか。","respondent":"梶戸籍住民課長、柏原住宅担当課長","answer":"それをもとに、また変更等といったものを、手続き、いろいろ調査をいたしまして、７月９日からこちらのほうを住民票に移していくです。外国人の皆様方には１月から広報、あるいは英字の広報等を通じてお知らせをしてまいりますし… ございませんので、今すぐ何かというのはないんですけれども、そういったところで事務は増えることが見込まれるということになります。","id":"exchange-023"},{"speaker":"武内委員","kind":"質問","question":"今のはいわゆる財調算定で上乗せされるという考えでいいんですか。まだ決定じゃないの。","respondent":"岩田都市環境事業部長","answer":"やはりいろいろ難しいんですね。今回のは２点の証明書を発行する手数料事務のみのことを、自治事務として既に今でも、もし物件が出てくれば区でやらなければいけないというものです。","id":"exchange-024"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"それともいわゆる在留カード、特別永住者証明書の交付をする人に変更があるのか、ちょっとそこをご説明ほしいと求めました。その基準というのも区の考え一つで変わるものなのか、いやいや別に定められているものなのか、そこをちょっとご説明いただけますか尋ねました。","respondent":"梶戸籍住民課長、柏原住宅担当課長","answer":"外国人の登録原票の写し等の交付手数料の文言がありますので、そちらの３本が今後７月９日からなくなりますので、それの削除という形です。原則として、適法に在留しています外国人の方につきましては、今までの対処と変わらないです。 今まで、平成１４年にこの法律ができたときに、都に書類を流すという手続きをしていたんです。ただし、これもやはり法律のほうで基準というのはすべて決まっておりますので、その事務が一定程度こちらのほうに流れてくるという内容です。","id":"exchange-025"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"マンションのほうの確認だけですけれども、区のほうに事務は来るけれども、その基準が変更がないというか、できないといいますか、今のそこだけ、もう一度ご説明ほしいと求めました。","respondent":"柏原住宅担当課長","answer":"委員がおっしゃるとおりでございまして、特に区のほうで何か事務の判断とかいうことになると、法律に決まった内容で判断していくということになります。","id":"exchange-026"}]},{"id":"topic-06","title":"専決処分の報告について（報告第２号）","agenda":"専決処分の報告について（報告第２号）","exchanges":[{"speaker":"武内委員","kind":"質問","question":"例えば交通事故もそうでしょうけれども、こういうのが起きたときに、一応どういうふうな徹底をするのか。そういう方たちにも徹底とかはできるものなのか、その辺の徹底はどうなっているんか尋ねました。","respondent":"太田品川区清掃事務所長","answer":"今回のような飛散事故にかかわらず、事故全般については、当然その日に当日の職員を呼んで状況を聞いた上で注意をすると。毎朝朝礼を実施していますので、朝礼の中でこういう事故があったということで、十分気をつけるようにということでの注意喚起をしています。","id":"exchange-027"},{"speaker":"武内委員","kind":"質問","question":"車両持ち込みで来る方たち、そういう方たちにも同じように徹底できるということでいいんか尋ねました。","respondent":"太田品川区清掃事務所長","answer":"委員がご指摘の部分は傭上車両、運転手つきの清掃車の部分だと思います。あるいは傭上会社、当該運転手等を含めて、注意をするということで徹底をしています。","id":"exchange-028"},{"speaker":"中塚副委員長","kind":"質問","question":"周りに注意する、それは当然のことですけれども、あわせてやはりこういうこともごみの出し方ですよね。今回これで済みましたけれども、車ごと火がついてしまうこともたまに報告されているわけですから、ご説明いただけますか尋ねました。","respondent":"太田品川区清掃事務所長","answer":"ご指摘の部分は、今、冬ですので、簡易コンロとかいいますか、そういった分のガス缶の部分が出てまいります。排出のときに別袋でお出しいただきたいという形で、この間、区民の皆さんにはお願いをしています。","id":"exchange-029"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"なかなか、正直言うとあまり捨てる機会がないですから、どう捨てていいのかというのもよくわからないというのが正直なところなんですよね。ただ、引き続きどのように安全に捨てる方法があるのか、そういう周知もあわせて進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]},{"id":"topic-07","title":"平成２３年度目黒川水質改善対策検討のまとめ","agenda":"平成２３年度目黒川水質改善対策検討のまとめ","exchanges":[{"speaker":"中塚副委員長","kind":"質問・要望","question":"それ自体は、今後どういうことになっていくのか伺いたいと思います。東京都の要請の中で「抜本的な水質改善への取り組みを進めることを約束した」とあって、どういう中身なのか、ちょっとご説明ほしいと求めました。","respondent":"藤田水とみどりの課長","answer":"これは対策検討のまとめということでございまして、短期的・長期的な形のことを、これから目黒川についてはやっていくべきと考えています。世田谷区共同していろいろ調査を進め、その後のここに書いてあります、短期・長期に向けた対策を実施していきたいと考えておるものです。","id":"exchange-031"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"近隣の方々を含め長年の期待と強い要望で、いわばこの間、品川区は主体的に何とかできないのかと取り組んできたと思うんです。そこのところで、東京都がどういうことと方法を考えているのか、それから今後の見通しも含めてご説明いただけますか尋ねました。","respondent":"岩田都市環境事業部長","answer":"それから区議会、行政が一体となった目黒川浄化３区連合という行政体をつくって、東京都と長年にわたってこの浄化についてはやってまいりました。","id":"exchange-032"},{"speaker":"高橋委員","kind":"質問","question":"その明言の話なんですけれども、ちょっと勉強不足で申しわけないんですが、平成２４年度の東京都の予算の中に、今、明言したとありますけれども、具体的に何かわかる形で公表されているのか尋ねました。","respondent":"藤田水とみどりの課長","answer":"おそらく目黒川としてやるというような形ではなく、全体のパイの中で目黒川について対策をとっていきたいということで、東京都のほうから話を聞いているところです。","id":"exchange-033"},{"speaker":"高橋委員","kind":"質問","question":"全体のパイというのは、今、部長がおっしゃったような川全体のということで、あと平成２４年度に数字的に何かというのはあるんか尋ねました。","respondent":"藤田水とみどりの課長","answer":"全体のパイというのは、東京都全体の中でしゅんせつ作業はずっとやっておりますので、その中でやっていくということで聞いてあります。そういう面で言うと、目黒川用ということで、平成２４年度の中に明確に記載があるというものではないと考えております。","id":"exchange-034"},{"speaker":"井上委員","kind":"質問・要望","question":"これはどういうイメージなのか、ちょっとこれ、監視というところだけよくわからないんです。何を住民に求めているのか尋ねました。","respondent":"藤田水とみどりの課長","answer":"立会川については地域の方々と一緒に清掃活動をしたり、川の様子を見ていただいたり、勝島運河の様子も見ていただいたりしております。そういった機会も使いながら、地域の方々と目黒川を見守っていくためのことを進めていきたいと考えています。","id":"exchange-035"},{"speaker":"井上委員","kind":"質問","question":"１つはそういう案だということなんですけれども、そういうところの研究もやはりしていくべきだと思うんですが、そういうところはどんなふうに考えているのか尋ねました。","respondent":"岩田都市環境事業部長","answer":"数年前に五反田を中心に、目黒川を考える地域の方たちが出てまいりまして、ついにＮＰＯがつくられました。地域の方たちでこういう動きが出てまいりましたので、品川区と区議会と、これからやってみたいということです。","id":"exchange-036"},{"speaker":"井上委員","kind":"質問・要望","question":"これは（案）ですから、この河川監視という表現よりは、もう少し住民協力による何かというようなことにまとめていただいたほうがいいのではないかと。やろうとしていることは同じことだと思うんですけれども、少しそういうところに配慮していただければいいなと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]},{"id":"topic-08","title":"温暖化対策実行計画の実績報告及び品川区環境計画等の改定","agenda":"温暖化対策実行計画の実績報告及び品川区環境計画等の改定","exchanges":[{"speaker":"武内委員","kind":"質問・要望","question":"その辺の理由が何かあれば教えていただきたいのと、平成２３年度は省エネ、節電を大分やられたのでいいでしょう。ここも踏まえて６％ということにしているので、区がやはり率先してやらなくてはいけない中で６％というのは、その辺を教えてもらいたいと思います。","respondent":"野呂瀬環境課長","answer":"大体１２月ごろにご報告しているというのが、１つは庁内検討委員会というのに諮って、やはり来年度の見通しをある程度立ててからとなります。２０２０年度までに２５％という、やはり事業者とか区民の方と一緒になって削減に努めていくという方向性に変わりはございません。","id":"exchange-038"},{"speaker":"武内委員","kind":"意見","question":"これから平成２４年度中に策定することになるわけですけれども、この２５％という大きな目標、どういうふうに今の段階で考えているのかとの意見を述べました。","respondent":"野呂瀬環境課長","answer":"それとともに、これはいわゆる今後の国の動向等とか、これも当然踏まえて視野に入れながら計画を策定していくように考えているところです。","id":"exchange-039"},{"speaker":"武内委員","kind":"質問","question":"決まっている２５％という地域推進計画の目標設定を下げるということもあり得るという判断なのか、今の段階でその辺の区の実際のところはどうなんだという、そこら辺をちょっと説明を求めました。","respondent":"岩田都市環境事業部長","answer":"これはもう、それは変える考えは一切ございません。あくまで２５％をきちんと見据えた上で、今年１年間かけて計画する中では、そこら辺も見ながら数値目標というのは定めていきたいと考えております。","id":"exchange-040"},{"speaker":"井上委員","kind":"質問","question":"大きなところの全体の計画があって、それを受けて地域推進計画、区も事業者も区民も一緒に地球温暖化防止対策をしましょう。区の職員が中心になってつくっていくと、その辺はどういうふうにこの計画策定についての取り組み方をしていこうとしているのか、説明を求めました。","respondent":"野呂瀬環境課長","answer":"それと町会とか区の商店街連合会とか、それから区民の皆様からも公募を募って、その中で１年間かけて策定していく。これにつきましてはいわゆる外部委員等ではなくて、中で決めていくと、こういう計画が分かれているところです。","id":"exchange-041"},{"speaker":"井上委員","kind":"質問","question":"品川区環境計画と品川区温暖化防止対策実行計画を一括して改定し、というところが同時並行で同じようにつくっていって、内容だけを整合性を持たせるというイメージでいいんか尋ねました。","respondent":"野呂瀬環境課長","answer":"品川区環境計画という上位計画に沿った温暖化防止の趣旨があって、それに基づいて品川区役所として、１事業者としてどういう形で進んでいくかという品川区温暖化防止対策実行計画を一緒につくっていくということです。","id":"exchange-042"},{"speaker":"井上委員","kind":"質問","question":"その辺がどういうふうに動いているか、そこはどういうふうに示していくものになっているのか、説明を求めました。","respondent":"野呂瀬環境課長","answer":"今、これから委員を募集しまして、それから顔合わせというのを新年度の５月、６月ぐらいを予定しています。そのような形で計画を進めていくと考えています。","id":"exchange-043"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"その中で、この１m2当たりを出す理由というのは何なのかなというのをあわせて伺いたいと思います。ここにかかわるのかどうかわからない点ですけれども、ちょっとそこがよくわからないので、あわせてご説明いただきたい。","respondent":"岩田都市環境事業部長、野呂瀬環境課長","answer":"とりあえず１２月までの大規模受電施設の速報値が出ましたので、それが２２％ぐらい減っていますので、こう説明を差し上げました。これは引き続き努力してまいりますので、その中でどこまで数値を下げられるか… ただ、全体的な総量から比べると、電気、これは６,０００万Kwhですので、今の時点ではさほど影響はない。ただ、今後そういうのが増えてくれば、当然電気使用量に対してもエネルギー使用量が省エネに向かうということになります。","id":"exchange-044"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"これというのは、使用量そのものが増えたということになるのではないでしょうか。３つ目は自然エネルギーのことですけれども、やはりＣＯ２換算の排出を減らすために、いかがか尋ねました。","respondent":"岩田都市環境事業部長、野呂瀬環境課長","answer":"ＣＯ２でそれぞれ比較しましたのが、そこら辺をちょっとお間違いのないように見ていただきたいと思います。今後これを説明していかなければいけませんので、見方を変えるとこういうふうに見えますよというものを… 目標を設定するですけれども、昨年の１月から環境情報システムで、各施設のエネルギー使用量の見える化というのに努めているところです。","id":"exchange-045"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"目標の設定そのものは出るものを減らそうというわけですから、そこを見るとやはり増えている。この延長の理由がちょっとまだよくわからなかったので伺いたいんですけれども、それとも違うのか、もう一度ご説明いただけますか。","respondent":"野呂瀬環境課長","answer":"後段のほうからご回答しますけれども、１０年たちます品川区環境計画、上位計画が改定されます。その結果、電力事業者の排出係数が上がったことによって、結果的に排出量が上がったとしても、区役所として、節電、省エネに努めていくです。","id":"exchange-046"}]},{"id":"topic-09","title":"休憩前に引き続きまして、報告事項を行います。 (5)地籍調査事業","agenda":"休憩前に引き続きまして、報告事項を行います。 (5)地籍調査事業","exchanges":[{"speaker":"武内委員","kind":"質問","question":"教えてもらいたいんですけれども、それとも平成２３年度、そこだけの影響なのか。その大もとが狂うことで全部影響を、みたいな話だったので、その辺をちょっと説明を求めました。","respondent":"井浦土木管理課長","answer":"この震災に伴う地殻変動につきましては、大規模で広範囲に及んでおりますため、局部的な狭い範囲のものについては影響はないと考えております。品川区内の広範囲にわたって公共測量を実施してまいりましたので、補正の必要があるのか、今後協議してまいりたいと考えています。","id":"exchange-047"},{"speaker":"武内委員","kind":"質問","question":"そうしますと、この裏のほうにある５６カ所の部分の補正なのか、３５７カ所も含めてなのか、それで、いずれにしても何か手直しが必要だという判断になりそうだということなんか尋ねました。","respondent":"井浦土木管理課長","answer":"委員ご指摘のとおりでございまして、５６カ所につきましては、平成２３年度中にすべて改定を実施してまいります。３５７カ所につきましても、計算上の改定で済むかにつきましては、専門的な見地から法令にのっとりまして適切に処理してまいたいと考えています。","id":"exchange-048"},{"speaker":"松澤委員","kind":"質問","question":"同じようなことなんですけれども、２７cmずれたということは、例えば私の家の敷地だったらちょうど２７cmずれているという判断なんか尋ねました。","respondent":"井浦土木管理課長、岩田都市環境事業部長","answer":"それから２３区でそれ以外のエリアについては、東京都の最大の移動値は２８cmであるというように国土地理院からは説明会で報告を受けてあります。品川区につきまして、どのような規模で動いたのかという点につきましては… この２級基準点、３級基準点を今回私どものほうで測量し直しまして、全体に平行移動したのかもしれません。","id":"exchange-049"},{"speaker":"松澤委員","kind":"質問","question":"これはずっと１年のおくれだけで、これが広がるということはないんでしょうか。大丈夫か尋ねました。","respondent":"井浦土木管理課長","answer":"これは、国土交通省に提出しております平成３１年度までの計画面積がありますので、１年半程度おくれまして、その後は平成３１年以降の計画の中に盛り込まれると考えています。","id":"exchange-050"},{"speaker":"中塚副委員長","kind":"確認","question":"あらかじめ上と下で確認したものが広がったのか狭まったのか、調べてみないとわかりませんけれども、数ミリ単位という感じなんでしょうか。結果、土地が小さくなったり大きくなったりするときにはどういうことになっていくのか、そこをご説明いただきますか尋ねました。","respondent":"井浦土木管理課長","answer":"測量の範囲が一様に同じ方向で移動していると考えられますので、隣り合う座標間の整合はとれておりますので、そのまま使って差し支えないと考えています。","id":"exchange-051"},{"speaker":"中塚副委員長","kind":"質問","question":"そうすると、そういう場合というのはどういうふうにしていくんでしょうか。これから測定して国の判断というのもまだあるんですけれども、ちょっとそこをご説明いただけるか尋ねました。","respondent":"岩田都市環境事業部長","answer":"南北方向に５００Km、おそらくかなり離れた東京は全体的におそらく横にちょっとずれただけだろうというのが今の国の見解です。ただ、これは一遍全部調査してみないと、多少のゆがみが出ている可能性はゼロではありませんので、これらの結果を見てから判断したいということです。","id":"exchange-052"}]},{"id":"topic-10","title":"次、(6)下神明駅区営自転車等駐車場の収容台数変更","agenda":"次、(6)下神明駅区営自転車等駐車場の収容台数変更","exchanges":[{"speaker":"中塚副委員長","kind":"質問","question":"初めからこの仮道路ができると、それとも東京都のほうが示してきた図面でこうなってしまったのか、そこの関係をちょっと伺いたいと思います。利用者にとっては不便なことですから、その経過を伺いたいのと、伺いたいと思います。","respondent":"藤木交通安全担当課長","answer":"経過ですけれども、東京都のほうから私どものほうに一部を削ってもらいたいという要請が来たのが、今年の１月です。なお、利用率につきましては先ほどご説明申し上げたとおりですので、特に大きな支障はないものと現在考えおります。","id":"exchange-053"},{"speaker":"中塚副委員長","kind":"質問","question":"どうもそこが腑に落ちないんですよね。どうも何か後からの計画に確かに削られてしまったというのが、その経過、そういうのはどうお考えなんか尋ねました。","respondent":"藤木交通安全担当課長","answer":"あくまでここは東京都の道路予定区域の上に品川区のほうで駐輪場を設置させてもらっているという立場ですので。先ほども申し上げましたように警察との調整だとかいろいろ入ってくる中で、若干道路の幅員ですとか位置が若干変更になったと聞いております。","id":"exchange-054"},{"speaker":"中塚副委員長","kind":"意見","question":"その辺はどうも腑に落ちないんですけれども。４１台が元に戻るのかということと、何で初めから都の道路の上につくってしまったのということを、最後にとの意見を述べました。","respondent":"松代都市計画課長","answer":"それまでには、下神明駅側とか、今の計画でもなるべく駐輪場にかからないようなことも検討したと聞いてあります。今後協議してまいりますけれども、もともとの機能の駐輪場として我々がお借りして使うということも十分あると考えておるところです。","id":"exchange-055"},{"speaker":"松澤委員","kind":"質問","question":"その辺をちょっとまずは伺って。どうか尋ねました。","respondent":"松代都市計画課長","answer":"ちょっとまだ説明が来ておりませんけれども、最終的には図面等、まだもらっていない状況です。","id":"exchange-056"},{"speaker":"武内委員","kind":"質問・要望","question":"今のに関連して、直接の撤去の話と違いますけれども、この仮道路沿いに、今年の８月か９月に地域センターが先に建ちますよね。今、おっしゃったような通学路との兼ね合い等含めて、安全対策はしっかり東京都のほうに要望していただきたいなということで。","respondent":"松代都市計画課長","answer":"下神明駅周辺というのは、駅乗降客の安全対策、また今回の仮設道路での新たな部分での通行の変更になります。今、お話のとおり、私どもは十分安全対策という観点から東京都と協議をしながら進めてまいりたいと思っているところです。","id":"exchange-057"},{"speaker":"井上委員","kind":"質問","question":"駐輪場の平均利用率２２.６％というところでちょっとお伺いしたいんですけれども、ここを建てて２２.６％を、今、周りでちょっと工事をしているからというようなことなのか、当初計画でその辺のこの利用率の低さというものをどういうふうにとらえているんか尋ねました。","respondent":"藤木交通安全担当課長","answer":"平成２１年から有料化して供用開始しているわけですけれども、そこから利用状況などを推定しまして現在の収容台数を算定したという次第です。実際ふたをあけて供用開始してみましたら、平成２２年度が２５％、別に工事に伴ってというものではないと考えております。","id":"exchange-058"},{"speaker":"井上委員","kind":"質問","question":"それは、今回ここの地域センターとか新しくできる施設でも、その施設の駐輪場もつくるんでしょうけれども、ここはそのままにするのか、２２％とか３０％の利用率では、やはり効率的な運営とは言えないと考えたときに、これからその先をどういうふうに考えていくんか尋ねました。","respondent":"岩田都市環境事業部長","answer":"ここだけではなくて、ああいうところはやはりもう自転車需要が今後見込めないのであれば、こういったものをやはり柔軟に考えていかなくてはいけない。駐輪料金の値下げと、そういうことで、いよいよ踏み切っていく成熟した段階に来たと考えております。","id":"exchange-059"},{"speaker":"井上委員","kind":"質問・要望","question":"もうそのとおりだと思いますけれども、そういったところの地域ニーズの把握というものをしっかりと取り組んでいただきたいと、これは意見です。お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"}]},{"id":"topic-11","title":"公園における飲料自動販売機の設置","agenda":"公園における飲料自動販売機の設置","exchanges":[{"speaker":"武内委員","kind":"提案","question":"ＡＥＤが１台しかない理由というのは、今、大体ご説明でわかりました。飲み物が提供できますよというのが売りなのかということが１つと、あと入札ではなくて提案型にしたという、その辺の理由について説明を求めました。","respondent":"稲田道路公園課長","answer":"ということで、電光掲示板がついたものではございません。よりよいものを決めていきたいということがございましたので、提案方式で業者からいろいろ聞きまして、決定した次第です。","id":"exchange-061"},{"speaker":"武内委員","kind":"提案","question":"その４社の中で、やはりどうしてもＡＥＤというのは、なかなかできないという考え方はまだ変わっていないんでしょうか。そういう提案があったところはあったんか尋ねました。","respondent":"稲田道路公園課長","answer":"４社とも、やはり屋根つきで温度や風雨等に影響されないところというふうに申しておりました。今後その辺は研究していくということです。","id":"exchange-062"},{"speaker":"大沢委員","kind":"質問","question":"この２０台についてはどのような形で、要は飲んでしまった後のごみ箱はその横に置くんでしょうか。それとも勝手にどこか公園内に捨ててくださいとか、どういうスタンスでこれを考えていますか。","respondent":"稲田道路公園課長","answer":"これは自動販売機の横に必ず回収ボックスを設置するように要綱それから協定等でうたって、必ず設置させていくと。これがあふれたりしないように常に監視して、常時使用可能な状態にしてくださいとか、そういう条件等も一緒にしております。","id":"exchange-063"},{"speaker":"大沢委員","kind":"質問","question":"すみません。ちょっと勉強不足で、これは条例ができているんか尋ねました。","respondent":"稲田道路公園課長","answer":"あります。","id":"exchange-064"},{"speaker":"井上委員","kind":"質問","question":"改善したという状況ではなくて、引き続き同じような状況だと思うんですけれども、それでなぜ今なのかと。何ら変わっているという認識はないんですけれども、それについてどのようにお考えか尋ねました。","respondent":"稲田道路公園課長","answer":"提案の中でお聞きしました節電対策を十分に実施する機械であるとか、節電ももちろん大切です。こちらの公園の事業につきましてもやっていきたいというところもありますので、節電も考慮しながら並行してやらせていきたいです。","id":"exchange-065"},{"speaker":"井上委員","kind":"質問・要望","question":"総合体育館とかでも１回イベントがあったらすぐなくなるくらいで、一斉に使ったら、やはりこの辺は慎重に検討してほしいと求めました。これがよかった、収入が上げられるからという方向で安易に進めていただく事業ではないと思いますので、しっかりご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"大沢委員","kind":"確認","question":"１つだけ確認で、飲んでしまったもののごみ箱の件なんですが、これは、ごみ箱を置くという内容の条例なんか尋ねました。","respondent":"岩田都市環境事業部長","answer":"今、ちょっと手元に条例がありませんが、罰則も何もありませんので、町場のたばこ屋の横にあるような自動販売機のところにはないところが多いということですけれども、今回は公共機関がやりますので、当然のことながらきちんと義務づけているわけです。","id":"exchange-067"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"素朴な疑問なのは、自動販売機を置くその電気代というのはだれが支払うのか、伺いたいと思います。そこも含めてこのジャパンビバレッジ東京がやるのか、それとも別の部隊がやるのか、品川区とどういう関係なのか伺いたいと思います。","respondent":"稲田道路公園課長、岩田都市環境事業部長","answer":"今回試算しますと約３０万５,０００円というところで、回収ボックスも含めた土地の使用料をやってみますと、月１万９,７２１円です。今回は… よく言うんですけれども、日比谷公園の「松本楼」というレストラン、あれも設置管理許可なんですけれども、役所側は何も苦情を言わない。管理を許可する… それから協定は１年なんですけれども、５年間のスパンでこのジャパンビバレッジ東京と考えております。","id":"exchange-068"},{"speaker":"中塚副委員長","kind":"質問・要望","question":"ついでに伺えると、飲み物の種類というのはだれが決めるんでしょうか。ぜひ利用者に沿った中身になったらとは思うんですが、何のジュースを置くのかというのはだれがどう決めるんか尋ねました。","respondent":"稲田道路公園課長","answer":"自動販売機の業者は実績もございまして、一番どういう商品が売れるか、売れる商品を持ってくるのが事業者でございまして、そういう中でジャパンビバレッジ東京は各種多様な商品を取り扱っているというのも提案の一つでございました。","id":"exchange-069"}]},{"id":"topic-12","title":"宮城県女川町災害廃棄物の清掃工場での受入れ","agenda":"宮城県女川町災害廃棄物の清掃工場での受入れ","exchanges":[{"speaker":"井上委員","kind":"質問","question":"この受入量なんですけれども、清掃工場で焼却をするときに普通のごみと混ぜて燃やすということになっていると思うんですけれども、その１５０ｔというのは純粋にそちらの量なのかどうか、ちょっと説明を求めました。","respondent":"太田品川区清掃事務所長","answer":"これは、受入量というのは災害廃棄物を工場で受け入れる限度です。試験焼却のときは、２０％ということで実施いたしましたが、１０％の混載率でやるということになります。","id":"exchange-070"},{"speaker":"大西委員","kind":"質問","question":"住民の方々から主に出ている質問というのはどんなことだったかということと、それに対する答えはどのような内容だったんでしょうか。目ぼしいものだけ説明を求めました。","respondent":"太田品川区清掃事務所長","answer":"清掃工場敷地境界４カ所、東西南北で実施をしています。灰をやった上にさらに５０cmくらい土で覆って、焼却灰、最終処分場においても空間の線量を定期的に計測をしているというような説明をしています。","id":"exchange-071"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/142731?Template=document&Id=4030#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":61037,"voices":262}},{"id":"h24-20120227-9","meetingId":"h24-cm02","date":"2012年2月27日","dateIso":"2012-02-27","committee":"文教委員会","time":"午前１０時００分～午後０時１４分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を53件整理しています。","topics":[{"id":"topic-01","title":"の第３９号議案 品川区立学校施設使用条例の一部を改正する条例","agenda":"の第３９号議案 品川区立学校施設使用条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"順番にお伺いしたいと思います。部活は６時半くらいに終わると伺っているんですけれども、学校にお伺いしたいんですが、そこの大前提のところをもう一度聞きたい。","respondent":"齋藤庶務課長","answer":"土曜日は１日やっております。1)と2)の部分は必ず使うということで設定しています。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"日曜とか祝日は、学校では全く使っていないので貸し出すということなんですか。大もとの基本のところを教えていただきたい。","respondent":"小林青少年育成課長","answer":"今ご説明がございましたように、あるいは学校の使用と特殊な例を除いて、原則的には地域開放の対象としている。現状規定上は４校ほどありますが、とりわけ少年少女スポーツ団体に開放しておりますが、それと同様に実際の運用は考えているところです。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"意見","question":"品川学園の場合は、特殊な例を除いては、地域に開放している。その辺の違いがあるのかどうか、休日とか祝日・日曜がどうなっているのかを、そこの大もとを聞きたかったんですけれどもとの意見を述べました。","respondent":"冠木指導課長","answer":"ですので、施設開放で使えるときについては、積極的に地域の方に開放で使っていただくと。そういった場合については、事前に十分調整をした上で、開放のほうと調整しているということになると思います。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"確認","question":"調節はきちんとして、品川学園だけが一般開放することで、学校に支障があるということはないという受けとめでいいんでしょうか。ちょっと基本的なところなので、そこのところを確認したいと思いますが、いかがか尋ねました。","respondent":"小林青少年育成課長","answer":"先ほどご説明したとおりですが、同じ少年少女スポーツ団体に開放するものではありますが、特殊な事情を抱えている。ただ、原則的には、規定された日時につきましては、地域開放、少年少女スポーツ団体等が行うことが原則と考えたところです。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"教育施設なので、その辺の調節というんですか、事前の十分な理解と調節が大事だと思いますので、その辺はよろしくお願いしたいと思います。この辺の利用料がどうなっているのか教えていただきたいのが１つと、わかったら、ここの調整会議のところをもうちょっと詳しく教えていただきたい。","respondent":"安藤文化スポーツ振興課長、小林青少年育成課長","answer":"そして、使用料ですが、先ほどご説明しました、校庭にはダスト、土の校庭と全天候型があります。だれでも、いろいろな体育館の利用調整ならびに地域の区民の方々へのスポーツの教室とか、そういうものを提供するという組織です。 区内の少年野球の連盟加盟チームは、野球におきましては５３チーム、サッカーについては３０チームと把握しています。使用、活動の計画をして、開放に当たっていく予定です。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問","question":"５ブロックで、ブロックでないところとか、学校で調整するのに担当できないようなところがあるんでしょうか。ちょっとその辺、私は荏原なんですけれども、必ずどこの地域にもスポクラ・しながわができているのかどうか、そこをちょっとお伺いしたい。","respondent":"安藤文化スポーツ振興課長","answer":"品川区全校すべてですけれども、もう昭和５７年から長期基本計画に基づきまして、スポレク推進委員会というものが各地区にでき上がっています。そこで、各地区、各スポレクごとに、体育館ならびに校庭等の利用調整をすべてしています。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"最後、調整会議が終わった後の窓口というのは、どこになるんか尋ねました。","respondent":"安藤文化スポーツ振興課長","answer":"とりあえずすべての学校で調整会議の場で調整します。その後は、直接学校に行って、あいているところを学校に申請するという形になっています。","id":"exchange-007"},{"speaker":"須藤委員","kind":"質問・要望","question":"第一グラウンドの２面と第二グラウンドは、第一グラウンドは別としても、第二グラウンドは授業でそこまで広さを求められるかな。まちの人は使い勝手がいいのではないかと思うんだけれども、その２点、いかがか尋ねました。","respondent":"安藤文化スポーツ振興課長、齋藤庶務課長","answer":"私から１点目の料金の表についてご説明します。この屋内運動場等の説明部分で、備考で、１番と２番の日野学園のものがそこに出ているということです。具体的に申し上げますと、例えば、1)と2)でやっているときに、ほかの学年の子が、屋外スポーツをするということであれば、有効に広さを使いたい。","id":"exchange-008"},{"speaker":"木村委員","kind":"質問","question":"4)のところを貸し出す、何かをすること、変えることは不可能か尋ねました。","respondent":"齋藤庶務課長","answer":"説明がありましたように、この有効な資源を活用してもらいたいということが日曜日の扱いを、少年少女スポーツ団体のために使わせるという方針です。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問","question":"なにか中止に見えるんですけれども、トイレに関しては、学校の１カ所を皆さんが使えるということでしょうか。それを１つだけお伺いしたい。","respondent":"齋藤庶務課長","answer":"ご指摘は倉庫・トイレ棟でしょうか。これは地域開放の方のためにも使えるというトイレです。","id":"exchange-010"},{"speaker":"飯沼委員","kind":"確認","question":"今の木村委員の質問で、地域に開放するということですか、そこのところをもう一回確認したい。","respondent":"齋藤庶務課長","answer":"ＰＴＡの方々に見守りをしていただくという仕組みでしたが、品川学園に限っては、そういう取り扱いはしません。少年少女スポーツ団体の方たちが使うので、ＰＴＡの方たちにお願いして、校庭開放をやる予定はございません。","id":"exchange-011"},{"speaker":"渡部委員","kind":"確認","question":"土曜日に部活等で使用するということで、１、２、３番とも、基本的に土曜日は、逆に少年少女スポーツ団体の開放はなしと考えていいんですか。第１・第３土曜日は午前中授業をやって、第２・第４土曜日に関しては、どういうとらえ方を今考えられているのか。","respondent":"齋藤庶務課長、小林青少年育成課長","answer":"今のご指摘は、多分、第１と第３土曜日は、授業のときは、午前中はいつもと全く同じ使い方になります。 今ご説明のあったとおりですけれども、第一グラウンドは土曜日に使いますので、第二グラウンドのみです。","id":"exchange-012"},{"speaker":"渡部委員","kind":"意見","question":"それと第２・第４土曜日、もしくは日曜日と第２・第４土曜日というのは、全面との意見を述べました。","respondent":"小林青少年育成課長","answer":"お手元の図の1)と2)の部分ですが、部活で、いわゆる学校使用です。第１・第３土曜日、ここは原則どおり、少年少女スポーツ団体で使用するということです。","id":"exchange-013"},{"speaker":"渡部委員","kind":"質問","question":"第２・第４土曜日というのは授業がありません。日曜日と同じ扱いなのかどうなのか、地域活動で第２・第４土曜日は使いますというイメージなのか、そこがちょっとわからないんですけれども。","respondent":"齋藤庶務課長","answer":"3)の第二グラウンドは、土曜日だけお貸しします。今までは午前・午後お貸しするという予定だったんですけれども、授業がある関係で、午後しかお貸ししませんということです。","id":"exchange-014"},{"speaker":"渡部委員","kind":"質問","question":"第１・第３土曜日に関しては、第２・第４土曜日に関しては、第一グラウンドは貸さないというところでよろしいでしょうか。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]},{"id":"topic-02","title":"の第４０号議案 品川区幼稚園条例の一部を改正する条例","agenda":"の第４０号議案 品川区幼稚園条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"ちょっと伺いたいのは、給食の関係で、第一日野幼稚園の幼稚園と台場幼稚園は６００円に該当するということですよね。北品川のすこやか園の御殿山幼稚園はどうなっているのか、幼保一体のところで違いができている中身を具体的に説明を求めました。","respondent":"吉岡保育課長","answer":"４歳、５歳が並行する形になりますので、並列型の幼保一体施設に変更したものです。５歳児という形での設定がありますけれども、保育園の４・５歳児が増えたことによって、給食をなかなか提供できないという状況がそこにきております。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この辺は、選択性なんですか。教えていただきたいのと、預かり保育をやっているところはどこも同じなんですか、おやつは幾らぐらいなんか尋ねました。","respondent":"吉岡保育課長","answer":"キャパシティーの関係で、調理室でつくったものを提供できませんので、市販のものということで考えてあります。こちらは、値段が幾らと、毎回同じ値段でそろえてはございませんけれども、１００円から２００円の間、１００円前後ぐらいかなと考えております。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問","question":"今伺ったら、３歳でお預けになって、今後においては何とか給食の検討は必要であると思います。これは意見を述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]},{"id":"topic-03","title":"平成２４年陳情第４号 保護者夜勤時の子どもショートステイ利用に関する陳情","agenda":"平成２４年陳情第４号 保護者夜勤時の子どもショートステイ利用に関する陳情","exchanges":[{"speaker":"阿久津委員","kind":"質問・要望","question":"突発的ということを伺ったんですけれども、証明書みたいなものを出すということなのかどうかということと、ちょっとまとめてほしい。ここに新宿区の２４時間営業認可保育園、例外はあるのかどうか、そこまで把握していれば教えていただきたいということです。","respondent":"安井子育て支援課長","answer":"それから、ほとんどと申し上げて、申しわけございませんけれども、私が調べました限りでは、定期的なものは認めておりません。そういったことで、全部という形になります。","id":"exchange-019"},{"speaker":"阿久津委員","kind":"質問","question":"夜にぜひお預かりできるような制度は品川区にないんでしょうかと、そういうものがあれば、エントリーしたいというご相談を受けたことがあるんです。ですから、そういう利用法があるかどうか、それについてちょっと伺えればと思います。","respondent":"安井子育て支援課長、吉岡保育課長","answer":"１０時までお預かりするというか、１泊させる、証明みたいなものが必要になりましてやっているというところが実態です。就労支援のために実施している事業ですので、午前８時から午後６時の間の８時間ということで、検討する課題が非常に多かろうと思ってあります。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問","question":"就労支援で、夜間とか、宿泊が必要なケースは当然ありますよね。区はどういった考えを持っていらっしゃるのかということを１つお伺いしたいのと、拡大するお考えがあるのかどうか、そこをちょっと説明を求めました。","respondent":"安井子育て支援課長","answer":"私どもとしては、なるべくどうしてもやむを得ない場合という形で限定的にとらえてご利用いただくということが望ましいものだと考えております。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"意見","question":"２４時間営業の認可保育園があって、夜遅くまで預けるのはどうかというところはもちろんありますけれども、何らかの形で必要だと私は思うんです。何らかの対策がないと、どうにもならないといった現状をどう受けとめているのか、ちょっともう一回そこを聞かせてくださいとの意見を述べました。","respondent":"金子子ども未来事業部長","answer":"その中でも、確かに２４時間保育というのは検討の一つとして考えていたことはあります。こういったニーズにただこたえるべきかどうかというのを絶えず検証しながら、検討はしていきたいと考えています。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"内容をちょっと拡大していけば、現制度でやっていけるのではないかという感触を私は受けたんですけれども、いかがでしょうか。今、子どものショートステイがあるので、ここをぜひ拡大して、受けとめていただきたいと思うんですが、いかがか尋ねました。","respondent":"金子子ども未来事業部長","answer":"それ以外の時間帯でどういうものをしていくのか、子どもにとっての影響はどういうことがあるのか等々、やはり検討すべき課題は非常に多いと思います。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"お母さんは公的なところでやっていただきたいという思いを出していますので、お金も大変ですけれども、ここでつくっていただきたいと私は思います。最後になります、もう一度ご答弁をお願いいたします。","respondent":"金子子ども未来事業部長","answer":"一番重要なのは、子どもにとってどうなのかと、考えることが幾つかあろうかと思います。実施する考えはありませんけれども、時間はかかるかもしれませんが、慎重に検討していく必要はあるかなとは思っております。","id":"exchange-024"},{"speaker":"須藤委員","kind":"質問","question":"このやっていますというのは、どのあたりをどういうふうに、ちゃんとショートステイの形の仕組みをこの区はやっていらっしゃるんですか。それとも、今の品川区のように、在宅支援をベースにした考え方を見せているのか、そのあたりを説明を求めました。","respondent":"安井子育て支援課長","answer":"基本的には、仕事で出張するときということで、定期的な利用はないという意味のことを確認しています。それぞれのセクションで確認していますので、インターネットとかで、ただ制度の概要だけで調べているものではございません。","id":"exchange-025"},{"speaker":"須藤委員","kind":"質問","question":"仕事先もそれを配慮してくれていると私の仲間からも聞いているので、子どもが小さいうちは日勤でずっとやらせてもらっていますと。病院なんかでもそういう話を伺っているので、突発的にどうしてもというときは、そういう仕組みでやっていますというようなお話も伺えているので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"渡部委員","kind":"質問・要望","question":"ですから、この陳情自体の採択ということはないんですけれども、では、果たして不採択なのかと考えたときに、すごく複雑な思いがありました。現に持たれている病院があるのかどうなのか、その辺がわかれば、ちょっと教えていただけますか尋ねました。","respondent":"安井子育て支援課長","answer":"看護師については、社会的に求人が非常に多いということもありまして、大きな病院では、企業内保育の託児所等を備えているところが多いです。９００件とか、そういったものが出てきているというのは、ホームページ等で確認できているところです。","id":"exchange-027"},{"speaker":"渡部委員","kind":"質問・要望","question":"品川区は、ほかの所管になりますけれども、そのようなサービスも始めてきていますので、積極的に働きかけてほしいと求めました。ただ、何らかの形でそういう機関等に働きかけられるような仕組みづくりが必要なのかなと思いまして、お話しさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"須藤委員","kind":"質問・要望","question":"ちょっと１点だけ、これは今うちの担当課ではないんだけれども、関係する課に連絡しておいていただければと思うんです。安心して両方できると思うので、この先を連絡しておいてあげていただきたいというのを、ひとつお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"浅野委員長","kind":"質問","question":"ほかにご発言等、ありますでしょうか。特異なケースというんでしょうか、２４時間はいろいろ考えた経緯はあると伺っていますけれども、ちょっと教えていただけますか。","respondent":"吉岡保育課長","answer":"２４時間保育について直接実施を要望されたという記憶はないんですけれども、中にはそういう希望を持っていらっしゃる方もいらっしゃるかとは思うんですが、特に陳情・請願という形で承ったということはございません。","id":"exchange-030"},{"speaker":"須藤委員","kind":"意見","question":"よろしくお願いします。この陳情については不採択との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"阿久津委員","kind":"意見","question":"研究調査、また前向きに考えていただくことを前提に、不採択としますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"木村委員","kind":"質問","question":"私は反対だったものですから、継続にしたわけですけれども、これからまたあらゆるパターンの方々も出てくると思います。そういうことを考えまして、この方の一生懸命やろうとする姿、会派としてはこれを採択という形にしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"渡部委員","kind":"質問・要望","question":"さまざまな方がいるわけですから、この一個人の方というよりも、区はしっかり考えていかなければいけないんだと思います。時間がかかるかもしれませんが、研究を続けてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"飯沼委員","kind":"意見","question":"共産党としては、社会が今厳しい状況になっている中で、女性の就労を支えていく施策の拡充が大事であると思っています。ぜひ拡大していって、早急に対策をとるべきことと思いますので、採択を主張しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"吉田委員","kind":"意見","question":"行政側も親御さんの身になって考えていただいて、時間はかかるんですが、これから先考えていかなければならない動きの問題だと思っています。３歳のお子さんがいらっしゃると、こういう方々のためにも、ショートステイを考えていったらいいなと私は思いますとの意見を述べました。","respondent":"浅野委員長","answer":"本件は挙手により採決を行います。","id":"exchange-036"}]},{"id":"topic-04","title":"平成２４年陳情第７号 戸越台中学校優先入学に関する陳情","agenda":"平成２４年陳情第７号 戸越台中学校優先入学に関する陳情","exchanges":[{"speaker":"須藤委員","kind":"質問・要望","question":"今年はちょっと伺うと、クラスも３５人学級制とか、形もいろいろ変わってきていますよね。そんなので、今まであんまり声が出なかったことが入っていたのか、そのあたりをちょっと聞かせてほしいと求めました。","respondent":"和氣学務課長","answer":"中学校にしても、今のところ把握している限りでは５００名、去年は７００から８００名いましたので、中学校についても若干減っているのかなと。中学校は東京では３７人ということで規定がありますので、その両方の相乗で、今年度は待機者がかなり増えてしまったという状況です。","id":"exchange-037"},{"speaker":"須藤委員","kind":"意見","question":"今すぐ京陽小学校だけでなくて、絶対的な、どういう仕組みがつくれるんだというものを考えてもらわなければいけないと思う。１つは、ほかでもそういう状況があるのかどうかという点を資料にして、そのあたりの資料を出してほしいと求めました。","respondent":"和氣学務課長","answer":"品川区の就学人口の伸びなんですけれども、東京都２３区平均を大きく上回って、学校のキャパシティーがかなり苦しくなっているということもあります。そういう意味で、そういった資料につきましては、また改めて次回にご提出させていただきたいと考えています。","id":"exchange-038"},{"speaker":"阿久津委員","kind":"質問","question":"連携しているところに行けるんですかという問い合わせがあるのかどうか、そういうことがなかったのかどうか、そういうところを伺ってみたいと思います。","respondent":"和氣学務課長","answer":"説明の際、３校と連携していれば、必ずしもその中学校の学区ではないということもあります。ただ、事前にもう少し丁寧に説明しておくほうがいいのかなというのは考えているところです。","id":"exchange-039"},{"speaker":"阿久津委員","kind":"質問","question":"今後品川区もいろいろお考えがあるようなんですが、一定の考えみたいなものは、大体どのくらいまで考えられているのかを伺います。","respondent":"和氣学務課長","answer":"次の学校選択に反映できませんので、直ちにどうということはございませんが、少なくとも夏までには何らかの結論を出さなければいけないかなと考えています。","id":"exchange-040"},{"speaker":"飯沼委員","kind":"質問・要望","question":"読み方を教えていただきたいんですけれども、４色に分けられていますけれども、これは小学校の学区ですよね。この厳しさをこれからどう改善するのかなと思うんですけれども、連携校の学校の選び方とか、基本的な考え方も説明を求めました。","respondent":"和氣学務課長","answer":"先ほども申し上げたように、中学校にはキャパシティーというのがありますので、それも含めて考えなければそう簡単に結論は出るものではないです。","id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問","question":"さっきちょっとほっとしたのは、戸越台中学校は全員が繰り上がったということなので、あきらめてしまったお子さんはいないんでしょうか。起こった後で改善しますではいけないと思うんですが、そこの大もとのところはいかがか尋ねました。","respondent":"和氣学務課長","answer":"小中一貫教育につきましても、だからこそ全区展開して、だからこそカリキュラムをつくる。いろいろな形の連携をしながら、品川区の中でどう育っていくかということを考えているわけで、そういう説明をさせていただいてきたところです。","id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問","question":"ここの委員会で納得されていらっしゃる方がいても、区民がどうかというところが問題であると私は思います。次の質問をしますけれども、その連携校に行かれないというところで、連携校の意味がどこにあるんだというところを改めてお伺いしたいと思います。","respondent":"和氣学務課長","answer":"連携しながら、小学校、中学校の先生たちがお互いの指導内容とか、指導法を磨き上げて、それぞれのいいところをしっかりとっていこう。中学校でいろいろな教育を展開していって、質の高い教育を、委員の指摘には当たらないと考えています。","id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どのくらいの距離があるかわかっていたら、最長のところはどのくらい距離が離れているのか、教えていただきたい、そこを１個お伺いしたいと思います。早急に見直していただかないと、問題がいっぱいあると思うんですけれども、距離的な問題を説明を求めました。","respondent":"和氣学務課長","answer":"学区との距離でどこが一番遠いのかとは考えてございません。既存の学校がどう連携するというかという問題ですので、その距離を云々されても、ちょっと解決しようがない問題であると考えています。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これから第４ステージで検討されるということは、もちろん検討してもらわないと困るわけですけれども、本当に距離をはかっていないんですか。小学校と中学校の先生が行ったり来たりして、子どもも行ったり来たりして、より効果的にと言っておきながら、距離をはかっていないんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"渡部委員","kind":"質問・要望","question":"質問に入る前に１つ確認させていただきたいのが、仮に日野学園の６年生で、日野学園の７年生に無条件で進学できるんでしたっけ。そこだけ１つ確認させてください。","respondent":"和氣学務課長","answer":"日野中学校の学区域であれば、無条件で。","id":"exchange-046"},{"speaker":"渡部委員","kind":"意見","question":"すみません、聞き方が悪かったですね。小学校に選択制を利用して入られていた場合、無条件で中学校に行けているのか、行けていないのかとの意見を述べました。","respondent":"和氣学務課長","answer":"一貫校の小学校に在籍している方は、全員無条件で行けます。","id":"exchange-047"},{"speaker":"渡部委員","kind":"質問","question":"ですから、これからまた第４ステージに向けて、よりいいものに直してしかるべきものだと思います。今回このようにしてほしいという陳情も出てきているわけですから、今後第４ステージに向かうとき、これもいいタイミングだと思います。","respondent":"和氣学務課長","answer":"連携につきましても、やはりこれまでやっている組み合わせの変わり方もあると思うんですが、どういう形を敷いていくかと考えております。そういうものも含めまして、さまざまな保護者と子どもたちの希望がどうかなえられるかという観点で検討させていただきたいと考えております。","id":"exchange-048"},{"speaker":"渡部委員","kind":"質問・要望","question":"本当にやるとしたら、かけていかなければいけない部分、これは１年や２年でできる話では全くないと思います。今、見直しを始めていただきたいなという思いがあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"須藤委員","kind":"意見","question":"継続で。１回区の実態を見させていただいて、資料をまずもらえたら、継続審議しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"渡部委員","kind":"意見","question":"プラン２１が成熟期に入る中で、いい方向に制度改定はしていくべきだと思います。やはり前向きに継続をしていって、話を続けたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"吉田委員","kind":"意見","question":"私は継続で、子どもたちのために大いに議論していくべきだと思いますので、継続でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"一般質問の無所属の藤原議員の質問に関連して、財政的なことも含めて今後の見通しについての答弁をもうちょっと深めていきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/162678?Template=document&Id=4752#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2012-01-01&TermEnd=2012-12-31"}],"sourceMeta":{"pages":0,"characters":37818,"voices":159}}]);
